module.exports = [{"id":1,"chapter":"导论","type":"single","typeText":"单选题","score":4.0,"question":"2018年3月，( )通过宪法修正案，郑重地把习近平新时代中国特色社会主义思想载入宪法，实现了国家指导思想的与时俱进，反映了全国各族人民的共同意志和全社会的共同意愿。","options":[{"key":"A","text":"党的十八届六中全会"},{"key":"B","text":"十三届全国人大一次会议"},{"key":"C","text":"十四届全国人大三次会议"},{"key":"D","text":"党的十九届六中全会"}],"answer":["B"],"explanation":"2018年3月11日，十三届全国人大一次会议第三次全体会议经投票表决，通过了《中华人民共和国宪法修正案》。"},{"id":2,"chapter":"导论","type":"single","typeText":"单选题","score":4.0,"question":"中国特色社会主义的战略布局是( )。","options":[{"key":"A","text":"\"四个全面\""},{"key":"B","text":"\"十四个坚持\""},{"key":"C","text":"\"十个明确\""},{"key":"D","text":"\"五位一体\""}],"answer":["A"],"explanation":"中国特色社会主义的战略布局是\"四个全面\"战略布局，即全面建设社会主义现代化国家、全面深化改革、全面依法治国、全面从严治党。"},{"id":3,"chapter":"导论","type":"single","typeText":"单选题","score":4.0,"question":"( )明确了习近平同志党中央的核心地位、全党的核心地位。","options":[{"key":"A","text":"党的十九大"},{"key":"B","text":"党的二十大"},{"key":"C","text":"党的十八届六中全会"},{"key":"D","text":"党的十九届六中全会"}],"answer":["C"],"explanation":"党的十八届六中全会正式提出\"以习近平同志为核心的党中央\"，明确了习近平总书记党中央的核心、全党的核心地位。"},{"id":4,"chapter":"导论","type":"single","typeText":"单选题","score":4.0,"question":"党的二十大提出的( )，是习近平新时代中国特色社会主义思想的世界观、方法论和贯穿其中的立场观点方法的重要体现。","options":[{"key":"A","text":"\"六个必须坚持\""},{"key":"B","text":"\"四个意识\""},{"key":"C","text":"\"四个自信\""},{"key":"D","text":"\"两个确立\""}],"answer":["A"],"explanation":"党的二十大报告提出\"六个必须坚持\"，即必须坚持人民至上、必须坚持自信自立、必须坚持守正创新、必须坚持问题导向、必须坚持系统观念、必须坚持胸怀天下。"},{"id":5,"chapter":"导论","type":"single","typeText":"单选题","score":4.0,"question":"( )把习近平新时代中国特色社会主义思想确立为党必须长期坚持的思想并写入党章。","options":[{"key":"A","text":"党的二十大"},{"key":"B","text":"党的十九大"},{"key":"C","text":"党的十八大"},{"key":"D","text":"党的十九届六中全会"}],"answer":["B"],"explanation":"党的十九大把习近平新时代中国特色社会主义思想确立为党必须长期坚持的指导思想并写入党章。"},{"id":6,"chapter":"导论","type":"single","typeText":"单选题","score":4.0,"question":"经过长期努力，中国特色社会主义进入新时代，这是我国发展新的( )。","options":[{"key":"A","text":"历史时期"},{"key":"B","text":"历史地位"},{"key":"C","text":"历史方位"},{"key":"D","text":"历史阶段"}],"answer":["C"],"explanation":"党的十九大报告指出：经过长期努力，中国特色社会主义进入了新时代，这是我国发展新的历史方位。"},{"id":7,"chapter":"导论","type":"single","typeText":"单选题","score":4.0,"question":"( )指出，\"两个确立\"，是党在新时代取得的重大政治成果，对新时代党和国家事业发展、对推进中华民族伟大复兴历史进程具有决定性意义。","options":[{"key":"A","text":"党的十九届六中全会"},{"key":"B","text":"党的十九大"},{"key":"C","text":"党的十八届六中全会"},{"key":"D","text":"党的二十大"}],"answer":["A"],"explanation":"党的十九届六中全会审议通过的《中共中央关于党的百年奋斗重大成就和历史经验的决议》明确指出：\"两个确立\"对新时代党和国家事业发展、对推进中华民族伟大复兴历史进程具有决定性意义。"},{"id":8,"chapter":"导论","type":"single","typeText":"单选题","score":4.0,"question":"党的( )以来，中国特色社会主义进入新时代，以习近平同志为主要代表的中国共产党人，坚持把马克思主义基本原理同中国具体实际相结合、同中华传统文化相结合，创立了习近平新时代中国特色社会主义思想，实现了马克思主义中国化的新飞跃。","options":[{"key":"A","text":"二十大"},{"key":"B","text":"十九大"},{"key":"C","text":"十七大"},{"key":"D","text":"十八大"}],"answer":["D"],"explanation":"党的十八大以来，中国特色社会主义进入新时代，习近平新时代中国特色社会主义思想是马克思主义中国化的最新成果。"},{"id":9,"chapter":"导论","type":"multiple","typeText":"多选题","score":9.7,"question":"习近平新时代中国特色社会主义思想从理论上回答了新时代( )等重大课题，以崭新的思想内容丰富和发展了马克思主义，形成了完整的科学体系。","options":[{"key":"A","text":"建设什么样的社会主义现代化强国、怎样建设社会主义现代化强国"},{"key":"B","text":"坚持和发展什么样的中国特色社会主义文化、怎样建设和发展中国特色社会主义文化"},{"key":"C","text":"建设什么样的长期执政的马克思主义政党、怎样建设长期执政的马克思主义政党"},{"key":"D","text":"坚持和发展什么样的中国特色社会主义、怎样坚持和发展中国特色社会主义"}],"answer":["A","C","D"],"explanation":"习近平新时代中国特色社会主义思想系统回答了新时代坚持和发展什么样的中国特色社会主义、怎样坚持和发展中国特色社会主义，建设什么样的社会主义现代化强国、怎样建设社会主义现代化强国，建设什么样的长期执政的马克思主义政党、怎样建设长期执政的马克思主义政党等重大时代课题。"},{"id":10,"chapter":"导论","type":"multiple","typeText":"多选题","score":9.7,"question":"习近平新时代中国特色社会主义思想是( )，实现了马克思主义中国化新的飞跃。","options":[{"key":"A","text":"二十一世纪马克思主义"},{"key":"B","text":"中华品格和中国力量"},{"key":"C","text":"当代中国马克思主义"},{"key":"D","text":"中华文化和中国精神时代精华"}],"answer":["A","C","D"],"explanation":"习近平新时代中国特色社会主义思想是当代中国马克思主义、二十一世纪马克思主义，是中华文化和中国精神的时代精华。"},{"id":11,"chapter":"导论","type":"multiple","typeText":"多选题","score":9.8,"question":"党的二十大提出的\"六个必须坚持\"，是习近平新时代中国特色社会主义思想的世界观、方法论和贯穿其中的立场观点方法的重要体现。这\"六个必须坚持\"是( )。","options":[{"key":"A","text":"必须坚持理论联系实际"},{"key":"B","text":"必须坚持问题导向"},{"key":"C","text":"必须坚持胸怀天下"},{"key":"D","text":"必须坚持自信自立"},{"key":"E","text":"必须坚持实事求是"},{"key":"F","text":"必须坚持人民至上"},{"key":"G","text":"必须坚持系统观念"},{"key":"H","text":"必须坚持守正创新"}],"answer":["B","C","D","F","G","H"],"explanation":"党的二十大报告提出的\"六个必须坚持\"是：必须坚持人民至上、必须坚持自信自立、必须坚持守正创新、必须坚持问题导向、必须坚持系统观念、必须坚持胸怀天下。"},{"id":12,"chapter":"导论","type":"multiple","typeText":"多选题","score":9.7,"question":"习近平新时代中国特色社会主义思想，是马克思主义基本原理同( )相结合的重大成果，是坚持\"两个结合\"的光辉典范。\"两个结合\"是我们党在探索中国特色社会主义道路中得出的规律性认识，是我们取得成功的最大法宝。","options":[{"key":"A","text":"社会主义文化"},{"key":"B","text":"中华优秀传统文化"},{"key":"C","text":"中国精神"},{"key":"D","text":"中国具体实际"}],"answer":["B","D"],"explanation":"习近平新时代中国特色社会主义思想是坚持\"两个结合\"的光辉典范，即坚持把马克思主义基本原理同中国具体实际相结合、同中华优秀传统文化相结合。"},{"id":13,"chapter":"导论","type":"multiple","typeText":"多选题","score":9.7,"question":"党的十九届六中全会指出，党确立( )，反映了全党全军全国各族人民共同心愿。\"两个确立\"，是党在新时代取得的重大政治成果，对新时代党和国家事业发展、对推进中华民族伟大复兴历史进程具有决定性意义。","options":[{"key":"A","text":"确立习近平同志党中央的核心地位、全党的核心地位"},{"key":"B","text":"确立习近平新时代中国特色社会主义思想的指导地位"},{"key":"C","text":"确立必须坚定\"四个自信\""},{"key":"D","text":"确立必须增强\"四个意识\""}],"answer":["A","B"],"explanation":"党的十九届六中全会提出的\"两个确立\"是指：确立习近平同志党中央的核心、全党的核心地位，确立习近平新时代中国特色社会主义思想的指导地位。"},{"id":14,"chapter":"导论","type":"multiple","typeText":"多选题","score":9.7,"question":"习近平新时代中国特色社会主义思想内涵十分丰富，党的十九大、十九届六中全会提出的( )概括了习近平新时代中国特色社会主义的主要内容。","options":[{"key":"A","text":"\"十三个方面的成就\""},{"key":"B","text":"\"十四个坚持\""},{"key":"C","text":"\"十一个方面的成就\""},{"key":"D","text":"\"十个明确\""}],"answer":["A","B","D"],"explanation":"党的十九大报告提出的\"八个明确\"和\"十四个坚持\"，党的十九届六中全会进一步概括为\"十个明确\"，并总结了新时代党和国家事业取得的\"十三个方面历史性成就\"。"},{"id":15,"chapter":"导论","type":"multiple","typeText":"多选题","score":9.7,"question":"全面系统学习领会习近平新时代中国特色社会主义思想，对青年大学生( )具有十分重要的意义。","options":[{"key":"A","text":"认识改革开放"},{"key":"B","text":"认识我们所处的时代"},{"key":"C","text":"认识在创新理论指导下党和国家事业发展"},{"key":"D","text":"认识新时代党的理论创新"}],"answer":["B","C","D"],"explanation":"学习习近平新时代中国特色社会主义思想有助于青年大学生正确认识时代、认识党和国家事业发展、认识党的理论创新成果。"},{"id":101,"chapter":"第一章 新时代坚持和发展中国特色社会主义","type":"single","typeText":"单选题","score":4.5,"question":"坚定中国特色社会主义道路自信、理论自信、制度自信，说到底是要坚定( )","options":[{"key":"A","text":"政治自信"},{"key":"B","text":"历史自信"},{"key":"C","text":"战略自信"},{"key":"D","text":"文化自信"}],"answer":["D"],"explanation":"文化自信是更基础、更广泛、更深厚的自信，是道路自信、理论自信、制度自信的根本和源泉。"},{"id":102,"chapter":"第一章 新时代坚持和发展中国特色社会主义","type":"single","typeText":"单选题","score":4.5,"question":"( )宣布，中国特色社会主义进入了新时代，这是我国发展新的历史方位。","options":[{"key":"A","text":"党的十七大"},{"key":"B","text":"党的十八大"},{"key":"C","text":"党的十九大"},{"key":"D","text":"党的二十大"}],"answer":["C"],"explanation":"党的十九大报告明确作出了“中国特色社会主义进入了新时代”的重大政治判断。"},{"id":103,"chapter":"第一章 新时代坚持和发展中国特色社会主义","type":"single","typeText":"单选题","score":4.5,"question":"中国特色社会主义进入新时代，这是我国发展新的( )","options":[{"key":"A","text":"历史维度"},{"key":"B","text":"战略方向"},{"key":"C","text":"战略格局"},{"key":"D","text":"历史方位"}],"answer":["D"],"explanation":"进入新时代，是我国发展新的历史方位，意味着中华民族迎来了从站起来、富起来到强起来的伟大飞跃。"},{"id":104,"chapter":"第一章 新时代坚持和发展中国特色社会主义","type":"single","typeText":"单选题","score":4.5,"question":"中国特色社会主义进入新时代重大判断的基本依据是( )","options":[{"key":"A","text":"我国社会主要矛盾发生新变化"},{"key":"B","text":"党的主要任务发生新变化"},{"key":"C","text":"中国和世界关系发生新变化"},{"key":"D","text":"发展理念和思路发生新变化"}],"answer":["A"],"explanation":"我国社会主要矛盾已经转化为人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾，这是中国特色社会主义进入新时代的基本依据。"},{"id":105,"chapter":"第一章 新时代坚持和发展中国特色社会主义","type":"single","typeText":"单选题","score":4.5,"question":"在新中国成立特别是改革开放以来取得重大成就的基础上,我国发展站在了新的历史起点上，社会主要矛盾已由人民日益增长的物质文化需要同落后的社会生产之间的矛盾，转化为( )。","options":[{"key":"A","text":"人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾"},{"key":"B","text":"人民日益增长的美好生活需要和不充分不平衡的发展之间的矛盾"},{"key":"C","text":"人民日益增长的幸福生活需要和不充分不平衡的发展之间的矛盾"},{"key":"D","text":"人民日益增长的幸福生活需要和不平衡不充分的发展之间的矛盾"}],"answer":["A"],"explanation":"党的十九大报告明确指出，我国社会主要矛盾已经转化为人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾。"},{"id":106,"chapter":"第一章 新时代坚持和发展中国特色社会主义","type":"single","typeText":"单选题","score":4.5,"question":"( )是更基础、更广泛、更深厚的自信，是一个国家、一个民族发展中最基本、最深沉、最持久的力量。","options":[{"key":"A","text":"道路自信"},{"key":"B","text":"理论自信"},{"key":"C","text":"制度自信"},{"key":"D","text":"文化自信"}],"answer":["D"],"explanation":"文化自信是更基础、更广泛、更深厚的自信，是中华民族独特的精神标识和持久力量。"},{"id":107,"chapter":"第一章 新时代坚持和发展中国特色社会主义","type":"single","typeText":"单选题","score":4.5,"question":"新时代我国社会主要矛盾的变化，是在社会主义初级阶段中发生的变化，( )对我国社会主义所处历史阶段的判断。","options":[{"key":"A","text":"正在进行"},{"key":"B","text":"未能进行"},{"key":"C","text":"已经改变"},{"key":"D","text":"没有改变"}],"answer":["D"],"explanation":"我国社会主要矛盾的变化，没有改变我们对我国社会主义所处历史阶段的判断，我国仍处于并将长期处于社会主义初级阶段。"},{"id":108,"chapter":"第一章 新时代坚持和发展中国特色社会主义","type":"single","typeText":"单选题","score":4.5,"question":"( )是坚持和发展中国特色社会主义的行动指南。","options":[{"key":"A","text":"党的基本路线"},{"key":"B","text":"党的基本理论"},{"key":"C","text":"党的基本方略"},{"key":"D","text":"党的基本政策"}],"answer":["B"],"explanation":"党的基本理论是坚持和发展中国特色社会主义的行动指南，包括马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观、习近平新时代中国特色社会主义思想等。"},{"id":109,"chapter":"第一章 新时代坚持和发展中国特色社会主义","type":"single","typeText":"单选题","score":4.5,"question":"( )是国家的生命线、人民的幸福线。","options":[{"key":"A","text":"党的基本路线"},{"key":"B","text":"党的基本理论"},{"key":"C","text":"党的基本方略"},{"key":"D","text":"党的基本政策"}],"answer":["A"],"explanation":"党的基本路线是党和国家的生命线、人民的幸福线，必须长期坚持、永不动摇。"},{"id":110,"chapter":"第一章 新时代坚持和发展中国特色社会主义","type":"single","typeText":"单选题","score":4.5,"question":"( )是新时代条件下坚持和发展中国特色社会主义、推进改革开放和社会主义现代化建设战略抉择","options":[{"key":"A","text":"十个明确"},{"key":"B","text":"十四个坚持"},{"key":"C","text":"五位一体"},{"key":"D","text":"四个全面"}],"answer":["D"],"explanation":"“四个全面”战略布局（全面建设社会主义现代化国家、全面深化改革、全面依法治国、全面从严治党）是新时代坚持和发展中国特色社会主义的战略布局。"},{"id":111,"chapter":"第一章 新时代坚持和发展中国特色社会主义","type":"single","typeText":"单选题","score":4.5,"question":"中国特色社会主义，既坚持了( )基本原则，又根据时代条件赋予其鲜明的中国特色，以全新的视野深化了对共产党执政规律、社会主义建设规律、人类社会发展规律的认识，","options":[{"key":"A","text":"唯物辩证主义"},{"key":"B","text":"科学社会主义"},{"key":"C","text":"历史唯物主义"},{"key":"D","text":"辩证唯物主义"}],"answer":["B"],"explanation":"中国特色社会主义，既坚持了科学社会主义基本原则，又根据时代条件赋予其鲜明的中国特色，是科学社会主义理论逻辑和中国社会发展历史逻辑的辩证统一。"},{"id":112,"chapter":"第一章 新时代坚持和发展中国特色社会主义","type":"multiple","typeText":"多选题","score":5.5,"question":"中国特色社会主义是( )。","options":[{"key":"A","text":"在改革开放40多年的伟大实践中得来的"},{"key":"B","text":"在新中国成立70多年的持续探索中得来的"},{"key":"C","text":"在中国共产党领导人民进行伟大社会革命100多年的实践中得来的"},{"key":"D","text":"在近代以来中华民族由衰到盛180多年的历史进程中得来的"}],"answer":["A","B","C","D"],"explanation":"中国特色社会主义是在改革开放40多年的伟大实践中得来的，在新中国成立70多年的持续探索中得来的，在我们党领导人民进行伟大社会革命100年的实践中得来的，在近代以来中华民族由衰到盛180多年的历史进程中得来的，是对中华文明5000多年的传承发展中得来的。"},{"id":113,"chapter":"第一章 新时代坚持和发展中国特色社会主义","type":"multiple","typeText":"多选题","score":5.0,"question":"中国特色社会主义坚持科学社会主义基本原则，并赋予其鲜明的中国特色,包括( )。","options":[{"key":"A","text":"坚持人民代表大会制度的根本政治制度"},{"key":"B","text":"中国共产党领导的多党合作和政治协商制度"},{"key":"C","text":"坚持公有制为主体多种所有制经济共同发展"},{"key":"D","text":"坚持按劳分配为主体多种分配方式并存"}],"answer":["A","B","C","D"],"explanation":"中国特色社会主义在政治制度上实行人民代表大会制度、中国共产党领导的多党合作和政治协商制度等；在经济制度上实行公有制为主体、多种所有制经济共同发展，按劳分配为主体、多种分配方式并存。这些都是科学社会主义基本原则与中国实际相结合的具体体现。"},{"id":114,"chapter":"第一章 新时代坚持和发展中国特色社会主义","type":"multiple","typeText":"多选题","score":5.0,"question":"改革开放以来，我们取得一切成绩和进步的根本原因，就是( )。","options":[{"key":"A","text":"开辟了中国特色社会主义道路"},{"key":"B","text":"形成了中国特色社会主义理论体系"},{"key":"C","text":"确立了中国特色社会主义制度"},{"key":"D","text":"发展了中国特色社会主义文化。"}],"answer":["A","B","C","D"],"explanation":"改革开放以来我们取得一切成绩和进步的根本原因，归结起来就是：开辟了中国特色社会主义道路，形成了中国特色社会主义理论体系，确立了中国特色社会主义制度，发展了中国特色社会主义文化。"},{"id":115,"chapter":"第一章 新时代坚持和发展中国特色社会主义","type":"multiple","typeText":"多选题","score":5.0,"question":"习近平指出:\"中国特色社会主义，承载着几代中国共产党人的理想和探索，寄托着无数仁人志士的意愿和期盼,凝聚着千千万万革命先烈的奋斗和牺牲，凝聚着全国各族人民的奋斗和实践，是近代以来，是( )\"","options":[{"key":"A","text":"中国社会发展的必然选择"},{"key":"B","text":"历史和人民的选择"},{"key":"C","text":"中国道路的必然选择"},{"key":"D","text":"社会进步发展的选择"}],"answer":["A","B"],"explanation":"中国特色社会主义是党和人民历经千辛万苦、付出巨大代价取得的根本成就，是中国社会发展的必然选择，是历史和人民的选择。"},{"id":116,"chapter":"第一章 新时代坚持和发展中国特色社会主义","type":"multiple","typeText":"多选题","score":5.0,"question":"中国特色社会主义进入了新时代的判断，是( )","options":[{"key":"A","text":"基于我国发展进入新阶段的伟大成就"},{"key":"B","text":"基于社会主要矛盾发生新变化"},{"key":"C","text":"基于党的新的奋斗目标"},{"key":"D","text":"基于我国面临新的国际环境"}],"answer":["A","B","C","D"],"explanation":"中国特色社会主义进入新时代，是基于我国发展取得的历史性成就和历史性变革、社会主要矛盾的变化、党的奋斗目标（两个一百年）以及国际环境深刻变化等作出的科学判断。"},{"id":117,"chapter":"第一章 新时代坚持和发展中国特色社会主义","type":"multiple","typeText":"多选题","score":5.0,"question":"中国特色社会主义新时代，( )","options":[{"key":"A","text":"是承前启后、继往开来，在新的历史条件下继续夺取中国特色社会主义伟大胜利的时代。"},{"key":"B","text":"是决胜全面建成小康社会、进而全面建设社会主义现代化强国的时代。"},{"key":"C","text":"是全国各族人民团结奋斗、不断创造美好生活、逐步实现全体人民共同富裕的时代。"},{"key":"D","text":"全体中华儿女勠力同心、奋力实现中华民族伟大复兴中国梦的时代。"}],"answer":["A","B","C","D"],"explanation":"这是党的十九大报告对中国特色社会主义新时代内涵的全面概括，涵盖了历史方位、奋斗目标、人民生活和民族复兴等多个维度。"},{"id":118,"chapter":"第一章 新时代坚持和发展中国特色社会主义","type":"multiple","typeText":"多选题","score":5.0,"question":"党的十九大概括中国特色社会主义进入新时代的重大意义,这就是( )","options":[{"key":"A","text":"意味着中华民族迎来了从站起来、富起来到强起来的伟大飞跃，迎来了中华民族伟大复兴的光明前景。"},{"key":"B","text":"意味着科学社会主义在中国焕发出强大生机活力，在世界上高高举起了中国特色社会主义伟大旗帜"},{"key":"C","text":"意味着中国特色社会主义道路、理论、制度、文化不断发展，拓展了发展中国家实现现代化的途径"},{"key":"D","text":"意味着中国即将建成社会主义现代化强国，全体人民过上共同富裕的生活。"}],"answer":["A","B","C"],"explanation":"党的十九大报告阐述了中国特色社会主义进入新时代的三个“意味着”。选项D表述不准确，建成社会主义现代化强国和全体人民共同富裕是未来的目标，并非“进入新时代”本身直接意味着“即将建成”。"},{"id":119,"chapter":"第一章 新时代坚持和发展中国特色社会主义","type":"multiple","typeText":"多选题","score":5.0,"question":"我国社会主要矛盾的变化( )。","options":[{"key":"A","text":"没有改变我们对我国社会主义所处历史阶段的判断"},{"key":"B","text":"我国仍处于并将长期处于社会主义初级阶段的基本国情没有变"},{"key":"C","text":"我国是世界最大发展中国家的国际地位没有变"},{"key":"D","text":"以上都正确"}],"answer":["A","B","C","D"],"explanation":"社会主要矛盾的变化，没有改变我们对我国社会主义所处历史阶段的判断，我国仍处于并将长期处于社会主义初级阶段的基本国情没有变，我国是世界最大发展中国家的国际地位没有变。"},{"id":120,"chapter":"第一章 新时代坚持和发展中国特色社会主义","type":"multiple","typeText":"多选题","score":5.0,"question":"进入新时代，以习近平同志为核心的党中央准确把握我国发展新的历史方位，不断深化对中国特色社会主义建设规律的认识，......解决了许多长期想解决而没有解决的难题，办成了许多过去想办而没有办成的大事，党和国家事业( ),推动我国迈上全面建设社会主义现代化国家新征程。","options":[{"key":"A","text":"实现历史性跨越"},{"key":"B","text":"取得历史性成就"},{"key":"C","text":"发生历史性变革"},{"key":"D","text":"创造历史性发展"}],"answer":["B","C"],"explanation":"党的十九大报告指出：“党的十八大以来，党和国家事业取得历史性成就、发生历史性变革。”这是对新时代伟大实践的高度概括。"},{"id":121,"chapter":"第一章 新时代坚持和发展中国特色社会主义","type":"multiple","typeText":"多选题","score":5.0,"question":"党的( )事关党的前途命运,事关中国特色社会主义事业兴衰成败。","options":[{"key":"A","text":"基本理论"},{"key":"B","text":"基本路线"},{"key":"C","text":"基本方略"},{"key":"D","text":"基本方针"}],"answer":["A","B","C"],"explanation":"党的基本理论、基本路线、基本方略是管全局、管根本、管方向、管长远的，是党的行动纲领，必须全面贯彻、长期坚持。"},{"id":16,"chapter":"第二章 以中国式现代化全面推进中华民族伟大复兴","type":"single","typeText":"单选题","score":5.0,"question":"( )，是近代以来中国人民的共同梦想，是中国共产党矢志不渝的奋斗目标。","options":[{"key":"A","text":"社会主义现代化建设"},{"key":"B","text":"中国特色社会主义"},{"key":"C","text":"国家富强民族振兴"},{"key":"D","text":"实现中华民族伟大复兴"}],"answer":["D"],"explanation":"实现中华民族伟大复兴是近代以来中华民族最伟大的梦想，是中国共产党矢志不渝的奋斗目标。"},{"id":17,"chapter":"第二章 以中国式现代化全面推进中华民族伟大复兴","type":"single","typeText":"单选题","score":5.0,"question":"习近平指出:\"一百年来，中国共产党团结带领中国人民进行的一切奋斗、一切牺牲、一切创造，归结起来就是一个主题:( )。\"","options":[{"key":"A","text":"实现中华民族伟大复兴"},{"key":"B","text":"走中国特色社会主义道路"},{"key":"C","text":"促进人的全面发展"},{"key":"D","text":"坚持中国共产党领导"}],"answer":["A"],"explanation":"习近平总书记在庆祝中国共产党成立100周年大会上指出：一百年来，中国共产党团结带领中国人民进行的一切奋斗、一切牺牲、一切创造，归结起来就是一个主题：实现中华民族伟大复兴。"},{"id":18,"chapter":"第二章 以中国式现代化全面推进中华民族伟大复兴","type":"single","typeText":"单选题","score":5.0,"question":"( )，习近平在庆祝中国共产党成立100周年大会上庄严宣告:\"经过全党全国各族人民持续奋斗，我们实现了第一个百年奋斗目标，在中华大地上全面建成了小康社会，历史性地解决了绝对贫困问题，正在意气风发向着全面建成社会主义现代化强国的第二个百年奋斗目标迈进。\"","options":[{"key":"A","text":"2018年7月1日"},{"key":"B","text":"2019年7月1日"},{"key":"C","text":"2021年7月1日"},{"key":"D","text":"2022年7月1日"}],"answer":["C"],"explanation":"2021年7月1日，习近平总书记在庆祝中国共产党成立100周年大会上庄严宣告：我们实现了第一个百年奋斗目标，在中华大地上全面建成了小康社会。"},{"id":19,"chapter":"第二章 以中国式现代化全面推进中华民族伟大复兴","type":"single","typeText":"单选题","score":5.0,"question":"( )，标志着第一个百年奋斗目标胜利实现，国家更富强、人民更幸福、社会更稳定、环境更优美，人民获得感幸福感安全感显著提升，中华民族实现了从大幅落后于时代到大踏步赶上时代的新跨越。","options":[{"key":"A","text":"打赢脱贫攻坚战"},{"key":"B","text":"成为世界第二大经济体"},{"key":"C","text":"中国特色社会主义进入新时代"},{"key":"D","text":"如期全面建成小康社会"}],"answer":["D"],"explanation":"如期全面建成小康社会标志着第一个百年奋斗目标的胜利实现，是我国发展史上的重要里程碑。"},{"id":20,"chapter":"第二章 以中国式现代化全面推进中华民族伟大复兴","type":"single","typeText":"单选题","score":5.0,"question":"摆脱贫困一直是困扰全球发展和治理的突出难题，我国提前( )实现联合国2030年可持续发展议程减贫目标。","options":[{"key":"A","text":"10年"},{"key":"B","text":"15年"},{"key":"C","text":"20年"},{"key":"D","text":"25年"}],"answer":["A"],"explanation":"中国提前10年实现联合国2030年可持续发展议程减贫目标，对全球减贫贡献率超过70%。"},{"id":21,"chapter":"第二章 以中国式现代化全面推进中华民族伟大复兴","type":"single","typeText":"单选题","score":5.0,"question":"党的二十大进一步明确了全面建成社会主义现代化强国的战略安排，把基本实现社会主义现代化的时间提前了( )年。","options":[{"key":"A","text":"10年"},{"key":"B","text":"15年"},{"key":"C","text":"20年"},{"key":"D","text":"25年"}],"answer":["B"],"explanation":"党的二十大报告提出：到2035年基本实现社会主义现代化，比原先规划提前了15年。"},{"id":22,"chapter":"第二章 以中国式现代化全面推进中华民族伟大复兴","type":"single","typeText":"单选题","score":5.0,"question":"( )把我国建成富强民主文明和谐美丽的社会主义现代化强国。","options":[{"key":"A","text":"从2020年到2035年"},{"key":"B","text":"从2020年到2045年"},{"key":"C","text":"从2035年到2050年"},{"key":"D","text":"从2035年到本世纪中叶"}],"answer":["D"],"explanation":"从2035年到本世纪中叶，在基本实现现代化的基础上，把我国建成富强民主文明和谐美丽的社会主义现代化强国。"},{"id":23,"chapter":"第二章 以中国式现代化全面推进中华民族伟大复兴","type":"single","typeText":"单选题","score":5.0,"question":"孙中山领导辛亥革命试图以建立资产阶级共和国、振兴实业等方案来实现现代化，他的( )被称为近代中国谋求现代化的第一份蓝图。","options":[{"key":"A","text":"《建国方略》"},{"key":"B","text":"《现代化之路》"},{"key":"C","text":"《中国方案》"},{"key":"D","text":"《振兴中华》"}],"answer":["A"],"explanation":"孙中山先生的《建国方略》被称为近代中国谋求现代化的第一份蓝图，提出了许多宏伟设想。"},{"id":24,"chapter":"第二章 以中国式现代化全面推进中华民族伟大复兴","type":"single","typeText":"单选题","score":5.0,"question":"进入新时代，我们党成功推进和拓展了中国式现代化，为中国式现代化提供了( )。","options":[{"key":"A","text":"根本社会条件"},{"key":"B","text":"根本政治前提和制度基础"},{"key":"C","text":"更为完善的制度保证、更为坚实的物质基础、更为主动的精神力量"},{"key":"D","text":"充满新的活力的体制保证和快速发展的物质条件"}],"answer":["C"],"explanation":"新时代为中国式现代化提供了更为完善的制度保证、更为坚实的物质基础、更为主动的精神力量。"},{"id":25,"chapter":"第二章 以中国式现代化全面推进中华民族伟大复兴","type":"single","typeText":"单选题","score":5.0,"question":"( )决定中国式现代化的根本性质。","options":[{"key":"A","text":"党的领导"},{"key":"B","text":"人民当家作主"},{"key":"C","text":"依法治国"},{"key":"D","text":"中国特色社会主义"}],"answer":["A"],"explanation":"党的领导决定中国式现代化的根本性质，只有坚持党的领导，中国式现代化才能前景光明、繁荣兴盛。"},{"id":26,"chapter":"第二章 以中国式现代化全面推进中华民族伟大复兴","type":"single","typeText":"单选题","score":5.0,"question":"( )是推进现代化最坚实的根基、最深厚的力量。","options":[{"key":"A","text":"文化"},{"key":"B","text":"中国共产党的领导"},{"key":"C","text":"人民"},{"key":"D","text":"中华文明"}],"answer":["C"],"explanation":"人民是历史的创造者，是推进现代化最坚实的根基、最深厚的力量。"},{"id":27,"chapter":"第二章 以中国式现代化全面推进中华民族伟大复兴","type":"single","typeText":"单选题","score":5.0,"question":"( )是中华民族精神之魂，是我们立党立国的重要原则。","options":[{"key":"A","text":"文化自信"},{"key":"B","text":"人民至上"},{"key":"C","text":"社会主义制度"},{"key":"D","text":"独立自主"}],"answer":["D"],"explanation":"独立自主是中华民族精神之魂，是我们立党立国的重要原则，也是中国式现代化必须坚持的重大原则。"},{"id":28,"chapter":"第二章 以中国式现代化全面推进中华民族伟大复兴","type":"single","typeText":"单选题","score":5.0,"question":"( )是中国共产党和中国人民最显著的精神标识，是中国人民创造历史伟业的必由之路。","options":[{"key":"A","text":"自力更生"},{"key":"B","text":"团结奋斗"},{"key":"C","text":"斗争精神"},{"key":"D","text":"中国精神"}],"answer":["B"],"explanation":"团结奋斗是中国共产党和中国人民最显著的精神标识，是创造历史伟业的必由之路。"},{"id":29,"chapter":"第二章 以中国式现代化全面推进中华民族伟大复兴","type":"single","typeText":"单选题","score":5.0,"question":"中国式现代化，深深植根于( )，体现科学社会主义的先进本质，借鉴吸收一切人类优秀文明成果，代表人类文明进步的发展方向，是一种全新的人类文明形态。","options":[{"key":"A","text":"中华五千年灿烂文明"},{"key":"B","text":"中华优秀传统文化"},{"key":"C","text":"科学社会主义"},{"key":"D","text":"中国特色社会主义"}],"answer":["B"],"explanation":"中国式现代化深深植根于中华优秀传统文化，体现了中华文明的深厚底蕴。"},{"id":30,"chapter":"第二章 以中国式现代化全面推进中华民族伟大复兴","type":"multiple","typeText":"多选题","score":5.0,"question":"新时代新征程中国共产党的中心任务，就是团结带领全国各族人民、( )，以中国式现代化全面推进中华民族伟大复兴。","options":[{"key":"A","text":"全面建成社会主义现代化强国"},{"key":"B","text":"实现第一个百年奋斗目标"},{"key":"C","text":"实现第二个百年奋斗目标"},{"key":"D","text":"全面建成社会主义现代化国家"}],"answer":["A","C"],"explanation":"党的二十大报告指出：从现在起，中国共产党的中心任务就是团结带领全国各族人民全面建成社会主义现代化强国、实现第二个百年奋斗目标，以中国式现代化全面推进中华民族伟大复兴。"},{"id":31,"chapter":"第二章 以中国式现代化全面推进中华民族伟大复兴","type":"multiple","typeText":"多选题","score":5.0,"question":"实现中华民族伟大复兴的中国梦，本质是( )。","options":[{"key":"A","text":"国家富强"},{"key":"B","text":"民族振兴"},{"key":"C","text":"人民幸福"},{"key":"D","text":"世界大同"}],"answer":["A","B","C"],"explanation":"中华民族伟大复兴的中国梦，基本内涵是实现国家富强、民族振兴、人民幸福。"},{"id":32,"chapter":"第二章 以中国式现代化全面推进中华民族伟大复兴","type":"multiple","typeText":"多选题","score":5.0,"question":"我们要统揽( )，勠力同心、接力奋斗，用实干托起中国梦。","options":[{"key":"A","text":"伟大斗争"},{"key":"B","text":"伟大工程"},{"key":"C","text":"伟大事业"},{"key":"D","text":"伟大梦想"}],"answer":["A","B","C","D"],"explanation":"实现中华民族伟大复兴的中国梦，必须进行伟大斗争、建设伟大工程、推进伟大事业、实现伟大梦想。"},{"id":33,"chapter":"第二章 以中国式现代化全面推进中华民族伟大复兴","type":"multiple","typeText":"多选题","score":5.0,"question":"中国式现代化是中国共产党领导的社会主义现代化，这是对中国式现代化的定性，是( )的。","options":[{"key":"A","text":"管总"},{"key":"B","text":"管根本"},{"key":"C","text":"管长远"},{"key":"D","text":"管大局"}],"answer":["A","B"],"explanation":"中国共产党领导是中国式现代化的最本质特征和最大优势，是对中国式现代化定性的管总、管根本的问题。"},{"id":34,"chapter":"第二章 以中国式现代化全面推进中华民族伟大复兴","type":"multiple","typeText":"多选题","score":5.0,"question":"推进中国式现代化需要牢牢把握的重大原则是( )。","options":[{"key":"A","text":"坚持和加强党的全面领导"},{"key":"B","text":"坚持中国特色社会主义道路"},{"key":"C","text":"坚持以人民为中心的发展思想"},{"key":"D","text":"坚持深化改革开放，坚持发扬斗争精神"}],"answer":["A","B","C","D"],"explanation":"推进中国式现代化需要牢牢把握的重大原则包括：坚持和加强党的全面领导、坚持中国特色社会主义道路、坚持以人民为中心的发展思想、坚持深化改革开放、坚持发扬斗争精神。"},{"id":35,"chapter":"第二章 以中国式现代化全面推进中华民族伟大复兴","type":"multiple","typeText":"多选题","score":5.0,"question":"推进中国式现代化，必须坚持( )，坚持道不变、志不改，既不走封闭僵化的老路，也不走改旗易帜的邪路，始终坚持和发展中国特色社会主义。","options":[{"key":"A","text":"以经济建设为中心"},{"key":"B","text":"坚持四项基本原则"},{"key":"C","text":"坚持改革开放"},{"key":"D","text":"坚持独立自主、自力更生"}],"answer":["A","B","C","D"],"explanation":"推进中国式现代化必须坚持党的基本路线，即以经济建设为中心，坚持四项基本原则，坚持改革开放，同时要坚持独立自主、自力更生。"},{"id":301,"chapter":"第三章 坚持党的全面领导","type":"single","typeText":"单选题","score":1.0,"question":"( )是坚持和发展中国特色社会主义的必由之路。","options":[{"key":"A","text":"团结奋斗"},{"key":"B","text":"坚持党的全面领导"},{"key":"C","text":"贯彻新发展理念"},{"key":"D","text":"全面从严治党"}],"answer":["B"],"explanation":"坚持党的全面领导是坚持和发展中国特色社会主义的必由之路，只有坚持和加强党的全面领导，才能确保中国特色社会主义事业始终沿着正确方向前进。"},{"id":302,"chapter":"第三章 坚持党的全面领导","type":"single","typeText":"单选题","score":1.0,"question":"中国特色社会主义事业始终充满生机活力的根本原因是( )。","options":[{"key":"A","text":"中国共产党运用马克思主义及时科学解答时代新课题，不断推进马克思主义中国化时代化"},{"key":"B","text":"中国共产党是中国工人阶级的先锋队，同时是中国人民和中华民族的先锋队"},{"key":"C","text":"中国共产党具有广泛坚实的阶级基础、群众基础和社会基础"},{"key":"D","text":"党经受了长期历史考验和血与火的洗礼，形成了思想高度统一、组织体系严密、组织纪律严明的统一整体"}],"answer":["A"],"explanation":"中国共产党不断推进马克思主义中国化时代化，科学解答时代课题，是中国特色社会主义事业充满生机活力的根本原因。"},{"id":303,"chapter":"第三章 坚持党的全面领导","type":"single","typeText":"单选题","score":1.0,"question":"习近平指出:\"一定要认清，中国最大的国情就是( )。什么是中国特色?这就是中国特色。\"","options":[{"key":"A","text":"现在处于并将长期处于社会主义初级阶段"},{"key":"B","text":"中国共产党的领导"},{"key":"C","text":"仅用几十年时间就走完发达国家几百年走过的工业化历程"},{"key":"D","text":"中国特色社会主义"}],"answer":["B"],"explanation":"中国共产党的领导是中国特色社会主义最本质的特征，是中国最大的国情，也是中国特色社会主义的最大特色。"},{"id":304,"chapter":"第三章 坚持党的全面领导","type":"single","typeText":"单选题","score":1.0,"question":"坚持和加强党的全面领导，使党的政治领导力、思想引领力、群众组织力、社会号召力显著增强。( )是马克思主义政党第一位的能力。","options":[{"key":"A","text":"政治领导力"},{"key":"B","text":"思想引领力"},{"key":"C","text":"群众组织力"},{"key":"D","text":"社会号召力"}],"answer":["A"],"explanation":"政治领导力是马克思主义政党第一位的能力，关系到党的政治方向和政治原则。"},{"id":305,"chapter":"第三章 坚持党的全面领导","type":"single","typeText":"单选题","score":2.0,"question":"( )是党的领导的最高原则，是党保持团结统一和强大战斗力的关键所在。","options":[{"key":"A","text":"民主集中制"},{"key":"B","text":"党中央集中统一领导"},{"key":"C","text":"群众路线"},{"key":"D","text":"实事求是"}],"answer":["B"],"explanation":"党中央集中统一领导是党的领导的最高原则，是党保持团结统一和强大战斗力的关键所在。"},{"id":306,"chapter":"第三章 坚持党的全面领导","type":"single","typeText":"单选题","score":2.0,"question":"维护党中央权威和集中统一领导，最关键的是( )。","options":[{"key":"A","text":"坚决维护习近平同志党中央的核心、全党的核心地位"},{"key":"B","text":"实行民主集中制"},{"key":"C","text":"修改党章，加强党中央权力"},{"key":"D","text":"严明政治纪律"}],"answer":["A"],"explanation":"维护党中央权威和集中统一领导，最关键的是坚决维护习近平总书记党中央的核心、全党的核心地位。"},{"id":307,"chapter":"第三章 坚持党的全面领导","type":"single","typeText":"单选题","score":2.0,"question":"中国共产党是以( )为根本组织原则和领导制度。","options":[{"key":"A","text":"群众路线"},{"key":"B","text":"民主集中制"},{"key":"C","text":"党章"},{"key":"D","text":"政治纪律"}],"answer":["B"],"explanation":"民主集中制是党的根本组织原则和领导制度，是马克思主义政党区别于其他政党的重要标志。"},{"id":308,"chapter":"第三章 坚持党的全面领导","type":"single","typeText":"单选题","score":2.0,"question":"党的领导制度是我国的( )。","options":[{"key":"A","text":"根本制度"},{"key":"B","text":"重要制度"},{"key":"C","text":"基本制度"},{"key":"D","text":"政策策略"}],"answer":["A"],"explanation":"党的领导制度是我国的根本领导制度，在党和国家制度体系中居于统领地位。"},{"id":309,"chapter":"第三章 坚持党的全面领导","type":"single","typeText":"单选题","score":2.0,"question":"坚持党总揽全局、协调各方的领导核心地位，( )形象地说，这就像\"众星捧月\"，这个\"月\"就是中国共产党。","options":[{"key":"A","text":"习近平"},{"key":"B","text":"邓小平"},{"key":"C","text":"毛泽东"},{"key":"D","text":"江泽民"}],"answer":["A"],"explanation":"习近平总书记用\"众星捧月\"形象地比喻了党总揽全局、协调各方的领导核心地位。"},{"id":310,"chapter":"第三章 坚持党的全面领导","type":"single","typeText":"单选题","score":2.0,"question":"中国共产党的性质决定了党的宗旨是( )。","options":[{"key":"A","text":"立党为公、执政为民"},{"key":"B","text":"以人为本、执政为民"},{"key":"C","text":"全心全意为人民服务"},{"key":"D","text":"为实现共产主义而奋斗"}],"answer":["C"],"explanation":"中国共产党的性质决定了党的根本宗旨是全心全意为人民服务，这是党的一切工作的出发点和落脚点。"},{"id":311,"chapter":"第三章 坚持党的全面领导","type":"single","typeText":"单选题","score":2.0,"question":"( )是我国的根本领导制度，居于统领地位。","options":[{"key":"A","text":"党的组织原则"},{"key":"B","text":"党的政治原则"},{"key":"C","text":"党的领导制度"},{"key":"D","text":"党的性质宗旨"}],"answer":["C"],"explanation":"党的领导制度是我国的根本领导制度，在党和国家制度体系中居于统领地位。"},{"id":312,"chapter":"第三章 坚持党的全面领导","type":"single","typeText":"单选题","score":2.0,"question":"历史和现实证明，( )就没有中国特色社会主义的产生与发展。","options":[{"key":"A","text":"没有中国共产党的指导"},{"key":"B","text":"没有中国共产党的组织"},{"key":"C","text":"没有中国共产党的领导"},{"key":"D","text":"没有中国共产党的监督"}],"answer":["C"],"explanation":"中国共产党的领导是中国特色社会主义最本质的特征，没有党的领导就没有中国特色社会主义的产生与发展。"},{"id":313,"chapter":"第三章 坚持党的全面领导","type":"single","typeText":"单选题","score":2.0,"question":"( )将党的领导制度明确为我国根本领导制度。","options":[{"key":"A","text":"党的十九大"},{"key":"B","text":"党的十九届三中全会"},{"key":"C","text":"党的十九届四中全会"},{"key":"D","text":"党的十九届五中全会"}],"answer":["C"],"explanation":"党的十九届四中全会将党的领导制度明确为我国根本领导制度，这在党的历史上是第一次。"},{"id":314,"chapter":"第三章 坚持党的全面领导","type":"single","typeText":"单选题","score":2.0,"question":"《中国共产党党章》明确规定，中国共产党是中国工人阶级的先锋队，同时是( )。","options":[{"key":"A","text":"中国人民的先锋队"},{"key":"B","text":"中华民族的先锋队"},{"key":"C","text":"中国人民和中华民族的先锋队"},{"key":"D","text":"中国新阶层的先锋队"}],"answer":["C"],"explanation":"党章明确规定，中国共产党是中国工人阶级的先锋队，同时是中国人民和中华民族的先锋队。"},{"id":315,"chapter":"第三章 坚持党的全面领导","type":"single","typeText":"单选题","score":2.0,"question":"( )是中国特色社会主义最本质的特征。","options":[{"key":"A","text":"以经济建设为中心"},{"key":"B","text":"以人为本"},{"key":"C","text":"\"五位一体总体布局\""},{"key":"D","text":"中国共产党的领导"}],"answer":["D"],"explanation":"中国共产党的领导是中国特色社会主义最本质的特征，这是习近平总书记提出的重要论断。"},{"id":316,"chapter":"第三章 坚持党的全面领导","type":"single","typeText":"单选题","score":2.0,"question":"面对新时代新挑战新要求，( )就是战胜艰难险阻，不断取得胜利的制胜法宝。","options":[{"key":"A","text":"改进完善党的领导"},{"key":"B","text":"坚持和加强党的领导"},{"key":"C","text":"全面推进党的改革"},{"key":"D","text":"增加党员人数"}],"answer":["B"],"explanation":"坚持和加强党的领导是战胜一切艰难险阻、不断取得胜利的制胜法宝。"},{"id":317,"chapter":"第三章 坚持党的全面领导","type":"single","typeText":"单选题","score":2.0,"question":"党中央制定的理论和路线方针政策，是全党全国各族人民统一思想、统一意志、统一行动的依据和基础。党中央的权威首先体现在( )。","options":[{"key":"A","text":"党中央决定的事、党中央的决策部署，所有党组织和党员都必须坚决执行"},{"key":"B","text":"党的理论和路线方针政策能够不折不扣得到贯彻执行"},{"key":"C","text":"要以实际行动维护党中央权威，确保党中央政令畅通、令行禁止"},{"key":"D","text":"维护党中央权威和集中统一领导，对象是党中央而不是其他任何组织"}],"answer":["B"],"explanation":"党中央的权威首先体现在党的理论和路线方针政策能够不折不扣得到贯彻执行，这是维护党中央权威的基础。"},{"id":318,"chapter":"第三章 坚持党的全面领导","type":"single","typeText":"单选题","score":2.0,"question":"中国共产党是以民主集中制为根本组织原则和领导制度的马克思主义政党。必须坚持党员个人服从党的组织，少数服从多数，下级组织服从上级组织，全党各个组织和全体党员服从党的全国代表大会和中央委员会，核心是( )。","options":[{"key":"A","text":"个人服从党的组织"},{"key":"B","text":"少数服从多数"},{"key":"C","text":"下级组织服从上级组织"},{"key":"D","text":"全党各个组织和全体党员服从党的全国代表大会和中央委员会"}],"answer":["D"],"explanation":"民主集中制的核心是全党各个组织和全体党员服从党的全国代表大会和中央委员会，这是维护党的团结统一的关键。"},{"id":319,"chapter":"第三章 坚持党的全面领导","type":"single","typeText":"单选题","score":2.0,"question":"加强党中央对重大工作的领导，是我们党的优良传统和宝贵经验。早在( )时期，我们党就确立了各省委向中央报告的制度，要求各地及时向中央报告工作。","options":[{"key":"A","text":"建党"},{"key":"B","text":"土地革命战争"},{"key":"C","text":"抗日战争"},{"key":"D","text":"解放战争"}],"answer":["B"],"explanation":"土地革命战争时期，我们党就确立了各省委向中央报告的制度，这是加强党中央集中统一领导的重要举措。"},{"id":320,"chapter":"第三章 坚持党的全面领导","type":"single","typeText":"单选题","score":2.0,"question":"党的领导制度是一个系统完备、内涵丰富的制度体系，主要涵盖( )个方面的制度。","options":[{"key":"A","text":"四"},{"key":"B","text":"五"},{"key":"C","text":"六"},{"key":"D","text":"七"}],"answer":["C"],"explanation":"党的领导制度主要涵盖六个方面的制度，包括领导立法、保证执法、支持司法、带头守法等方面的制度。"},{"id":321,"chapter":"第三章 坚持党的全面领导","type":"single","typeText":"单选题","score":2.0,"question":"健全党的全面领导制度，确保党在各种组织中发挥领导作用，是党的领导制度体系的( )。","options":[{"key":"A","text":"最高原则"},{"key":"B","text":"主体内容"},{"key":"C","text":"实践要求"},{"key":"D","text":"坚强保证"}],"answer":["B"],"explanation":"确保党在各种组织中发挥领导作用是党的领导制度体系的主体内容，是实现党的全面领导的重要保障。"},{"id":322,"chapter":"第三章 坚持党的全面领导","type":"single","typeText":"单选题","score":2.0,"question":"中国共产党的领导是中国特色社会主义最本质的特征，这是( )以来习近平提出的一个重要论断。","options":[{"key":"A","text":"党的十八大"},{"key":"B","text":"党的十五大"},{"key":"C","text":"党的十九大"},{"key":"D","text":"党的十七大"}],"answer":["A"],"explanation":"党的十八大以来，习近平总书记提出了中国共产党的领导是中国特色社会主义最本质的特征这一重要论断。"},{"id":323,"chapter":"第三章 坚持党的全面领导","type":"multiple","typeText":"多选题","score":3.0,"question":"中国共产党的领导是( )。","options":[{"key":"A","text":"中国特色社会主义最本质的特征"},{"key":"B","text":"中国最大的国情"},{"key":"C","text":"中国特色社会主义制度的最大优势"},{"key":"D","text":"实现中华民族伟大复兴的历史使命"}],"answer":["A","B","C"],"explanation":"中国共产党的领导是中国特色社会主义最本质的特征，是中国最大的国情，是中国特色社会主义制度的最大优势。"},{"id":324,"chapter":"第三章 坚持党的全面领导","type":"multiple","typeText":"多选题","score":3.0,"question":"中国共产党领导是中国特色社会主义最本质的特征，( )。","options":[{"key":"A","text":"这是在近代以来中国历史发展中形成的"},{"key":"B","text":"这是由中国最广大人民根本利益决定的"},{"key":"C","text":"这是实现中华民族伟大复兴历史任务决定的"},{"key":"D","text":"这决定了中国特色社会主义其他特点和特征"}],"answer":["A","B","C","D"],"explanation":"党的领导是中国特色社会主义最本质的特征，这是历史发展的必然、人民的选择、民族复兴的需要，决定了中国特色社会主义的其他特点和特征。"},{"id":325,"chapter":"第三章 坚持党的全面领导","type":"multiple","typeText":"多选题","score":3.0,"question":"中国共产党的领导是( )。","options":[{"key":"A","text":"在历史奋斗中形成的"},{"key":"B","text":"人民当家做主的可靠保障"},{"key":"C","text":"关系中国特色社会主义的性质、方向和命运"},{"key":"D","text":"是实现中华民族伟大复兴的根本保证"}],"answer":["A","B","C","D"],"explanation":"党的领导是在历史奋斗中形成的，是人民当家作主的保障，关系中国特色社会主义的性质、方向和命运，是实现民族复兴的根本保证。"},{"id":326,"chapter":"第三章 坚持党的全面领导","type":"multiple","typeText":"多选题","score":3.0,"question":"中国特色社会主义之所以是社会主义，究其根本就在于( )。","options":[{"key":"A","text":"坚持科学社会主义基本原则"},{"key":"B","text":"坚持中国共产党的领导"},{"key":"C","text":"坚持按劳分配"},{"key":"D","text":"坚持社会主义市场经济体制"}],"answer":["A","B"],"explanation":"中国特色社会主义之所以是社会主义，根本在于坚持科学社会主义基本原则和中国共产党的领导。"},{"id":327,"chapter":"第三章 坚持党的全面领导","type":"multiple","typeText":"多选题","score":3.0,"question":"全面加强党的领导，( )。","options":[{"key":"A","text":"使我们有效应对严峻复杂的国际形势和接踵而至的巨大风险挑战"},{"key":"B","text":"有力推进了党和国家各项事业的顺利发展"},{"key":"C","text":"胜利实现了全面建成小康社会的战略目标"},{"key":"D","text":"开启了全面建设社会主义现代化国家新征程"}],"answer":["A","B","C","D"],"explanation":"全面加强党的领导，使我们有效应对风险挑战，推进事业发展，实现全面小康，开启全面建设社会主义现代化国家新征程。"},{"id":328,"chapter":"第三章 坚持党的全面领导","type":"multiple","typeText":"多选题","score":3.0,"question":"1948年在解放战争即将取得决定性胜利之际，中国共产党发布\"五一口号\"，( )。","options":[{"key":"A","text":"号召全国各族人民为争取民族独立、人民解放和实现国家富强、人民幸福而不懈奋斗"},{"key":"B","text":"号召迅速召开政治协商会议，成立民主联合政府"},{"key":"C","text":"各民主党派以及无党派民主人士和海外华侨热烈响应，公开、自觉地接受中国共产党的领导"},{"key":"D","text":"必须团结成\"一块坚硬的钢铁\"，必须有坚强的领导核心"}],"answer":["B","C"],"explanation":"1948年中国共产党发布\"五一口号\"，号召召开政治协商会议，成立民主联合政府，各民主党派积极响应，接受党的领导。"},{"id":329,"chapter":"第三章 坚持党的全面领导","type":"multiple","typeText":"多选题","score":3.0,"question":"健全党的全面领导制度，必须( )。","options":[{"key":"A","text":"必须完善党在各种组织中发挥领导作用的制度"},{"key":"B","text":"必须完善党协调各方的机制"},{"key":"C","text":"必须完善党领导各项事业的具体制度"},{"key":"D","text":"必须完善人民代表大会制度"}],"answer":["A","B","C"],"explanation":"健全党的全面领导制度需要完善党在各种组织中发挥领导作用的制度、完善党协调各方的机制、完善党领导各项事业的具体制度。"},{"id":330,"chapter":"第三章 坚持党的全面领导","type":"multiple","typeText":"多选题","score":3.0,"question":"党的领导是做好党和国家各项工作的根本保证，是我国( )的根本点，绝对不能有丝毫动摇。","options":[{"key":"A","text":"民族团结"},{"key":"B","text":"社会稳定"},{"key":"C","text":"政治稳定"},{"key":"D","text":"经济发展"}],"answer":["A","B","C","D"],"explanation":"党的领导是我国民族团结、社会稳定、政治稳定、经济发展的根本保证，绝对不能有丝毫动摇。"},{"id":331,"chapter":"第三章 坚持党的全面领导","type":"multiple","typeText":"多选题","score":3.0,"question":"确保党始终总揽全局、协调各方，必须增强政治意识( )，自觉维护党中央权威和集中统一领导，自觉在思想上政治上行动上同党中央保持高度一致。","options":[{"key":"A","text":"大局意识"},{"key":"B","text":"核心意识"},{"key":"C","text":"中心意识"},{"key":"D","text":"看齐意识"}],"answer":["A","B","D"],"explanation":"确保党始终总揽全局、协调各方，必须增强政治意识、大局意识、核心意识、看齐意识。"},{"id":332,"chapter":"第三章 坚持党的全面领导","type":"multiple","typeText":"多选题","score":3.0,"question":"党是最高政治领导力量，这是由我国( )和( )所决定的。","options":[{"key":"A","text":"国家性质"},{"key":"B","text":"政治制度体系"},{"key":"C","text":"经济基础"},{"key":"D","text":"经济制度"}],"answer":["A","B"],"explanation":"党是最高政治领导力量，这是由我国国家性质和政治制度体系所决定的。"},{"id":333,"chapter":"第三章 坚持党的全面领导","type":"multiple","typeText":"多选题","score":3.0,"question":"党的领导是全面的，体现在( )。","options":[{"key":"A","text":"领导对象"},{"key":"B","text":"领导内容"},{"key":"C","text":"领导过程"},{"key":"D","text":"领导方式"}],"answer":["A","B","C","D"],"explanation":"党的领导是全面的，体现在领导对象、领导内容、领导过程、领导方式等各个方面。"},{"id":334,"chapter":"第三章 坚持党的全面领导","type":"multiple","typeText":"多选题","score":3.0,"question":"坚持和完善党的领导，是( )。","options":[{"key":"A","text":"党和国家的根本所在、命脉所在"},{"key":"B","text":"全国各族人民的利益所在、幸福所在"},{"key":"C","text":"中国特色社会主义最本质的特征"},{"key":"D","text":"中国特色社会主义制度的最大优势"}],"answer":["A","B","C","D"],"explanation":"坚持和完善党的领导，是党和国家的根本所在、命脉所在，是全国各族人民的利益所在、幸福所在，是中国特色社会主义最本质的特征和最大优势。"},{"id":335,"chapter":"第三章 坚持党的全面领导","type":"multiple","typeText":"多选题","score":3.0,"question":"党的领导是全面的、系统的、整体的，并不是说党组织包揽包办一切、事无巨细什么都去管，而是( )。","options":[{"key":"A","text":"在各级各种组织中发挥领导核心作用"},{"key":"B","text":"既善于总揽全局，又善于协调各方，不断增强党组织的领导统筹能力"},{"key":"C","text":"充分调动方方面面的工作积极性"},{"key":"D","text":"使党的领导作用贯穿于工作全过程"}],"answer":["A","B","C","D"],"explanation":"党的领导是全面的、系统的、整体的，体现在发挥领导核心作用、总揽全局协调各方、调动各方积极性、贯穿工作全过程等方面。"},{"id":336,"chapter":"第三章 坚持党的全面领导","type":"multiple","typeText":"多选题","score":3.0,"question":"中国共产党是中国特色社会主义事业的( )。","options":[{"key":"A","text":"开创者"},{"key":"B","text":"推动者"},{"key":"C","text":"引领者"},{"key":"D","text":"发动者"}],"answer":["A","B","C"],"explanation":"中国共产党是中国特色社会主义事业的开创者、推动者和引领者。"},{"id":337,"chapter":"第三章 坚持党的全面领导","type":"multiple","typeText":"多选题","score":3.0,"question":"党章规定的民主集中制要求( )。","options":[{"key":"A","text":"党员个人服从党的组织"},{"key":"B","text":"少数服从多数"},{"key":"C","text":"下级组织服从上级组织"},{"key":"D","text":"全党各个组织和全体党员服从党的全国代表大会和中央委员会"}],"answer":["A","B","C","D"],"explanation":"党章规定的民主集中制要求包括：党员个人服从党的组织、少数服从多数、下级组织服从上级组织、全党各个组织和全体党员服从党的全国代表大会和中央委员会。"},{"id":338,"chapter":"第三章 坚持党的全面领导","type":"multiple","typeText":"多选题","score":3.0,"question":"坚持和加强党的全面领导，使党的( )显著增强。","options":[{"key":"A","text":"政治领导力"},{"key":"B","text":"思想引领力"},{"key":"C","text":"群众组织力"},{"key":"D","text":"社会号召力"}],"answer":["A","B","C","D"],"explanation":"坚持和加强党的全面领导，使党的政治领导力、思想引领力、群众组织力、社会号召力显著增强。"},{"id":339,"chapter":"第三章 坚持党的全面领导","type":"multiple","typeText":"多选题","score":3.0,"question":"中国共产党作为最高政治领导力量，在党和国家事业发展中居于中心地位。党的领导是( )。","options":[{"key":"A","text":"全面的"},{"key":"B","text":"系统的"},{"key":"C","text":"独特的"},{"key":"D","text":"整体的"}],"answer":["A","B","D"],"explanation":"中国共产党作为最高政治领导力量，党的领导是全面的、系统的、整体的。"},{"id":340,"chapter":"第三章 坚持党的全面领导","type":"multiple","typeText":"多选题","score":3.0,"question":"中国特色社会主义制度是一个严密完整的科学制度体系，起四梁八柱作用的是( )。","options":[{"key":"A","text":"根本制度"},{"key":"B","text":"基本制度"},{"key":"C","text":"重要制度"},{"key":"D","text":"具体制度"}],"answer":["A","B","C"],"explanation":"中国特色社会主义制度体系中，根本制度、基本制度、重要制度起四梁八柱作用。"},{"id":341,"chapter":"第三章 坚持党的全面领导","type":"multiple","typeText":"多选题","score":3.0,"question":"加强党中央对重大工作的领导，必须完善党中央重大决策部署落实机制。党的领导决策核心是( )。","options":[{"key":"A","text":"中央委员会"},{"key":"B","text":"中央政治局"},{"key":"C","text":"中央政治局常委会"},{"key":"D","text":"党的总书记"}],"answer":["A","B","C"],"explanation":"党的领导决策核心是中央委员会、中央政治局、中央政治局常委会。"},{"id":342,"chapter":"第三章 坚持党的全面领导","type":"multiple","typeText":"多选题","score":3.0,"question":"坚持和加强党的全面领导，必须健全党的全面领导制度。健全党的全面领导制度，必须( )。","options":[{"key":"A","text":"加强党中央对重大工作的领导"},{"key":"B","text":"完善党在各种组织中发挥领导作用的制度"},{"key":"C","text":"完善党协调各方的机制"},{"key":"D","text":"完善党领导各项事业的具体制度"}],"answer":["B","C","D"],"explanation":"健全党的全面领导制度，必须完善党在各种组织中发挥领导作用的制度、完善党协调各方的机制、完善党领导各项事业的具体制度。"},{"id":401,"chapter":"第四章 坚持以人民为中心","type":"single","typeText":"单选题","score":6.0,"question":"坚持以人民为中心，就必须坚持人民主体地位，坚持立党为公、执政为民，践行全心全意为人民服务的根本宗旨，把党的群众路线贯彻到治国理政全部活动之中，把人民对美好生活的向往作为奋斗目标。\"坚持以人民为中心\"的理论基础是唯物史观关于( )。","options":[{"key":"A","text":"人民群众是历史的创造者的原理"},{"key":"B","text":"人的本质是一切社会关系的总和的原理"},{"key":"C","text":"人民群众的活动受到社会历史条件制约的原理"},{"key":"D","text":"总体的人在总体的历史过程中的主体地位的原理"}],"answer":["A"],"explanation":"唯物史观认为，人民群众是历史的创造者，是社会物质财富和精神财富的创造者，是社会变革的决定力量。\"以人民为中心\"的思想正是这一基本原理在当代中国的实践体现。"},{"id":402,"chapter":"第四章 坚持以人民为中心","type":"single","typeText":"单选题","score":6.0,"question":"始终时党的生命线和根本工作路线，是我们党永葆青春活力和战斗力的重要传家宝。( )。","options":[{"key":"A","text":"群众路线"},{"key":"B","text":"经济路线"},{"key":"C","text":"人民立场"},{"key":"D","text":"政治立场"}],"answer":["A"],"explanation":"群众路线是我们党的生命线和根本工作路线，其核心内容是‘一切为了群众，一切依靠群众，从群众中来，到群众中去’。这是党保持同人民群众血肉联系的根本保证。"},{"id":403,"chapter":"第四章 坚持以人民为中心","type":"single","typeText":"单选题","score":6.0,"question":"马克思主义政党站在人民立场上，始终将最广大人民群众的根本利益作为自己的( )。","options":[{"key":"A","text":"最终目标"},{"key":"B","text":"根本宗旨"},{"key":"C","text":"核心立场"},{"key":"D","text":"最高利益"}],"answer":["D"],"explanation":"作为马克思主义政党，中国共产党没有自己特殊的利益，始终代表最广大人民的根本利益，并将此视为自己的最高利益。"},{"id":404,"chapter":"第四章 坚持以人民为中心","type":"single","typeText":"单选题","score":6.0,"question":"我们党讲了宗旨，讲了很多话，但说到底还是这句话( )。","options":[{"key":"A","text":"以人民为中心"},{"key":"B","text":"为人民服务"},{"key":"C","text":"坚持人民主体地位"},{"key":"D","text":"群众路线是根本工作路线"}],"answer":["B"],"explanation":"中国共产党始终以全心全意为人民服务为根本宗旨，这是党一切工作的出发点和落脚点，是贯穿党的全部理论和实践的根本要求。"},{"id":405,"chapter":"第四章 坚持以人民为中心","type":"single","typeText":"单选题","score":6.0,"question":"新时代要坚持以( )为中心，在推动社会全面进步中促进人的全面发展。","options":[{"key":"A","text":"人民"},{"key":"B","text":"经济"},{"key":"C","text":"政治"},{"key":"D","text":"文化"}],"answer":["A"],"explanation":"以人民为中心是新时代中国特色社会主义的根本立场，所有的发展都要围绕人民，依靠人民，发展成果由人民共享，最终实现人的全面发展。"},{"id":406,"chapter":"第四章 坚持以人民为中心","type":"single","typeText":"单选题","score":6.0,"question":"党的十九届六中全会进一步明确，必须坚持( )的发展思想，发展全过程人民民主，推动人的全面发展、全体人民共同富裕取得更为明显实质性进展。","options":[{"key":"A","text":"群众路线是根本工作路线"},{"key":"B","text":"党的建设"},{"key":"C","text":"经济社会协调发展"},{"key":"D","text":"以人民为中心"}],"answer":["D"],"explanation":"党的十九届六中全会《决议》明确指出，必须坚持以人民为中心的发展思想，这是推动高质量发展、实现共同富裕、发展全过程人民民主的根本遵循。"},{"id":407,"chapter":"第四章 坚持以人民为中心","type":"single","typeText":"单选题","score":6.0,"question":"( )是我们党做好一切工作的价值取向和根本标准。","options":[{"key":"A","text":"实现社会主义社会的生产力快速发展"},{"key":"B","text":"提高社会主义国家的综合国力"},{"key":"C","text":"让群众满意"},{"key":"D","text":"实现经济的高质量发展"}],"answer":["C"],"explanation":"检验我们一切工作的成效，最终都要看人民是否真正得到了实惠，人民生活是否真正得到了改善，人民权益是否真正得到了保障，即是否让群众满意。"},{"id":408,"chapter":"第四章 坚持以人民为中心","type":"single","typeText":"单选题","score":6.0,"question":"坚持人民至上，是新时代党治国理政的根本价值取向。要坚持( )作为党的奋斗目标，把人民作为党的工作的最高裁决者和最终评判者。","options":[{"key":"A","text":"把满足人民的物质生活需要"},{"key":"B","text":"把人民对美好生活的向往"},{"key":"C","text":"把满足人民的精神文化需求"},{"key":"D","text":"把满足人民的政治生活需要"}],"answer":["B"],"explanation":"人民对美好生活的向往，就是我们的奋斗目标。党的一切工作必须以最广大人民根本利益为最高标准，由人民来评判最终成效。"},{"id":409,"chapter":"第四章 坚持以人民为中心","type":"single","typeText":"单选题","score":5.0,"question":"2021年5月13日，习近平总书记在河南考察南水北调工程时再次强调了我们共产党打江山、守江山都是为了人民的幸福，守的是人民的心。中国共产党执政要坚持\"权为民所用、情为民所系、利为民所谋\"。这说明中国共产党( )。","options":[{"key":"A","text":"以全心全意为人民服务为根本宗旨"},{"key":"B","text":"以实现共产主义为最高理想"},{"key":"C","text":"是工人阶级的先锋队"},{"key":"D","text":"反对党员追求个人利益"}],"answer":["A"],"explanation":"\"打江山、守江山，守的是人民的心\"，以及\"权为民所用、情为民所系、利为民所谋\"的论述，直接体现了中国共产党全心全意为人民服务的根本宗旨。"},{"id":410,"chapter":"第四章 坚持以人民为中心","type":"single","typeText":"单选题","score":5.0,"question":"树高千尺总有根，水流万里总有源。中国共产党历经百年而风华正茂、饱经磨难而生生不息。其立党、兴党、强党背后的原因在于，中国共产党( )。\n①始终坚持立党为公、执政为民\n②始终把人民放在心中最高位置\n③大公无私，没有任何自身利益\n④坚定理想信念信守初心和使命","options":[{"key":"A","text":"①③"},{"key":"B","text":"②③"},{"key":"C","text":"①④"},{"key":"D","text":"②④"}],"answer":["D"],"explanation":"中国共产党永葆生机活力的根本原因在于其始终代表最广大人民根本利益，坚持以人民为中心的发展思想（②），并坚守为中国人民谋幸福、为中华民族谋复兴的初心使命（④）。③的表述不准确，中国共产党有自身的利益追求，即实现人民的根本利益。①的表述是执政理念，但其成立之初（立党）主要任务是革命，因此概括为立党、兴党、强党的全部原因不如②④全面和精准。"},{"id":411,"chapter":"第四章 坚持以人民为中心","type":"multiple","typeText":"多选题","score":6.0,"question":"习近平总书记2019年3月在意大利进行国事访问时说到，我将无我，不负人民。我愿意做到一个\"无我\"的状态，为中国的发展奉献自己。2020年12月 在全国政协新年茶话会上他又说到，我们要发扬为民服务孺子牛、创新发展拓荒牛、艰苦奋斗老黄牛的精神，在全面建设社会主义现代化国家新征程上奋勇前进。\"我将无我，不负人民\"和\"三牛\"精神，体现了中国共产党( )。","options":[{"key":"A","text":"把人民利益放在至高无上的地位"},{"key":"B","text":"坚持全心全意为人民服务的根本宗旨"},{"key":"C","text":"立党为公、执政为民的执政理念"},{"key":"D","text":"从始至终都没有自身利益"}],"answer":["A","B","C"],"explanation":"\"我将无我，不负人民\"和\"三牛\"精神，集中体现了中国共产党全心全意为人民服务的根本宗旨、以人民为中心的发展思想和立党为公、执政为民的执政理念，彰显了党与人民休戚与共的血肉联系。D选项表述不准确，中国共产党有自己的利益追求，即追求人民的根本利益。"},{"id":412,"chapter":"第四章 坚持以人民为中心","type":"multiple","typeText":"多选题","score":6.0,"question":"《管子•牧民》中记载:\"政之所兴，在顺民心;政之所废，在逆民心。\"《尚书•大禹》提出:\"德惟善政，政在养民。\"这对我们党执政的启示是( )。","options":[{"key":"A","text":"把增长政府权威作为出发点和立足点"},{"key":"B","text":"倡导正确的权力观和政绩观"},{"key":"C","text":"以满足人民一切意愿与诉求为根本点"},{"key":"D","text":"坚持以人民为中心的治国理念"}],"answer":["B","D"],"explanation":"古语强调了民心向背是政权兴废的关键，为政之德在于养护百姓。这启示我们党必须坚持以人民为中心的治国理政思想，树立权力来自人民、为了人民的正确权力观，以及以人民福祉为重的政绩观。A选项强调政府权威，与以人民为中心的理念不完全一致。C选项中“满足一切意愿与诉求”表述绝对化，不符合实事求是原则。"},{"id":413,"chapter":"第四章 坚持以人民为中心","type":"multiple","typeText":"多选题","score":6.0,"question":"党的十九届六中全会把\"发展全过程人民民主\"写进了《决议》，强调必须坚持( )有机统一，积极发展全过程人民民主。这是对马克思主义人民民主思想的继承和发展，是中国特色社会主义民主理论的重大创新成果。","options":[{"key":"A","text":"党的领导"},{"key":"B","text":"人民当家作主"},{"key":"C","text":"依法治国"},{"key":"D","text":"独立自主"}],"answer":["A","B","C"],"explanation":"坚持党的领导、人民当家作主、依法治国有机统一，是中国特色社会主义政治发展道路的核心内容，也是发展全过程人民民主的根本保证。独立自主是外交原则，不直接属于国内民主政治的有机统一体范畴。"},{"id":414,"chapter":"第四章 坚持以人民为中心","type":"multiple","typeText":"多选题","score":6.0,"question":"中国特色社会主义价值目标是( )。","options":[{"key":"A","text":"国家富强"},{"key":"B","text":"民族振兴"},{"key":"C","text":"社会和谐"},{"key":"D","text":"人民幸福"}],"answer":["A","B","C","D"],"explanation":"中国特色社会主义的价值目标涵盖了国家、民族、社会、人民四个维度，即国家富强、民族振兴、社会和谐、人民幸福，这共同构成了中华民族伟大复兴中国梦的核心内涵。"},{"id":415,"chapter":"第四章 坚持以人民为中心","type":"multiple","typeText":"多选题","score":6.0,"question":"党的十八大以来，我们党一直强调坚持和发展中国特色社会主义要一以贯之。在《习近平谈治国理政》第三卷收录的文献中，习近平总书记再次强调了这一点。这是因为，新时代中国特色社会主义( )。","options":[{"key":"A","text":"是中国共产党必须牢记的初心和使命"},{"key":"B","text":"是人类社会发展的最高阶段"},{"key":"C","text":"是党领导人民进行伟大社会革命的继续"},{"key":"D","text":"是党和人民历经千辛万苦取得的宝贵成果"}],"answer":["C","D"],"explanation":"新时代中国特色社会主义是改革开放以来特别是党的十八大以来取得历史性成就、发生历史性变革的产物，是党和人民长期奋斗、创造、积累的根本成就。同时，它并非革命的终点，而是党领导人民进行具有许多新的历史特点的伟大社会革命的继续。A选项是初心使命的内容，不是强调“一以贯之”的原因；B选项表述错误。"},{"id":416,"chapter":"第四章 坚持以人民为中心","type":"multiple","typeText":"多选题","score":6.0,"question":"现在，我们党正团结带领全国各族人民朝着全面建成社会主义现代化强国的第二个百年奋斗目标迈进。新的赶考路上，我们要继续推进全过程人民民主建设，不断丰富有效的民主实现形式。以下是民主形式的有( )。","options":[{"key":"A","text":"民主选举"},{"key":"B","text":"民主监督"},{"key":"C","text":"民主决策"},{"key":"D","text":"民主协商"},{"key":"E","text":"民主管理"}],"answer":["A","B","C","D","E"],"explanation":"全过程人民民主是全链条、全方位、全覆盖的民主。其实践形式包括民主选举、民主协商、民主决策、民主管理、民主监督等各个环节，确保人民依法通过各种途径和形式管理国家事务、经济文化事业和社会事务。"},{"id":417,"chapter":"第四章 坚持以人民为中心","type":"multiple","typeText":"多选题","score":6.0,"question":"周恩来同志为家人订立\"十条家规\"，朱德同志告诫子女\"接班不接官\"，彭德怀同志对亲友不搞\"近水楼台先得月\"，曾志同志拒绝为孙子安排\"农转非\"。老一辈革命家的言行体现了共产党人( )。","options":[{"key":"A","text":"公而无私的党性修养"},{"key":"B","text":"正心律己的自觉"},{"key":"C","text":"不徇私情的原则立场"},{"key":"D","text":"只维护无产阶级的利益"}],"answer":["A","B","C"],"explanation":"老一辈革命家严于律己、廉洁齐家的言行，充分展现了共产党人光明磊落、一心为公的高尚品格，是坚守党性原则、严守纪律规矩、自觉抵制特权思想的典范。D选项“只维护”表述过于狭窄，共产党维护的是最广大人民的根本利益，而不仅限于某一阶级。"},{"id":501,"chapter":"第五章 全面深化改革","type":"single","typeText":"单选题","score":3.0,"question":"要破解发展中面临的难题，化解来自各方面的风险挑战，推动经济社会持续健康发展，必须依靠( )。","options":[{"key":"A","text":"全面建成小康社会"},{"key":"B","text":"全面深化改革"},{"key":"C","text":"全面依法治国"},{"key":"D","text":"全面从严治党"}],"answer":["B"],"explanation":"全面深化改革是解决发展难题、应对风险挑战、推动经济社会持续健康发展的根本动力和关键举措。"},{"id":502,"chapter":"第五章 全面深化改革","type":"single","typeText":"单选题","score":3.0,"question":"党的十九大提出，党的二十大重申，到( )\"各方面制度更加完善，国家治理体系和治理能力现代化基本实现\"。","options":[{"key":"A","text":"2035年"},{"key":"B","text":"2030年"},{"key":"C","text":"2025年"},{"key":"D","text":"2020年"}],"answer":["A"],"explanation":"党的十九大报告提出，到2035年基本实现国家治理体系和治理能力现代化；党的二十大报告重申了这一目标。"},{"id":503,"chapter":"第五章 全面深化改革","type":"single","typeText":"单选题","score":3.0,"question":"中国特色社会主义制度和国家治理体系是以( )为指导、植根中国大地、具有深厚中华文化根基、深得人民拥护的制度和治理体系。","options":[{"key":"A","text":"社会主义"},{"key":"B","text":"中国特色社会主义"},{"key":"C","text":"马克思主义"},{"key":"D","text":"毛泽东思想"}],"answer":["C"],"explanation":"中国特色社会主义制度和国家治理体系是以马克思主义为指导，结合中国实际和中华优秀传统文化形成的科学制度体系。"},{"id":504,"chapter":"第五章 全面深化改革","type":"single","typeText":"单选题","score":3.0,"question":"坚持和完善中国特色社会主义制度、推进国家治理体系和治理能力现代化，不仅要建立完善的制度体系，还要在不断提高( )上狠下功夫。","options":[{"key":"A","text":"民主与法治"},{"key":"B","text":"制度创新和社会和谐"},{"key":"C","text":"社会发展和经济增速"},{"key":"D","text":"制度执行力和治理能力"}],"answer":["D"],"explanation":"制度执行力和治理能力是制度优势转化为治理效能的关键，是推进国家治理现代化的重点。"},{"id":505,"chapter":"第五章 全面深化改革","type":"single","typeText":"单选题","score":3.0,"question":"( )作出了全面深化改革的决定。","options":[{"key":"A","text":"党的十八大"},{"key":"B","text":"党的十八届三中全会"},{"key":"C","text":"党的十九大"},{"key":"D","text":"党的十九届六中全会"}],"answer":["B"],"explanation":"党的十八届三中全会审议通过了《中共中央关于全面深化改革若干重大问题的决定》，标志着全面深化改革正式启动。"},{"id":506,"chapter":"第五章 全面深化改革","type":"single","typeText":"单选题","score":3.0,"question":"全面深化改革必须始终站稳人民立场，坚持( )的改革价值取向。","options":[{"key":"A","text":"以人民为中心"},{"key":"B","text":"社会主义本质要求"},{"key":"C","text":"党的性质宗旨"},{"key":"D","text":"社会主义发展"}],"answer":["A"],"explanation":"以人民为中心是全面深化改革的根本立场和价值取向，所有改革都要为了人民、依靠人民、造福人民。"},{"id":507,"chapter":"第五章 全面深化改革","type":"single","typeText":"单选题","score":3.0,"question":"保持战略定力，牢牢把握全面深化改革开放的正确方向，最核心的是( )、坚持和完善中国特色社会主义制度。","options":[{"key":"A","text":"全体人民的共同参与"},{"key":"B","text":"坚持和改善党的领导"},{"key":"C","text":"全方位对外开放"},{"key":"D","text":"社会主义的发展方向"}],"answer":["B"],"explanation":"党的领导是中国特色社会主义最本质的特征，是全面深化改革沿着正确方向推进的根本保证。"},{"id":508,"chapter":"第五章 全面深化改革","type":"single","typeText":"单选题","score":3.0,"question":"( )是运用国家制度管理国家各方面事务的能力。","options":[{"key":"A","text":"治理能力"},{"key":"B","text":"治理体系"},{"key":"C","text":"管理能力"},{"key":"D","text":"协调能力"}],"answer":["A"],"explanation":"治理能力是指运用国家制度体系管理国家和社会各方面事务的能力，是国家治理效能的重要体现。"},{"id":509,"chapter":"第五章 全面深化改革","type":"single","typeText":"单选题","score":3.0,"question":"坚持以( )为原则推动\"一带一路\"建设。","options":[{"key":"A","text":"中华民族伟大复兴"},{"key":"B","text":"维护世界和平、促进共同发展"},{"key":"C","text":"共商共建共享"},{"key":"D","text":"维护党中央权威"}],"answer":["C"],"explanation":"\"一带一路\"建设坚持共商共建共享原则，旨在实现互利共赢、共同发展，推动构建人类命运共同体。"},{"id":510,"chapter":"第五章 全面深化改革","type":"single","typeText":"单选题","score":3.0,"question":"推进国家治理体系和治理能力现代化，必须坚定中国特色社会主义( )。","options":[{"key":"A","text":"文化自信"},{"key":"B","text":"理论自信"},{"key":"C","text":"制度自信"},{"key":"D","text":"道路自信"}],"answer":["C"],"explanation":"制度自信是推进国家治理现代化的思想基础，只有坚定制度自信，才能不断坚持和完善中国特色社会主义制度。"},{"id":511,"chapter":"第五章 全面深化改革","type":"single","typeText":"单选题","score":3.0,"question":"坚持重大改革于法有据。全面深化改革开放是一场深刻的制度变革，制度的“立”和“破”必须于法有据。( )如鸟之两翼、车之两轮，相辅相成、相伴而生。","options":[{"key":"A","text":"改革和规则"},{"key":"B","text":"改革和法治"},{"key":"C","text":"改革与决策"},{"key":"D","text":"开放与合作"}],"answer":["B"],"explanation":"改革和法治是相辅相成的关系，改革要在法治框架内推进，法治要为改革提供保障和规范。"},{"id":512,"chapter":"第五章 全面深化改革","type":"single","typeText":"单选题","score":3.0,"question":"推进国家治理体系和治理能力现代化，必须把中国特色社会主义制度优势转化为国家( )。","options":[{"key":"A","text":"治理效率"},{"key":"B","text":"治理效能"},{"key":"C","text":"治理成效"},{"key":"D","text":"治理成果"}],"answer":["B"],"explanation":"治理效能是制度优势在实践中的具体体现，提升治理效能是推进国家治理现代化的核心目标。"},{"id":513,"chapter":"第五章 全面深化改革","type":"single","typeText":"单选题","score":3.0,"question":"正确处理好( )的关系，是我国改革开放的一条重要经验。","options":[{"key":"A","text":"系统整体协同"},{"key":"B","text":"顶层设计和摸着石头过河"},{"key":"C","text":"改革发展稳定"},{"key":"D","text":"胆子要大步子要稳"}],"answer":["C"],"explanation":"改革发展稳定三者关系是改革开放进程中必须统筹把握的重要关系，稳定是前提，改革是动力，发展是目标。"},{"id":514,"chapter":"第五章 全面深化改革","type":"single","typeText":"单选题","score":3.0,"question":"党的十九届四中全会，对坚持和完善中国特色社会主义制度、推进国家治理体系和治理能力现代化作出总体擘画。以下表述不正确的是( )。","options":[{"key":"A","text":"党成立100年时，在各方面制度更加成熟更加定型上取得明显成效"},{"key":"B","text":"2035年，各方面制度更加完善，基本实现国家治理体系和治理能力现代化"},{"key":"C","text":"新中国成立100年时，全面实现国家治理体系和治理能力现代化，中国特色社会主义制度更加巩固、优越性充分展现"},{"key":"D","text":"本世纪中叶，全面建成符合社会主义现代化发展的国家治理体系"}],"answer":["D"],"explanation":"党的十九届四中全会提出的是到新中国成立100年时全面实现国家治理体系和治理能力现代化，而非“全面建成符合社会主义现代化发展的国家治理体系”。"},{"id":515,"chapter":"第五章 全面深化改革","type":"single","typeText":"单选题","score":3.0,"question":"推进改革的目的是要不断推进我国社会主义制度( )，赋予社会主义新的生机活力。","options":[{"key":"A","text":"自我完善和发展"},{"key":"B","text":"现实性和实效性"},{"key":"C","text":"人民性和整体性"},{"key":"D","text":"整体推进和全面发展"}],"answer":["A"],"explanation":"改革的本质是社会主义制度的自我完善和发展，通过改革使制度更加成熟定型，焕发新的活力。"},{"id":516,"chapter":"第五章 全面深化改革","type":"single","typeText":"单选题","score":3.0,"question":"( )是新时代坚持和发展中国特色社会主义的根本动力。","options":[{"key":"A","text":"解放思想 实事求是"},{"key":"B","text":"全面深化改革开放"},{"key":"C","text":"发展社会主义市场经济"},{"key":"D","text":"坚持党的全面领导"}],"answer":["B"],"explanation":"全面深化改革开放是新时代坚持和发展中国特色社会主义的根本动力，是决定当代中国命运的关键一招。"},{"id":517,"chapter":"第五章 全面深化改革","type":"single","typeText":"单选题","score":3.0,"question":"继续扩大对外开放，构建更高水平开放型经济新体制，要依托我国超大规模市场优势，以( )吸引全球资源要素，提升贸易投资合作质量和水平。","options":[{"key":"A","text":"国内大循环"},{"key":"B","text":"国内国外双循环"},{"key":"C","text":"新质生产力"},{"key":"D","text":"社会主义市场经济"}],"answer":["A"],"explanation":"国内大循环是主体，通过扩大内需、优化供给体系，增强对全球要素资源的吸引力，推动高水平对外开放。"},{"id":518,"chapter":"第五章 全面深化改革","type":"single","typeText":"单选题","score":3.0,"question":"国家治理体系是在党领导下管理国家的制度体系，包括经济、政治、文化、社会、生态文明和( )等各领域体制机制、法律法规安排，是一整套紧密相连、相互协调的国家制度。","options":[{"key":"A","text":"国家统一"},{"key":"B","text":"军队建设"},{"key":"C","text":"党的建设"},{"key":"D","text":"人类命运共同体"}],"answer":["C"],"explanation":"党的建设是国家治理体系的重要组成部分，坚持和完善党的领导制度体系是国家治理的关键。"},{"id":519,"chapter":"第五章 全面深化改革","type":"single","typeText":"单选题","score":3.0,"question":"习近平指出：\"这'三个进一步解放'既是改革的目的，又是改革的条件\"，其中提到的\"三个进一步解放\"是进一步解放思想、进一步解放和发展社会生产力、进一步( )。","options":[{"key":"A","text":"解放和发展新理念"},{"key":"B","text":"解放和促进改革开放"},{"key":"C","text":"解放和发展新质生产力"},{"key":"D","text":"解放和增强社会活力"}],"answer":["D"],"explanation":"\"三个进一步解放\"包括解放思想、解放和发展社会生产力、解放和增强社会活力，是全面深化改革的重要指导原则。"},{"id":520,"chapter":"第五章 全面深化改革","type":"single","typeText":"单选题","score":3.0,"question":"把全面深化改革不断引向深入，要聚焦( )中的重大问题，注重统筹全局、把握重点，抓好重大改革任务攻坚克难。","options":[{"key":"A","text":"全面建设社会主义现代化国家"},{"key":"B","text":"中华民族伟大复兴"},{"key":"C","text":"建设社会主义市场经济"},{"key":"D","text":"建设富强、民主、文明、和谐、美丽的社会主义现代化强国"}],"answer":["A"],"explanation":"全面深化改革要紧紧围绕全面建设社会主义现代化国家的目标任务，聚焦重大问题和关键环节推进改革攻坚。"},{"id":521,"chapter":"第五章 全面深化改革","type":"multiple","typeText":"多选题","score":4.0,"question":"( )是全面深化改革的出发点和落脚点。","options":[{"key":"A","text":"实现两个百年目标"},{"key":"B","text":"促进社会公平正义"},{"key":"C","text":"增进人民福祉"},{"key":"D","text":"建成世界一流强国"}],"answer":["B","C"],"explanation":"全面深化改革必须坚持以促进社会公平正义、增进人民福祉为出发点和落脚点，体现以人民为中心的发展思想。"},{"id":522,"chapter":"第五章 全面深化改革","type":"multiple","typeText":"多选题","score":4.0,"question":"全面深化改革的总目标是( )。","options":[{"key":"A","text":"实现两个百年目标"},{"key":"B","text":"实现中国梦"},{"key":"C","text":"完善和发展中国特色社会主义制度"},{"key":"D","text":"推进国家治理体系和治理能力现代化"}],"answer":["C","D"],"explanation":"党的十八届三中全会明确提出，全面深化改革的总目标是完善和发展中国特色社会主义制度，推进国家治理体系和治理能力现代化。"},{"id":523,"chapter":"第五章 全面深化改革","type":"multiple","typeText":"多选题","score":4.0,"question":"治理能力是运用国家制度管理国家各方面事务的能力，它包括( )等各个方面各个领域的治理能力。","options":[{"key":"A","text":"改革发展稳定"},{"key":"B","text":"内政外交国防"},{"key":"C","text":"治党治国治军"},{"key":"D","text":"社会和谐进步"}],"answer":["A","B","C"],"explanation":"治理能力涵盖国家治理各领域各环节，包括改革发展稳定、内政外交国防、治党治国治军等各方面的能力。"},{"id":524,"chapter":"第五章 全面深化改革","type":"multiple","typeText":"多选题","score":4.0,"question":"全面深化改革必须坚持和完善( )。","options":[{"key":"A","text":"中国特色社会主义制度"},{"key":"B","text":"国家治理体系"},{"key":"C","text":"经济社会发展"},{"key":"D","text":"政府宏观调控"}],"answer":["A","B"],"explanation":"全面深化改革必须坚持和完善中国特色社会主义制度和国家治理体系，这是改革的总方向和根本遵循。"},{"id":525,"chapter":"第五章 全面深化改革","type":"multiple","typeText":"多选题","score":4.0,"question":"坚持全面深化改革开放的正确方向( )。","options":[{"key":"A","text":"必须坚持和完善党的全面领导、坚持和完善中国特色社会主义制度"},{"key":"B","text":"必须坚持社会主义市场经济改革方向"},{"key":"C","text":"必须坚持以人民为中心，促进社会公平正义、增进人民福祉"},{"key":"D","text":"必须有利于进一步解放思想、进一步解放和发展社会生产力、进一步解放和增强社会活力"}],"answer":["A","C","D"],"explanation":"坚持全面深化改革开放的正确方向，核心是坚持党的领导、完善中国特色社会主义制度，根本立场是以人民为中心，重要原则是推动“三个进一步解放”。"},{"id":526,"chapter":"第五章 全面深化改革","type":"multiple","typeText":"多选题","score":4.0,"question":"中国政府倡议，共建“一带一路”恪守联合国宪章的宗旨和原则，坚持( )。","options":[{"key":"A","text":"开放合作"},{"key":"B","text":"和谐包容"},{"key":"C","text":"市场运作"},{"key":"D","text":"互利共赢"}],"answer":["A","B","C","D"],"explanation":"“一带一路”建设坚持开放合作、和谐包容、市场运作、互利共赢的原则，致力于推动沿线国家共同发展。"},{"id":527,"chapter":"第五章 全面深化改革","type":"multiple","typeText":"多选题","score":4.0,"question":"五四运动以来，我国发生的三大历史性事件( )，是近代以来实现中华民族伟大复兴的三大里程碑。","options":[{"key":"A","text":"建立中国共产党"},{"key":"B","text":"成立中华人民共和国"},{"key":"C","text":"社会主义制度在中国确立"},{"key":"D","text":"推进改革开放和中国特色社会主义事业"}],"answer":["A","B","D"],"explanation":"建立中国共产党、成立中华人民共和国、推进改革开放和中国特色社会主义事业，是近代以来实现中华民族伟大复兴的三大里程碑事件。"},{"id":528,"chapter":"第五章 全面深化改革","type":"multiple","typeText":"多选题","score":4.0,"question":"改革开放永无止境是( )。","options":[{"key":"A","text":"是社会基本矛盾运动规律的深刻反映"},{"key":"B","text":"是总结世界社会主义实践经验得出的重要结论"},{"key":"C","text":"是推进党和人民事业发展的必然要求"},{"key":"D","text":"是实现中华民族伟大复兴的必然要求"}],"answer":["A","B","C"],"explanation":"改革开放永无止境，源于社会基本矛盾运动规律，是世界社会主义实践的经验总结，是推进党和人民事业发展的必然要求。"},{"id":529,"chapter":"第五章 全面深化改革","type":"multiple","typeText":"多选题","score":4.0,"question":"中国将继续实施( )、( )、( )对外开放，坚持走中国式现代化道路，建设更高水平开放型经济新体制。","options":[{"key":"A","text":"更广空间"},{"key":"B","text":"更大范围"},{"key":"C","text":"更宽领域"},{"key":"D","text":"更深层次"}],"answer":["B","C","D"],"explanation":"中国将实施更大范围、更宽领域、更深层次的对外开放，推动形成全面开放新格局，建设更高水平开放型经济新体制。"},{"id":530,"chapter":"第五章 全面深化改革","type":"multiple","typeText":"多选题","score":4.0,"question":"推进国家治理体系和治理能力现代化，必须( )。","options":[{"key":"A","text":"坚定中国特色社会主义制度自信"},{"key":"B","text":"更好发挥中国特色社会主义制度优势"},{"key":"C","text":"把中国特色社会主义制度优势转化为国家治理效能"},{"key":"D","text":"实施好“六个紧紧围绕”的路线图"}],"answer":["A","B","C"],"explanation":"推进国家治理现代化必须坚定制度自信、发挥制度优势、推动制度优势转化为治理效能，这是实现治理现代化的关键路径。"},{"id":601,"chapter":"第六章 推动高质量发展","type":"single","typeText":"单选题","score":7.0,"question":"我国经济已由高速增长阶段转向( )。","options":[{"key":"A","text":"高质量发展阶段"},{"key":"B","text":"高效益发展阶段"},{"key":"C","text":"高效率发展阶段"},{"key":"D","text":"高级形态发展阶段"}],"answer":["A"],"explanation":"我国经济发展进入新常态，已由高速增长阶段转向高质量发展阶段，这是适应新发展阶段的必然要求。"},{"id":602,"chapter":"第六章 推动高质量发展","type":"single","typeText":"单选题","score":6.0,"question":"习近平指出，新时代抓发展必须更加突出发展理念，必须坚定不移贯彻的新发展理念是( )。","options":[{"key":"A","text":"创新、稳定、绿色、开放、共享"},{"key":"B","text":"稳定、协调、绿色、开放、共享"},{"key":"C","text":"创新、协调、绿色、开放、共享"},{"key":"D","text":"创新、协调、稳定、开放、共享"}],"answer":["C"],"explanation":"新发展理念是创新、协调、绿色、开放、共享，是引领我国发展全局深刻变革的科学理念。"},{"id":603,"chapter":"第六章 推动高质量发展","type":"single","typeText":"单选题","score":6.0,"question":"引领发展的第一动力是( )。","options":[{"key":"A","text":"创新"},{"key":"B","text":"协调"},{"key":"C","text":"绿色"},{"key":"D","text":"开放"}],"answer":["A"],"explanation":"创新是引领发展的第一动力，是建设现代化经济体系的战略支撑。"},{"id":604,"chapter":"第六章 推动高质量发展","type":"single","typeText":"单选题","score":6.0,"question":"持续健康发展的内在要求是( )。","options":[{"key":"A","text":"创新"},{"key":"B","text":"协调"},{"key":"C","text":"绿色"},{"key":"D","text":"开放"}],"answer":["B"],"explanation":"协调是持续健康发展的内在要求，注重解决发展不平衡问题，增强发展的整体性。"},{"id":605,"chapter":"第六章 推动高质量发展","type":"single","typeText":"单选题","score":6.0,"question":"国家繁荣发展的必由之路是( )。","options":[{"key":"A","text":"创新"},{"key":"B","text":"协调"},{"key":"C","text":"绿色"},{"key":"D","text":"开放"}],"answer":["D"],"explanation":"开放是国家繁荣发展的必由之路，要推动形成全面开放新格局。"},{"id":606,"chapter":"第六章 推动高质量发展","type":"single","typeText":"单选题","score":6.0,"question":"永续发展的内在条件和人民对美好生活追求的重要体现是( )。","options":[{"key":"A","text":"创新"},{"key":"B","text":"协调"},{"key":"C","text":"绿色"},{"key":"D","text":"开放"}],"answer":["C"],"explanation":"绿色是永续发展的内在条件，体现了人与自然和谐共生，是人民美好生活需要的重要内容。"},{"id":607,"chapter":"第六章 推动高质量发展","type":"single","typeText":"单选题","score":6.0,"question":"构建高水平社会主义市场经济体制，关键是( )。","options":[{"key":"A","text":"处理好政府和市场的关系"},{"key":"B","text":"使市场在资源配置中起基础性作用"},{"key":"C","text":"处理好“引进来”和“走出去”的关系"},{"key":"D","text":"处理好公有制经济和非公有制经济的关系"}],"answer":["A"],"explanation":"处理好政府和市场的关系是构建高水平社会主义市场经济体制的关键，既要发挥市场在资源配置中的决定性作用，又要更好发挥政府作用。"},{"id":608,"chapter":"第六章 推动高质量发展","type":"single","typeText":"单选题","score":6.0,"question":"根据我国发展阶段、发展环境、发展条件的变化，必须构建的新发展格局是( )。","options":[{"key":"A","text":"以国内大循环为主体，国际国内双循环相互促进"},{"key":"B","text":"以国际大循环为主体，国际国内双循环相互促进"},{"key":"C","text":"以国内大循环为主体"},{"key":"D","text":"以国际大循环为主体"}],"answer":["A"],"explanation":"构建以国内大循环为主体、国内国际双循环相互促进的新发展格局，是适应新发展阶段、贯彻新发展理念的战略抉择。"},{"id":609,"chapter":"第六章 推动高质量发展","type":"single","typeText":"单选题","score":6.0,"question":"国家经济现代化的重要标志是( )。","options":[{"key":"A","text":"现代化产业体系"},{"key":"B","text":"现代化市场体系"},{"key":"C","text":"现代化收入分配体系"},{"key":"D","text":"现代化城乡区域发展体系"}],"answer":["A"],"explanation":"现代化产业体系是国家经济现代化的重要标志，是实现高质量发展的基础支撑。"},{"id":610,"chapter":"第六章 推动高质量发展","type":"multiple","typeText":"多选题","score":9.0,"question":"习近平指出：“全面建成小康社会、实现第一个百年奋斗目标之后，我们要乘势而上开启全面建设社会主义现代化国家新征程、向第二个百年奋斗目标进军，这标志着我国进入了一个新发展阶段。”新发展阶段是( )。","options":[{"key":"A","text":"我国社会主义初级阶段历史进程中的一个重要阶段"},{"key":"B","text":"是中国共产党带领人民迎来从站起来富起来到强起来历史性跨越的新阶段"},{"key":"C","text":"是全面建设社会主义现代化国家的重要阶段"},{"key":"D","text":"是向第二个百年奋斗目标进军的重要阶段"}],"answer":["A","B","C","D"],"explanation":"新发展阶段是我国社会主义初级阶段中的一个重要阶段，是党带领人民实现历史性跨越、开启全面建设社会主义现代化国家新征程、向第二个百年奋斗目标进军的关键阶段。"},{"id":611,"chapter":"第六章 推动高质量发展","type":"multiple","typeText":"多选题","score":9.0,"question":"高质量发展( )。","options":[{"key":"A","text":"是能够很好满足人民日益增长的美好生活需要的发展"},{"key":"B","text":"是体现新发展理念的发展"},{"key":"C","text":"是共享成为根本目的的发展"},{"key":"D","text":"是从“有没有”转向“好不好”的发展"}],"answer":["A","B","C","D"],"explanation":"高质量发展是体现新发展理念的发展，根本目的是满足人民美好生活需要，实现从量的扩张转向质的提升。"},{"id":612,"chapter":"第六章 推动高质量发展","type":"multiple","typeText":"多选题","score":9.0,"question":"社会主义基本经济制度包括( )。","options":[{"key":"A","text":"公有制为主体，多种所有制经济共同发展"},{"key":"B","text":"按劳分配为主体，多种分配方式并存"},{"key":"C","text":"社会主义市场经济体制"},{"key":"D","text":"国有资产的管理制度"}],"answer":["A","B","C"],"explanation":"社会主义基本经济制度包括公有制为主体、多种所有制经济共同发展，按劳分配为主体、多种分配方式并存，社会主义市场经济体制。"},{"id":613,"chapter":"第六章 推动高质量发展","type":"multiple","typeText":"多选题","score":9.0,"question":"公有制经济包括( )。","options":[{"key":"A","text":"国有经济"},{"key":"B","text":"集体经济"},{"key":"C","text":"混合所有制经济中的国有成分和集体成分"},{"key":"D","text":"民营经济"}],"answer":["A","B","C"],"explanation":"公有制经济包括国有经济、集体经济以及混合所有制经济中的国有成分和集体成分，是我国经济制度的基础。"},{"id":614,"chapter":"第六章 推动高质量发展","type":"multiple","typeText":"多选题","score":9.0,"question":"非公有制经济包括( )。","options":[{"key":"A","text":"个体经济"},{"key":"B","text":"私营经济"},{"key":"C","text":"港澳台投资经济"},{"key":"D","text":"混合所有制经济中的非国有成分和非集体成分"}],"answer":["A","B","C","D"],"explanation":"非公有制经济包括个体经济、私营经济、港澳台投资经济、外商投资经济以及混合所有制经济中的非公有成分，是社会主义市场经济的重要组成部分。"},{"id":701,"chapter":"第七章 社会主义现代化建设的教育、科技、人才战略","type":"single","typeText":"单选题","score":3.0,"question":"必须坚持( )是第一生产力。","options":[{"key":"A","text":"人才"},{"key":"B","text":"资源"},{"key":"C","text":"科技"},{"key":"D","text":"环境"}],"answer":["C"],"explanation":"科学技术是第一生产力，这是邓小平同志提出的重要论断，强调了科技在经济社会发展中的决定性作用。"},{"id":702,"chapter":"第七章 社会主义现代化建设的教育、科技、人才战略","type":"single","typeText":"单选题","score":3.0,"question":"( )是发展第一动力。","options":[{"key":"A","text":"科技"},{"key":"B","text":"人才"},{"key":"C","text":"创新"},{"key":"D","text":"党的领导"}],"answer":["C"],"explanation":"创新是引领发展的第一动力，是推动经济社会发展的核心力量。"},{"id":703,"chapter":"第七章 社会主义现代化建设的教育、科技、人才战略","type":"single","typeText":"单选题","score":3.0,"question":"( )提出“科学技术是第一生产力”。","options":[{"key":"A","text":"毛泽东"},{"key":"B","text":"邓小平"},{"key":"C","text":"习近平"},{"key":"D","text":"胡锦涛"}],"answer":["B"],"explanation":"邓小平同志在改革开放初期提出了“科学技术是第一生产力”的重要论断，为我国科技事业发展指明了方向。"},{"id":704,"chapter":"第七章 社会主义现代化建设的教育、科技、人才战略","type":"single","typeText":"单选题","score":3.0,"question":"科教兴国是我国的( )。","options":[{"key":"A","text":"基本国策"},{"key":"B","text":"基本政策"},{"key":"C","text":"基本路线"},{"key":"D","text":"基本战略"}],"answer":["A"],"explanation":"科教兴国是我国的一项基本国策，强调科技和教育在国家发展中的基础性、先导性作用。"},{"id":705,"chapter":"第七章 社会主义现代化建设的教育、科技、人才战略","type":"single","typeText":"单选题","score":3.0,"question":"( )是民族振兴、社会进步的基石。","options":[{"key":"A","text":"科技"},{"key":"B","text":"教育"},{"key":"C","text":"共同富裕"},{"key":"D","text":"人才"}],"answer":["B"],"explanation":"教育是民族振兴、社会进步的基石，是提高国民素质、促进人的全面发展的根本途径。"},{"id":706,"chapter":"第七章 社会主义现代化建设的教育、科技、人才战略","type":"single","typeText":"单选题","score":3.0,"question":"( )是发展教育的根本尺度。","options":[{"key":"A","text":"科技突破"},{"key":"B","text":"人民满意"},{"key":"C","text":"实现共同富裕"},{"key":"D","text":"发展生产力"}],"answer":["B"],"explanation":"人民满意是发展教育的根本尺度，办好人民满意的教育是教育工作的出发点和落脚点。"},{"id":707,"chapter":"第七章 社会主义现代化建设的教育、科技、人才战略","type":"single","typeText":"单选题","score":3.0,"question":"( )是国家强盛之基、安全之要。","options":[{"key":"A","text":"科技自立自强"},{"key":"B","text":"人才引进"},{"key":"C","text":"共同富裕"},{"key":"D","text":"改革开放"}],"answer":["A"],"explanation":"科技自立自强是国家强盛之基、安全之要，是实现国家长治久安和可持续发展的根本保障。"},{"id":708,"chapter":"第七章 社会主义现代化建设的教育、科技、人才战略","type":"single","typeText":"单选题","score":3.0,"question":"( )是我们攀登世界科技高峰的必由之路。","options":[{"key":"A","text":"自主创新"},{"key":"B","text":"脱贫攻坚"},{"key":"C","text":"守正创新"},{"key":"D","text":"信息技术"}],"answer":["A"],"explanation":"自主创新是我们攀登世界科技高峰的必由之路，是掌握关键核心技术、实现科技自立自强的根本途径。"},{"id":709,"chapter":"第七章 社会主义现代化建设的教育、科技、人才战略","type":"single","typeText":"单选题","score":3.0,"question":"必须坚持教育优先发展，把( )作为教育的根本任务，办好人民满意的教育。","options":[{"key":"A","text":"立德树人"},{"key":"B","text":"社会实践"},{"key":"C","text":"创新拔尖"},{"key":"D","text":"专业技术"}],"answer":["A"],"explanation":"立德树人是教育的根本任务，是培养德智体美劳全面发展的社会主义建设者和接班人的核心要求。"},{"id":710,"chapter":"第七章 社会主义现代化建设的教育、科技、人才战略","type":"single","typeText":"单选题","score":3.0,"question":"( )是科技创新的源头。我国面临的很多“卡脖子”技术问题，根子是基础理论研究跟不上。","options":[{"key":"A","text":"应用研究"},{"key":"B","text":"国家实验室"},{"key":"C","text":"经济特区"},{"key":"D","text":"基础研究"}],"answer":["D"],"explanation":"基础研究是科技创新的源头活水，是解决“卡脖子”技术问题、实现科技自立自强的根基。"},{"id":711,"chapter":"第七章 社会主义现代化建设的教育、科技、人才战略","type":"single","typeText":"单选题","score":3.0,"question":"落实立德树人根本任务，必须着力解决好(ABC)的问题，这是教育的根本问题，也是( )的核心课题。","options":[{"key":"A","text":"培养什么人"},{"key":"B","text":"怎样培养人"},{"key":"C","text":"为谁培养人"},{"key":"D","text":"建设教育强国"}],"answer":["D"],"explanation":"落实立德树人根本任务，必须解决好培养什么人、怎样培养人、为谁培养人这一根本问题，这也是建设教育强国必须回答的核心课题。"},{"id":712,"chapter":"第七章 社会主义现代化建设的教育、科技、人才战略","type":"multiple","typeText":"多选题","score":4.0,"question":"全面建设社会主义现代化国家，( )。","options":[{"key":"A","text":"教育是根本"},{"key":"B","text":"科技是关键"},{"key":"C","text":"人才是基础"},{"key":"D","text":"改革是保证"}],"answer":["A","B","C"],"explanation":"教育是根本，科技是关键，人才是基础，三者相辅相成，共同构成全面建设社会主义现代化国家的重要支撑。"},{"id":713,"chapter":"第七章 社会主义现代化建设的教育、科技、人才战略","type":"multiple","typeText":"多选题","score":4.0,"question":"实施( )是增强综合国力、满足人民群众美好生活需要的必然要求，是建设教育强国、科技强国、人才强国的重大举措。","options":[{"key":"A","text":"科教兴国战略"},{"key":"B","text":"人才强国战略"},{"key":"C","text":"创新驱动发展战略"},{"key":"D","text":"“四个全面战略”"}],"answer":["A","B","C"],"explanation":"科教兴国战略、人才强国战略、创新驱动发展战略是相互联系、相互支撑的重大战略，共同服务于国家发展和现代化建设。"},{"id":714,"chapter":"第七章 社会主义现代化建设的教育、科技、人才战略","type":"multiple","typeText":"多选题","score":4.0,"question":"实施科教兴国战略，( )。","options":[{"key":"A","text":"是应对新时代环境变化的必然要求"},{"key":"B","text":"是建设创新型国家的必然要求"},{"key":"C","text":"是应对国际竞争的有力举措"},{"key":"D","text":"是决胜全面小康社会的重大部署"}],"answer":["A","B","C"],"explanation":"实施科教兴国战略是适应时代发展、建设创新型国家、应对国际竞争的必然选择和重要举措。"},{"id":715,"chapter":"第七章 社会主义现代化建设的教育、科技、人才战略","type":"multiple","typeText":"多选题","score":4.0,"question":"实施人才强国战略，( )，实施更加积极、更加开放、更加有效的人才政策。","options":[{"key":"A","text":"要坚持党管人才原则"},{"key":"B","text":"坚持尊重劳动、尊重知识、尊重人才、尊重创造"},{"key":"C","text":"完善人才战略布局"},{"key":"D","text":"深化人才发展体制机制改革"}],"answer":["A","B","C","D"],"explanation":"实施人才强国战略必须坚持党管人才，落实“四个尊重”，完善布局、深化改革，构建科学有效的人才政策体系。"},{"id":716,"chapter":"第七章 社会主义现代化建设的教育、科技、人才战略","type":"multiple","typeText":"多选题","score":4.0,"question":"实施创新驱动发展战略，( )，让创新成为全社会的共同行动。","options":[{"key":"A","text":"要坚持面向世界科技前沿、面向经济主战场"},{"key":"B","text":"要坚持面向国家重大需求、面向人民生命健康"},{"key":"C","text":"坚持科技创新，增强自主创新能力"},{"key":"D","text":"坚决打赢关键核心技术攻坚战"}],"answer":["A","B","C","D"],"explanation":"实施创新驱动发展战略必须坚持“四个面向”，增强自主创新能力，攻坚关键核心技术，推动全社会创新活力迸发。"},{"id":717,"chapter":"第七章 社会主义现代化建设的教育、科技、人才战略","type":"multiple","typeText":"多选题","score":4.0,"question":"教育优先发展，要做到( )，使我国教育越办越好。","options":[{"key":"A","text":"经济社会发展规划优先安排教育发展"},{"key":"B","text":"财政资金投入优先保障教育投入"},{"key":"C","text":"公共资源配置优先满足教育和人力资源开发需要"},{"key":"D","text":"推动健全优先发展教育事业的体制机制"}],"answer":["A","B","C","D"],"explanation":"教育优先发展要在规划、投入、资源配置和制度建设等方面系统落实，形成保障教育事业持续健康发展的长效机制。"},{"id":718,"chapter":"第七章 社会主义现代化建设的教育、科技、人才战略","type":"multiple","typeText":"多选题","score":4.0,"question":"建设教育强国是( )。","options":[{"key":"A","text":"全面建成社会主义现代化强国的战略先导"},{"key":"B","text":"是实现高水平科技自立自强的重要支撑"},{"key":"C","text":"是以中国式现代化全面推进中华民族伟大复兴的基础工程"},{"key":"D","text":"必须把教育事业放在优先发展的战略位置"}],"answer":["A","B","C","D"],"explanation":"建设教育强国是实现国家现代化和民族复兴的基础性、战略性工程，必须坚持教育优先发展战略地位。"},{"id":719,"chapter":"第七章 社会主义现代化建设的教育、科技、人才战略","type":"multiple","typeText":"多选题","score":4.0,"question":"必须坚持教育( )。","options":[{"key":"A","text":"为人民服务"},{"key":"B","text":"为中国共产党治国理政服务"},{"key":"C","text":"为巩固和发展中国特色社会主义制度服务"},{"key":"D","text":"为改革开放和社会主义现代化建设服务"}],"answer":["A","B","C","D"],"explanation":"教育必须坚持“四个服务”方向，全面贯彻党的教育方针，落实立德树人根本任务。"},{"id":720,"chapter":"第七章 社会主义现代化建设的教育、科技、人才战略","type":"multiple","typeText":"多选题","score":4.0,"question":"我们培养的人，( )。","options":[{"key":"A","text":"要坚定共产主义远大理想和中国特色社会主义共同理想"},{"key":"B","text":"要有高尚的道德品质，厚植爱国主义情怀"},{"key":"C","text":"要养成刻苦学习的习惯"},{"key":"D","text":"要积极投身社会实践，增长经验和技能"}],"answer":["A","B","C","D"],"explanation":"培养的人应当德才兼备，既有坚定理想信念和爱国情怀，又有扎实学识和实践能力，能够担当民族复兴大任。"},{"id":721,"chapter":"第七章 社会主义现代化建设的教育、科技、人才战略","type":"multiple","typeText":"多选题","score":4.0,"question":"办好人民满意的教育，( )。","options":[{"key":"A","text":"大力促进教育公平"},{"key":"B","text":"加快建设高质量教育体系"},{"key":"C","text":"提升教育服务经济社会发展能力"},{"key":"D","text":"坚持深化教育改革创新"},{"key":"E","text":"坚持把教师队伍建设作为基础工作"}],"answer":["A","B","C","D","E"],"explanation":"办好人民满意的教育需要多措并举，促进公平、提升质量、增强服务能力、深化改革、建强教师队伍。"},{"id":722,"chapter":"第七章 社会主义现代化建设的教育、科技、人才战略","type":"multiple","typeText":"多选题","score":4.0,"question":"实现高水平科技自立自强是( )。","options":[{"key":"A","text":"应对风险挑战和维护国家利益的必然选择"},{"key":"B","text":"构建新发展格局的内在要求"},{"key":"C","text":"推动高质量发展的内在要求"},{"key":"D","text":"满足人民美好生活需要的内在要求"}],"answer":["A","B","C","D"],"explanation":"高水平科技自立自强是国家安全、发展格局、高质量发展和人民美好生活需要的重要保障和内在要求。"},{"id":723,"chapter":"第七章 社会主义现代化建设的教育、科技、人才战略","type":"multiple","typeText":"多选题","score":4.0,"question":"建设人才强国，必须( )。","options":[{"key":"A","text":"走好人才自主培养之路"},{"key":"B","text":"加快建设世界重要人才中心和创新高地"},{"key":"C","text":"坚持党对人才工作的全面领导"},{"key":"D","text":"深化人才发展体制机制改革"},{"key":"E","text":"营造识才爱才敬才用才的环境"}],"answer":["A","B","C","D","E"],"explanation":"建设人才强国要坚持自主培养、构建人才高地、加强党的领导、深化改革、优化环境，全方位培养、引进、用好人才。"},{"id":724,"chapter":"第七章 社会主义现代化建设的教育、科技、人才战略","type":"judge","typeText":"判断题","score":3.0,"question":"实现高水平科技自立自强是国家强盛和民族复兴的战略基石。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":["A"],"explanation":"高水平科技自立自强是关系国家发展全局和民族复兴的战略基石，必须牢牢掌握在自己手中。"},{"id":725,"chapter":"第七章 社会主义现代化建设的教育、科技、人才战略","type":"judge","typeText":"判断题","score":3.0,"question":"全面建成社会主义现代化强国关键看科技自立自强。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":["A"],"explanation":"科技自立自强是全面建成社会主义现代化强国的关键支撑，是赢得发展主动权的根本保障。"},{"id":726,"chapter":"第七章 社会主义现代化建设的教育、科技、人才战略","type":"judge","typeText":"判断题","score":3.0,"question":"科技创新是百年未有之大变局中的一个关键变量，世界主要国家纷纷把科技创新作为国际战略博弈的主要战场。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":["A"],"explanation":"科技创新是大变局中的关键变量，已成为国际竞争的核心领域和战略博弈的主战场。"},{"id":727,"chapter":"第七章 社会主义现代化建设的教育、科技、人才战略","type":"judge","typeText":"判断题","score":2.0,"question":"把教育技术掌握在自己手中，才能真正掌握竞争和发展的主动权。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":["B"],"explanation":"应为“把科技命脉掌握在自己手中”，科技而非教育技术，是掌握竞争和发展主动权的关键。"},{"id":728,"chapter":"第七章 社会主义现代化建设的教育、科技、人才战略","type":"judge","typeText":"判断题","score":2.0,"question":"培养人才是国家和民族长远发展大计。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":["A"],"explanation":"人才是国家和民族长远发展的根本大计，必须把人才培养摆在突出位置。"},{"id":729,"chapter":"第七章 社会主义现代化建设的教育、科技、人才战略","type":"judge","typeText":"判断题","score":2.0,"question":"坚持党对人才工作的全面领导，这是做好人才工作的根本保证。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":["A"],"explanation":"党的领导是人才工作沿着正确方向前进的根本保证，必须坚持党管人才原则。"},{"id":730,"chapter":"第七章 社会主义现代化建设的教育、科技、人才战略","type":"judge","typeText":"判断题","score":2.0,"question":"科技是富国之本、兴邦大计。科技已经成为推动社会发展最活跃、最积极的因素。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":["B"],"explanation":"应为“教育是富国之本、兴邦大计”，教育在推动社会发展中具有基础性、先导性作用，科技是重要驱动力。"},{"id":731,"chapter":"第七章 社会主义现代化建设的教育、科技、人才战略","type":"judge","typeText":"判断题","score":2.0,"question":"人才是国之大计、党之大计，在国家发展中始终具有基础性先导性全局性地位。","options":[{"key":"A","text":"对"},{"key":"B","text":"错"}],"answer":["B"],"explanation":"应为“教育是国之大计、党之大计”，人才是支撑，教育才具有基础性、先导性、全局性地位。"},{"id":801,"chapter":"第八章 发展全过程人民民主","type":"single","typeText":"单选题","score":1.0,"question":"我国是工人阶级领导的、以工农联盟为基础的( )的社会主义国家，国家一切权力属于人民。","options":[{"key":"A","text":"人民民主专政"},{"key":"B","text":"人民当家作主"},{"key":"C","text":"中国共产党领导"},{"key":"D","text":"民主专政"}],"answer":["A"],"explanation":"我国是工人阶级领导的、以工农联盟为基础的人民民主专政的社会主义国家，人民民主专政是我国的国体。"},{"id":802,"chapter":"第八章 发展全过程人民民主","type":"single","typeText":"单选题","score":1.0,"question":"( )是人民当家作主和依法治国的根本保证。","options":[{"key":"A","text":"人民民主"},{"key":"B","text":"党的领导"},{"key":"C","text":"宪法"},{"key":"D","text":"全过程民主"}],"answer":["B"],"explanation":"党的领导是人民当家作主和依法治国的根本保证，是中国特色社会主义政治发展道路最本质的特征。"},{"id":803,"chapter":"第八章 发展全过程人民民主","type":"single","typeText":"单选题","score":1.0,"question":"人民当家作主是社会主义民主政治的本质特征，( )是党领导人民治理国家的基本方式。","options":[{"key":"A","text":"依法治国"},{"key":"B","text":"坚持系统观念"},{"key":"C","text":"全过程民主"},{"key":"D","text":"民主集中制"}],"answer":["A"],"explanation":"依法治国是党领导人民治理国家的基本方式，是实现人民当家作主的重要保障。"},{"id":804,"chapter":"第八章 发展全过程人民民主","type":"single","typeText":"单选题","score":1.0,"question":"( )是党克敌制胜、执政兴国的重要法宝，是团结海内外全体中华儿女实现中华民族伟大复兴的重要法宝。","options":[{"key":"A","text":"协商民主"},{"key":"B","text":"统一战线"},{"key":"C","text":"全过程人民民主"},{"key":"D","text":"实现中华民族伟大复兴"}],"answer":["B"],"explanation":"统一战线是党克敌制胜、执政兴国的重要法宝，也是实现中华民族伟大复兴的重要法宝。"},{"id":805,"chapter":"第八章 发展全过程人民民主","type":"single","typeText":"单选题","score":1.0,"question":"( )是统一战线最核心、最根本的问题。","options":[{"key":"A","text":"大团结大联合"},{"key":"B","text":"广交朋友"},{"key":"C","text":"凝聚人心"},{"key":"D","text":"坚持党的领导"}],"answer":["D"],"explanation":"坚持党的领导是统一战线最核心、最根本的问题，是巩固和发展统一战线的政治保证。"},{"id":806,"chapter":"第八章 发展全过程人民民主","type":"single","typeText":"单选题","score":1.0,"question":"统战工作的关键是要( )。","options":[{"key":"A","text":"坚持求同存异"},{"key":"B","text":"坚持党的领导"},{"key":"C","text":"坚持同一性"},{"key":"D","text":"坚持多样性"}],"answer":["A"],"explanation":"统战工作的关键是坚持求同存异，既要增进共识，也要尊重差异，实现广泛团结。"},{"id":807,"chapter":"第八章 发展全过程人民民主","type":"single","typeText":"单选题","score":1.0,"question":"社会主义民主的实质是( )。","options":[{"key":"A","text":"民主集中制"},{"key":"B","text":"人民当家作主"},{"key":"C","text":"人民代表大会制度"},{"key":"D","text":"中华民族大团结"}],"answer":["B"],"explanation":"人民当家作主是社会主义民主政治的本质特征和核心要求。"},{"id":808,"chapter":"第八章 发展全过程人民民主","type":"single","typeText":"单选题","score":1.0,"question":"一个国家是不是民主，应该由这个国家的( )来评判，而不应该由外部少数人指手画脚来评判。","options":[{"key":"A","text":"人民"},{"key":"B","text":"执政党"},{"key":"C","text":"社会团体"},{"key":"D","text":"国家性质"}],"answer":["A"],"explanation":"民主是全人类共同价值，但一个国家是否民主，应由该国人民来评判，不应由外部势力单方面定义。"},{"id":809,"chapter":"第八章 发展全过程人民民主","type":"single","typeText":"单选题","score":1.0,"question":"( )是社会主义的生命，没有民主就没有社会主义。","options":[{"key":"A","text":"人民民主"},{"key":"B","text":"人民当家作主"},{"key":"C","text":"以人民为中心"},{"key":"D","text":"坚持人民的主体地位"}],"answer":["A"],"explanation":"人民民主是社会主义的生命，是中国特色社会主义政治发展道路的鲜明旗帜。"},{"id":810,"chapter":"第八章 发展全过程人民民主","type":"single","typeText":"单选题","score":1.0,"question":"( )是中国发展全过程人民民主的根本保证。","options":[{"key":"A","text":"人民当家作主"},{"key":"B","text":"中国特色社会主义制度"},{"key":"C","text":"人民民主专政"},{"key":"D","text":"中国共产党的领导"}],"answer":["D"],"explanation":"中国共产党的领导是中国发展全过程人民民主的根本保证，确保民主发展的正确方向。"},{"id":811,"chapter":"第八章 发展全过程人民民主","type":"single","typeText":"单选题","score":1.0,"question":"( )是指民主的制度安排，实质民主是指民主始终追求的价值目标，二者有机结合。","options":[{"key":"A","text":"程序民主"},{"key":"B","text":"协商民主"},{"key":"C","text":"人民民主"},{"key":"D","text":"全过程人民民主"}],"answer":["A"],"explanation":"程序民主强调民主的制度化安排和运行过程，实质民主强调民主的价值目标和实际成效，二者统一于民主实践。"},{"id":812,"chapter":"第八章 发展全过程人民民主","type":"single","typeText":"单选题","score":1.0,"question":"人民民主是社会主义的生命，( )是社会主义民主政治的本质属性。","options":[{"key":"A","text":"全过程人民民主"},{"key":"B","text":"全面建设社会主义现代化国家"},{"key":"C","text":"全面深化改革"},{"key":"D","text":"全面依法治国"}],"answer":["A"],"explanation":"全过程人民民主是社会主义民主政治的本质属性，是最广泛、最真实、最管用的民主。"},{"id":813,"chapter":"第八章 发展全过程人民民主","type":"single","typeText":"单选题","score":1.0,"question":"坚定中国特色社会主义( )，首先要坚定对中国特色社会主义政治制度的自信，增强走中国特色社会主义政治发展道路的信心与决心。","options":[{"key":"A","text":"文化自信"},{"key":"B","text":"制度自信"},{"key":"C","text":"理论自信"},{"key":"D","text":"道路自信"}],"answer":["B"],"explanation":"制度自信是坚定“四个自信”的重要内容，首先要坚定对中国特色社会主义政治制度的自信。"},{"id":814,"chapter":"第八章 发展全过程人民民主","type":"single","typeText":"单选题","score":1.0,"question":"( )是坚持党的领导、人民当家作主、依法治国有机统一的根本政治制度安排。","options":[{"key":"A","text":"中国共产党领导的多党合作和政治协商制度"},{"key":"B","text":"民族区域自治制度"},{"key":"C","text":"基层群众自治制度"},{"key":"D","text":"人民代表大会制度"}],"answer":["D"],"explanation":"人民代表大会制度是我国的根本政治制度，是实现“三者有机统一”的根本制度载体。"},{"id":815,"chapter":"第八章 发展全过程人民民主","type":"single","typeText":"单选题","score":1.0,"question":"全过程人民民主始终将( )作为民主政治建设的出发点和落脚点。","options":[{"key":"A","text":"坚持党的领导"},{"key":"B","text":"全面建设社会主义现代化国家"},{"key":"C","text":"实现最广大人民根本利益"},{"key":"D","text":"改革开放"}],"answer":["C"],"explanation":"全过程人民民主坚持以实现最广大人民根本利益为出发点和落脚点，确保人民真正当家作主。"},{"id":816,"chapter":"第八章 发展全过程人民民主","type":"single","typeText":"单选题","score":1.0,"question":"中华人民共和国的一切权力属于人民，国家权力是为人民服务的，人民行使国家权力的机关是( )和地方各级人民代表大会。","options":[{"key":"A","text":"全国人民代表大会"},{"key":"B","text":"人民政府"},{"key":"C","text":"基层党支部"},{"key":"D","text":"城乡社区"}],"answer":["A"],"explanation":"全国人民代表大会和地方各级人民代表大会是人民行使国家权力的机关，体现了一切权力属于人民的宪法原则。"},{"id":817,"chapter":"第八章 发展全过程人民民主","type":"single","typeText":"单选题","score":1.0,"question":"评判一种民主形式好不好，实践最有说服力，( )最有发言权。","options":[{"key":"A","text":"中国共产党"},{"key":"B","text":"人民政府"},{"key":"C","text":"新闻媒体"},{"key":"D","text":"人民"}],"answer":["D"],"explanation":"民主的本质是人民当家作主，因此民主形式的好坏应由人民来评判，实践是检验民主成效的根本标准。"},{"id":818,"chapter":"第八章 发展全过程人民民主","type":"single","typeText":"单选题","score":1.0,"question":"( )是中国社会主义民主政治中独特的、独有的、独到的民主形式。","options":[{"key":"A","text":"协商民主"},{"key":"B","text":"基层民主"},{"key":"C","text":"全过程人民民主"},{"key":"D","text":"民主选举"}],"answer":["A"],"explanation":"协商民主是中国社会主义民主政治中独特的民主形式，强调通过广泛协商达成共识。"},{"id":819,"chapter":"第八章 发展全过程人民民主","type":"single","typeText":"单选题","score":1.0,"question":"( )是凝聚人心、汇聚力量的强大法宝。","options":[{"key":"A","text":"独立自主"},{"key":"B","text":"统一战线"},{"key":"C","text":"党的领导"},{"key":"D","text":"改革开放"}],"answer":["B"],"explanation":"统一战线是凝聚人心、汇聚力量的强大法宝，对于实现国家统一和民族复兴具有重要意义。"},{"id":820,"chapter":"第八章 发展全过程人民民主","type":"single","typeText":"单选题","score":1.0,"question":"( )是统一战线最鲜明的特征。","options":[{"key":"A","text":"独立自主"},{"key":"B","text":"经济建设"},{"key":"C","text":"人民民主"},{"key":"D","text":"党的领导"}],"answer":["D"],"explanation":"党的领导是统一战线最鲜明的特征，是统一战线健康发展的根本保证。"},{"id":821,"chapter":"第八章 发展全过程人民民主","type":"single","typeText":"单选题","score":1.0,"question":"( )是中华民族精神的核心，维系着华夏大地上各个民族的团结统一，激励着一代又一代中华儿女为祖国发展繁荣而不懈奋斗。","options":[{"key":"A","text":"爱国主义"},{"key":"B","text":"斗争精神"},{"key":"C","text":"踔厉奋发"},{"key":"D","text":"勇毅前行"}],"answer":["A"],"explanation":"爱国主义是中华民族精神的核心，是凝聚民族力量、维护国家统一的重要精神纽带。"},{"id":822,"chapter":"第八章 发展全过程人民民主","type":"single","typeText":"单选题","score":1.0,"question":"( )是全人类共同价值，是人类政治文明发展的成果。","options":[{"key":"A","text":"科技"},{"key":"B","text":"民主"},{"key":"C","text":"法律"},{"key":"D","text":"道德"}],"answer":["B"],"explanation":"民主是全人类共同价值，各国应基于自身国情探索适合的民主发展道路。"},{"id":823,"chapter":"第八章 发展全过程人民民主","type":"single","typeText":"单选题","score":1.0,"question":"人民民主是( )的应有之义。","options":[{"key":"A","text":"全面建设社会主义现代化国家"},{"key":"B","text":"建设社会主义文化强国"},{"key":"C","text":"建设法治中国"},{"key":"D","text":"坚持党的全面领导"}],"answer":["A"],"explanation":"人民民主是全面建设社会主义现代化国家的应有之义，是中国特色社会主义政治发展的重要目标。"},{"id":824,"chapter":"第八章 发展全过程人民民主","type":"single","typeText":"单选题","score":1.0,"question":"以什么样的思路来谋划和推进中国社会主义民主( )，在国家政治生活中具有管根本、管全局、管长远的作用。","options":[{"key":"A","text":"经济建设"},{"key":"B","text":"生态文明建设"},{"key":"C","text":"社会建设"},{"key":"D","text":"政治建设"}],"answer":["D"],"explanation":"政治建设是国家建设的根本，民主政治建设是政治建设的核心内容，具有管根本、管全局、管长远的作用。"},{"id":825,"chapter":"第八章 发展全过程人民民主","type":"single","typeText":"单选题","score":1.0,"question":"( )是中国共产党团结带领人民追求民主、发展民主实现民主的伟大创造，是党不断推进中国民主理论创新、制度创新、实践创新的经验结晶。","options":[{"key":"A","text":"全面深化改革开放"},{"key":"B","text":"建设人才强国"},{"key":"C","text":"全过程人民民主"},{"key":"D","text":"建设教育强国"}],"answer":["C"],"explanation":"全过程人民民主是中国共产党领导人民在长期实践中形成的重大理论创新和实践成果。"},{"id":826,"chapter":"第八章 发展全过程人民民主","type":"single","typeText":"单选题","score":1.0,"question":"( )植根于我国社会主义民主的长期实践，是中国特色社会主义民主政治理论和实践的重大成果。","options":[{"key":"A","text":"全过程人民民主"},{"key":"B","text":"全面深化改革"},{"key":"C","text":"全面依法治国"},{"key":"D","text":"全面从严治党"}],"answer":["A"],"explanation":"全过程人民民主深深植根于中国土壤，是中国特色社会主义民主政治理论和实践的重大创新成果。"},{"id":827,"chapter":"第八章 发展全过程人民民主","type":"single","typeText":"单选题","score":1.0,"question":"( )是新时代我国民主政治领域具有重大创新意义的标志性成果。","options":[{"key":"A","text":"坚定“四个自信”"},{"key":"B","text":"全面深化改革"},{"key":"C","text":"全面依法治国"},{"key":"D","text":"全过程人民民主"}],"answer":["D"],"explanation":"全过程人民民主是新时代我国民主政治领域的标志性成果，展现了中国特色社会主义民主的独特优势。"},{"id":828,"chapter":"第八章 发展全过程人民民主","type":"single","typeText":"单选题","score":1.0,"question":"我国的各项国家制度都是围绕( )构建的，国家治理体系都是围绕人民当家作主运转的。","options":[{"key":"A","text":"经济建设"},{"key":"B","text":"人民当家作主"},{"key":"C","text":"坚持党的领导"},{"key":"D","text":"中国式现代化"}],"answer":["B"],"explanation":"人民当家作主是我国国家制度和国家治理体系的根本出发点和落脚点。"},{"id":829,"chapter":"第八章 发展全过程人民民主","type":"single","typeText":"单选题","score":1.0,"question":"全面发展( )，要不断完善协商民主体系，统筹推进政党协商、人大协商、政府协商、政协协商、人民团体协商、基层协商以及社会组织协商，健全各种制度化协商平台，推进协商民主广泛多层制度化发展。","options":[{"key":"A","text":"协商民主"},{"key":"B","text":"基层民主"},{"key":"C","text":"全过程人民民主"},{"key":"D","text":"民主选举"}],"answer":["A"],"explanation":"协商民主是我国社会主义民主政治的重要形式，需要不断完善制度体系，推进广泛多层制度化发展。"},{"id":830,"chapter":"第八章 发展全过程人民民主","type":"single","typeText":"单选题","score":1.0,"question":"( )是中国共产党夺取革命、建设、改革事业胜利的重要法宝，也是实现中华民族伟大复兴的重要法宝。","options":[{"key":"A","text":"统一战线"},{"key":"B","text":"武装斗争"},{"key":"C","text":"独立自主"},{"key":"D","text":"群众路线"}],"answer":["A"],"explanation":"统一战线是党在百年奋斗中积累的宝贵经验，是革命、建设、改革和实现民族复兴的重要法宝。"},{"id":831,"chapter":"第八章 发展全过程人民民主","type":"multiple","typeText":"多选题","score":3.0,"question":"全过程人民民主的提出、实践和发展，鲜明展示了我们党始终高举人民民主旗帜、实现人民当家作主的坚定立场，深刻彰显了我国人民民主的鲜明特色和显著优势，实现了( )相统一。","options":[{"key":"A","text":"过程民主和成果民主"},{"key":"B","text":"程序民主和实质民主"},{"key":"C","text":"直接民主和间接民主"},{"key":"D","text":"人民民主和国家意志"}],"answer":["A","B","C","D"],"explanation":"全过程人民民主实现了过程与成果、程序与实质、直接与间接、人民意愿与国家意志的有机统一。"},{"id":832,"chapter":"第八章 发展全过程人民民主","type":"multiple","typeText":"多选题","score":3.0,"question":"人民民主是社会主义的生命，没有民主( )。","options":[{"key":"A","text":"就没有社会主义"},{"key":"B","text":"就没有社会主义的现代化"},{"key":"C","text":"就没有中华民族伟大复兴"},{"key":"D","text":"以上都对"}],"answer":["A","B","C","D"],"explanation":"人民民主是社会主义的本质要求，关系到社会主义的存续、现代化建设和民族复兴大业。"},{"id":833,"chapter":"第八章 发展全过程人民民主","type":"multiple","typeText":"多选题","score":3.0,"question":"（ ）构成我国的基本政治制度。","options":[{"key":"A","text":"中国共产党领导的多党合作和政治协商制度"},{"key":"B","text":"民族区域自治制度"},{"key":"C","text":"基层群众自治制度"},{"key":"D","text":"人民代表大会制度"}],"answer":["A","B","C"],"explanation":"我国基本政治制度包括中国共产党领导的多党合作和政治协商制度、民族区域自治制度、基层群众自治制度。"},{"id":834,"chapter":"第八章 发展全过程人民民主","type":"multiple","typeText":"多选题","score":3.0,"question":"中国特色社会主义政治制度( )。","options":[{"key":"A","text":"既把握了长期形成的历史传承，又把握了走过的发展道路"},{"key":"B","text":"把握了现实要求、着眼解决现实问题"},{"key":"C","text":"注重历史和现实、理论和实践、形式和内容有机统一"},{"key":"D","text":"具有鲜明的中国特色、民族特色、时代特色"}],"answer":["A","B","C","D"],"explanation":"中国特色社会主义政治制度扎根中国土壤，贯通历史与现实，兼具理论创新与实践特色。"},{"id":835,"chapter":"第八章 发展全过程人民民主","type":"multiple","typeText":"多选题","score":3.0,"question":"中国特色社会主义政治制度的巨大优势体现在( )。","options":[{"key":"A","text":"能够有效保证人民享有更加广泛的权利和自由"},{"key":"B","text":"能够有效调节国家政治关系，形成安定团结的政治局面"},{"key":"C","text":"能够集中力量办大事，有效促进社会生产力解放和发展"},{"key":"D","text":"能够有效维护国家独立自主，有力维护国家主权、安全、发展利益"}],"answer":["A","B","C","D"],"explanation":"中国特色社会主义政治制度具有多方面的显著优势，是创造“中国奇迹”的重要制度保障。"},{"id":836,"chapter":"第八章 发展全过程人民民主","type":"multiple","typeText":"多选题","score":3.0,"question":"中华人民共和国的一切权力属于人民，人民行使国家权力的机关是( )。","options":[{"key":"A","text":"全国人民代表大会"},{"key":"B","text":"地方各级人民代表大会"},{"key":"C","text":"国务院"},{"key":"D","text":"人民代表"}],"answer":["A","B"],"explanation":"全国人民代表大会和地方各级人民代表大会是人民行使国家权力的机关。"},{"id":837,"chapter":"第八章 发展全过程人民民主","type":"multiple","typeText":"多选题","score":3.0,"question":"人民代表大会制度( )。","options":[{"key":"A","text":"坚持中国共产党领导，有效保证国家沿着社会主义道路前进"},{"key":"B","text":"最大限度保障人民当家作主"},{"key":"C","text":"有效保证国家治理跳出治乱兴衰的历史周期率"},{"key":"D","text":"正确处理事关国家前途命运的一系列重大政治关系，维护国家统一和民族团结"},{"key":"E","text":"有效保证国家政治生活既充满活力又安定有序"}],"answer":["A","B","C","D","E"],"explanation":"人民代表大会制度作为根本政治制度，具有多方面重要功能和显著优势。"},{"id":838,"chapter":"第八章 发展全过程人民民主","type":"multiple","typeText":"多选题","score":3.0,"question":"全过程人民民主是最真实的民主，具体体现在( )。","options":[{"key":"A","text":"把党的主张、国家意志、人民意愿紧密融合在一起，彰显了人民民主的真实性"},{"key":"B","text":"真实反映人民的期盼、希望和诉求"},{"key":"C","text":"人民的意愿和呼声，经过民主决策程序成为党和国家的方针政策"},{"key":"D","text":"真真切切落实到国家政治生活和社会生活各方面"}],"answer":["A","B","C","D"],"explanation":"全过程人民民主的真实性体现在意愿表达、政策形成、落实见效的全过程中。"},{"id":839,"chapter":"第八章 发展全过程人民民主","type":"multiple","typeText":"多选题","score":3.0,"question":"全过程人民民主是最广泛的民主，具体体现在( )。","options":[{"key":"A","text":"人民既充分享有民主选举权利，又充分享有民主协商、民主决策、民主管理、民主监督权利"},{"key":"B","text":"既参与国家事务管理，又参与经济和文化事业以及社会事务管理"},{"key":"C","text":"既参与国家发展顶层设计的意见建议征询，又参与地方公共事务治理"},{"key":"D","text":"不同地域、不同领域、不同层级、不同群体均实现全面覆盖"}],"answer":["A","B","C","D"],"explanation":"全过程人民民主的广泛性体现在参与主体、内容、领域、层次的全面覆盖上。"},{"id":840,"chapter":"第八章 发展全过程人民民主","type":"multiple","typeText":"多选题","score":3.0,"question":"全过程人民民主是最管用的民主，具体体现在( )。","options":[{"key":"A","text":"保证在党的领导下有效治理国家，切实防止出现一盘散沙的现象"},{"key":"B","text":"保证人民依法行使权利，切实防止出现选举时漫天许诺、选举后无人过问的现象"},{"key":"C","text":"加强社会各种力量的合作协调，切实防止出现党争纷沓、相互倾轧的现象"},{"key":"D","text":"巩固平等团结互助和谐的社会主义民族关系，切实防止出现民族隔阂、民族冲突的现象"},{"key":"E","text":"发展基层民主，切实防止出现人民形式上有权、实际上无权的现象"}],"answer":["A","B","C","D","E"],"explanation":"全过程人民民主的管用性体现在其能有效解决国家治理、权利保障、社会协调、民族团结、基层治理等实际问题。"},{"id":841,"chapter":"第八章 发展全过程人民民主","type":"multiple","typeText":"多选题","score":2.5,"question":"我国的协商民主体系包括( )。","options":[{"key":"A","text":"政党协商，人大协商"},{"key":"B","text":"政府协商"},{"key":"C","text":"人民团体协商"},{"key":"D","text":"政协协商"},{"key":"E","text":"基层协商以及社会组织协商"}],"answer":["A","B","C","D","E"],"explanation":"我国的协商民主是一个多层级、多领域的完整体系，涵盖国家治理和社会生活的各个方面。"},{"id":842,"chapter":"第八章 发展全过程人民民主","type":"multiple","typeText":"多选题","score":2.5,"question":"我国基层民主有多种多样的形式，如( )。","options":[{"key":"A","text":"以村民委员会为组织形态的农村村民自治"},{"key":"B","text":"以社区居民委员会为组织形态的城市居民自治"},{"key":"C","text":"以职工代表大会为组织依托的企事业单位职工自治"},{"key":"D","text":"以上都对"}],"answer":["A","B","C","D"],"explanation":"基层民主是我国社会主义民主的重要组成部分，主要通过村民自治、居民自治、企事业单位民主管理等形式实现。"},{"id":843,"chapter":"第八章 发展全过程人民民主","type":"multiple","typeText":"多选题","score":2.5,"question":"统一战线工作的本质要求是( )。","options":[{"key":"A","text":"大团结大联合"},{"key":"B","text":"解决的就是人心和力量问题"},{"key":"C","text":"推进国家统一"},{"key":"D","text":"实现中华民族伟大复兴"}],"answer":["A","B"],"explanation":"统一战线工作的本质要求是大团结大联合，核心是解决人心向背和力量对比的问题。"},{"id":844,"chapter":"第八章 发展全过程人民民主","type":"multiple","typeText":"多选题","score":2.5,"question":"铸牢中华民族共同体意识，就要( )。","options":[{"key":"A","text":"要引导各族人民牢固树立休戚与共、荣辱与共、命运与共的共同体理念"},{"key":"B","text":"要正确把握共同性和差异性的关系、中华民族共同体意识和各民族意识的关系、中华文化和各民族文化的关系"},{"key":"C","text":"建设各民族共有精神家园，促进各民族共同繁荣共同发展"},{"key":"D","text":"引导各族群众牢固树立正确的祖国观、民族观、文化观、历史观"}],"answer":["A","B","C","D"],"explanation":"铸牢中华民族共同体意识是一项系统工程，需要从理念、关系把握、文化建设和思想引导等多方面协同推进。"},{"id":845,"chapter":"第八章 发展全过程人民民主","type":"multiple","typeText":"多选题","score":2.5,"question":"统一战线工作范围包括( )。","options":[{"key":"A","text":"民主党派成员，无党派人士，党外知识分子"},{"key":"B","text":"少数民族人士，宗教界人士"},{"key":"C","text":"非公有制经济人士，新的社会阶层人士"},{"key":"D","text":"出国和归国留学人员"},{"key":"E","text":"香港同胞，澳门同胞，台湾同胞，华侨归侨及侨眷"}],"answer":["A","B","C","D","E"],"explanation":"统一战线工作范围广泛，涵盖各民主党派、无党派人士、各领域党外代表人士以及港澳台同胞和海外侨胞等。"},{"id":846,"chapter":"第八章 发展全过程人民民主","type":"multiple","typeText":"多选题","score":2.5,"question":"全过程人民民主是( )的民主，是最广泛、最真实、最管用的社会主义民主。","options":[{"key":"A","text":"全方面"},{"key":"B","text":"全链条"},{"key":"C","text":"全方位"},{"key":"D","text":"全覆盖"}],"answer":["B","C","D"],"explanation":"全过程人民民主是全链条、全方位、全覆盖的民主，体现了民主的完整性、全面性和有效性。"},{"id":847,"chapter":"第八章 发展全过程人民民主","type":"multiple","typeText":"多选题","score":2.5,"question":"全过程人民民主实现了( )。","options":[{"key":"A","text":"过程民主和成果民主相统一"},{"key":"B","text":"程序民主和实质民主相统一"},{"key":"C","text":"直接民主和间接民主相统一"},{"key":"D","text":"人民民主和国家意志相统一"}],"answer":["A","B","C","D"],"explanation":"全过程人民民主实现了民主过程与成果、程序与实质、直接参与与间接代表、人民意愿与国家意志的有机统一。"},{"id":848,"chapter":"第八章 发展全过程人民民主","type":"multiple","typeText":"多选题","score":2.5,"question":"在人民民主的共同旗帜下，中国共产党与各民主党派( )。","options":[{"key":"A","text":"长期共存"},{"key":"B","text":"互相监督"},{"key":"C","text":"肝胆相照"},{"key":"D","text":"荣辱与共"}],"answer":["A","B","C","D"],"explanation":"中国共产党与各民主党派遵循“长期共存、互相监督、肝胆相照、荣辱与共”的方针，共同致力于中国特色社会主义事业。"},{"id":849,"chapter":"第八章 发展全过程人民民主","type":"multiple","typeText":"多选题","score":2.5,"question":"巩固和发展爱国统一战线，应该着手做好以下工作( )。","options":[{"key":"A","text":"坚持长期共存、互相监督、肝胆相照、荣辱与共的中国共产党领导的政治协商制度"},{"key":"B","text":"深化民族团结进步教育"},{"key":"C","text":"全面贯彻党的宗教工作基本方针"},{"key":"D","text":"牢牢把握大团结大联合的主题，做好统战工作"}],"answer":["A","B","C","D"],"explanation":"巩固和发展爱国统一战线需要坚持和完善多党合作制度，加强民族团结和宗教工作，把握大团结大联合主题。"},{"id":850,"chapter":"第八章 发展全过程人民民主","type":"multiple","typeText":"多选题","score":2.5,"question":"走中国特色社会主义政治发展道路，必须坚持( )有机统一。","options":[{"key":"A","text":"推进国家治理体系和治理能力现代化"},{"key":"B","text":"巩固和发展最广泛的爱国统一战线"},{"key":"C","text":"党的领导"},{"key":"D","text":"人民当家作主，依法治国"}],"answer":["C","D"],"explanation":"党的领导、人民当家作主、依法治国三者有机统一，是中国特色社会主义政治发展道路的核心要义。"},{"id":851,"chapter":"第八章 发展全过程人民民主","type":"multiple","typeText":"多选题","score":2.5,"question":"全过程人民民主是社会主义民主政治的本质属性，是( )的民主。","options":[{"key":"A","text":"最广泛"},{"key":"B","text":"最真实"},{"key":"C","text":"最管用"},{"key":"D","text":"最典型"}],"answer":["A","B","C"],"explanation":"全过程人民民主是最广泛、最真实、最管用的社会主义民主，深刻体现了社会主义民主政治的本质属性。"},{"id":852,"chapter":"第八章 发展全过程人民民主","type":"multiple","typeText":"多选题","score":2.5,"question":"全过程人民民主是( )的民主。","options":[{"key":"A","text":"全链条"},{"key":"B","text":"全方位"},{"key":"C","text":"全覆盖"},{"key":"D","text":"全直接"}],"answer":["A","B","C"],"explanation":"全过程人民民主是全链条、全方位、全覆盖的民主，体现了民主参与和民主效能的完整性。"},{"id":853,"chapter":"第八章 发展全过程人民民主","type":"multiple","typeText":"多选题","score":2.5,"question":"全过程人民民主是( )的民主。","options":[{"key":"A","text":"最成熟"},{"key":"B","text":"最广泛"},{"key":"C","text":"最真实"},{"key":"D","text":"最管用"}],"answer":["B","C","D"],"explanation":"全过程人民民主以其广泛性、真实性和管用性，展现了社会主义民主的鲜明特色和显著优势。"},{"id":854,"chapter":"第八章 发展全过程人民民主","type":"multiple","typeText":"多选题","score":2.5,"question":"加强人民当家作主制度保障，要不断坚持和完善我国根本政治制度、基本政治制度、重要政治制度，构建多样、畅通、有序的民主渠道，有效保证( )相统一。","options":[{"key":"A","text":"多党派合作"},{"key":"B","text":"党的主张"},{"key":"C","text":"国家意志"},{"key":"D","text":"人民意愿"}],"answer":["B","C","D"],"explanation":"加强人民当家作主制度保障，关键在于通过制度建设，确保党的主张、国家意志、人民意愿三者高度统一。"},{"id":855,"chapter":"第八章 发展全过程人民民主","type":"multiple","typeText":"多选题","score":2.5,"question":"铸牢中华民族共同体意识，就是要引导各族人民牢固树立( )的共同体理念。","options":[{"key":"A","text":"休戚与共"},{"key":"B","text":"荣辱与共"},{"key":"C","text":"生死与共"},{"key":"D","text":"命运与共"}],"answer":["A","B","C","D"],"explanation":"铸牢中华民族共同体意识，就是要引导各族人民牢固树立休戚与共、荣辱与共、生死与共、命运与共的共同体理念。"},{"id":856,"chapter":"第八章 发展全过程人民民主","type":"multiple","typeText":"多选题","score":2.5,"question":"加强和促进海内外中华儿女大团结，要辩证把握好哪些方面的关系?( )。","options":[{"key":"A","text":"把握好固守圆心和扩大共识的关系"},{"key":"B","text":"把握好潜绩和显绩的关系"},{"key":"C","text":"把握好原则性和灵活性的关系"},{"key":"D","text":"把握好团结和斗争的关系"}],"answer":["A","B","C","D"],"explanation":"加强和促进海内外中华儿女大团结，需要辩证把握固守圆心与扩大共识、潜绩与显绩、原则性与灵活性、团结与斗争等多对重要关系。"},{"id":901,"chapter":"第九章 全面依法治国","type":"single","typeText":"单选题","score":2.0,"question":"( )是推进全面依法治国的总抓手。","options":[{"key":"A","text":"中国特色社会主义法治国家"},{"key":"B","text":"中国特色社会主义法治体系"},{"key":"C","text":"中国特色社会主义法治道路"},{"key":"D","text":"中国特色社会主义法治制度"}],"answer":["B"],"explanation":"建设中国特色社会主义法治体系是全面推进依法治国的总抓手，涉及法律规范、法治实施、法治监督、法治保障和党内法规等方面。"},{"id":902,"chapter":"第九章 全面依法治国","type":"single","typeText":"单选题","score":2.0,"question":"全面依法治国的唯一正确道路是( )。","options":[{"key":"A","text":"中国特色社会主义道路"},{"key":"B","text":"中国特色社会主义政治发展道路"},{"key":"C","text":"中国特色社会主义法治道路"},{"key":"D","text":"中国特色社会主义法制道路"}],"answer":["C"],"explanation":"中国特色社会主义法治道路是社会主义法治建设成就和经验的集中体现，是建设社会主义法治国家的唯一正确道路。"},{"id":903,"chapter":"第九章 全面依法治国","type":"single","typeText":"单选题","score":2.0,"question":"( )是国家的根本法，是治国安邦的总章程，是党和人民意志的集中体现，是国家各种制度和法律法规的总依据。","options":[{"key":"A","text":"法律总纲"},{"key":"B","text":"民法典"},{"key":"C","text":"宪法"},{"key":"D","text":"诉讼法"}],"answer":["C"],"explanation":"宪法是国家的根本大法，具有最高的法律地位、法律权威、法律效力，是全面依法治国的总依据。"},{"id":904,"chapter":"第九章 全面依法治国","type":"single","typeText":"单选题","score":2.0,"question":"我国人民法院对受理的民事案件、经济纠纷案件和轻微刑事案件进行的调解，是诉讼内调解。对于婚姻案件，诉讼内调解是必经的程序。至于其他民事案件是否进行调解，取决于当事人的自愿，调解不是必经程序。调解制度体现了下列哪方面中华优秀传统法律文化( )。","options":[{"key":"A","text":"出礼入刑、隆礼重法的治国策略"},{"key":"B","text":"德主刑辅、明德慎罚的慎刑思想"},{"key":"C","text":"天下无讼、以和为贵的价值追求"},{"key":"D","text":"民为邦本、本固邦宁的民本理念"}],"answer":["C"],"explanation":"调解制度体现了中华优秀传统法律文化中“天下无讼、以和为贵”的价值追求，注重通过协商化解矛盾，促进社会和谐。"},{"id":905,"chapter":"第九章 全面依法治国","type":"single","typeText":"单选题","score":2.0,"question":"法治体系是国家治理体系的骨干工程。更好推进中国特色社会主义法治体系建设，必须加快形成( ) ①完备的法律规范体系 ②高效的法治实施体系 ③严密的法治监督体系 ④有力的法治保障体系 ⑤完善的党内法规体系 ⑥普及的守法体系。","options":[{"key":"A","text":"①②③④⑤⑥"},{"key":"B","text":"①②③④⑤"},{"key":"C","text":"①②③④"},{"key":"D","text":"①②③④⑥"}],"answer":["B"],"explanation":"中国特色社会主义法治体系包括完备的法律规范体系、高效的法治实施体系、严密的法治监督体系、有力的法治保障体系和完善的党内法规体系五个部分。"},{"id":906,"chapter":"第九章 全面依法治国","type":"single","typeText":"单选题","score":2.0,"question":"“立善法于天下，则天下治；立善法于一国，则一国治”。表明更好推进中国特色社会主义法治体系建设，必须加快形成( )。","options":[{"key":"A","text":"完备的法律规范体系"},{"key":"B","text":"高效的法治实施体系"},{"key":"C","text":"严密的法治监督体系"},{"key":"D","text":"有力的法治保障体系"}],"answer":["A"],"explanation":"“立善法”强调立法的重要性，完备的法律规范体系是法治体系的基础，是实现良法善治的前提。"},{"id":907,"chapter":"第九章 全面依法治国","type":"single","typeText":"单选题","score":2.0,"question":"( )是党领导人民治理国家的基本方式。","options":[{"key":"A","text":"以人民为中心"},{"key":"B","text":"绿色发展"},{"key":"C","text":"依法治国"},{"key":"D","text":"人民当家作主"}],"answer":["C"],"explanation":"依法治国是党领导人民治理国家的基本方式，是实现国家治理体系和治理能力现代化的必然要求。"},{"id":908,"chapter":"第九章 全面依法治国","type":"single","typeText":"单选题","score":2.0,"question":"( )是社会主义法治最根本的保证。","options":[{"key":"A","text":"中国特色社会主义制度"},{"key":"B","text":"党的领导"},{"key":"C","text":"严密的法治监督体系"},{"key":"D","text":"全面深化改革"}],"answer":["B"],"explanation":"党的领导是中国特色社会主义最本质的特征，是社会主义法治最根本的保证，决定了法治建设的正确方向。"},{"id":909,"chapter":"第九章 全面依法治国","type":"single","typeText":"单选题","score":2.0,"question":"( )是中国特色社会主义法治体系的根本制度基础，是全面推进依法治国的根本制度保障。","options":[{"key":"A","text":"中国特色社会主义制度"},{"key":"B","text":"党的领导"},{"key":"C","text":"马克思主义指导"},{"key":"D","text":"以德治国"}],"answer":["A"],"explanation":"中国特色社会主义制度是中国特色社会主义法治体系的根本制度基础，为法治建设提供了根本的制度支撑和保障。"},{"id":910,"chapter":"第九章 全面依法治国","type":"single","typeText":"单选题","score":2.0,"question":"( )是中国特色社会主义的本质要求和重要保障。","options":[{"key":"A","text":"全面建设社会主义现代化国家"},{"key":"B","text":"全面依法治国"},{"key":"C","text":"全面深化改革"},{"key":"D","text":"全面从严治党"}],"answer":["B"],"explanation":"全面依法治国是中国特色社会主义的本质要求和重要保障，关系到党和国家长治久安。"},{"id":911,"chapter":"第九章 全面依法治国","type":"single","typeText":"单选题","score":2.0,"question":"法治监督体系以( )为重点。","options":[{"key":"A","text":"约束公权力运行"},{"key":"B","text":"思想教育"},{"key":"C","text":"制度建设"},{"key":"D","text":"少数领导干部"}],"answer":["A"],"explanation":"法治监督体系的核心是规范和约束公权力的运行，确保权力在法治轨道上正确行使，防止权力滥用。"},{"id":912,"chapter":"第九章 全面依法治国","type":"single","typeText":"单选题","score":2.0,"question":"全面依法治国最广泛、最深厚的基础是( )。","options":[{"key":"A","text":"党的领导"},{"key":"B","text":"社会稳定"},{"key":"C","text":"人民"},{"key":"D","text":"社会主义民主"}],"answer":["C"],"explanation":"人民是全面依法治国的主体和力量源泉，法治建设必须为了人民、依靠人民、造福人民、保护人民。"},{"id":913,"chapter":"第九章 全面依法治国","type":"single","typeText":"单选题","score":2.0,"question":"全面依法治国的总目标是( )。","options":[{"key":"A","text":"建设中国特色社会主义法治体系"},{"key":"B","text":"建设中国特色社会主义法治体系，建设社会主义法治国家"},{"key":"C","text":"建设社会主义法治国家"},{"key":"D","text":"有法可依、有法必依、违法必究、执法必严"}],"answer":["B"],"explanation":"全面依法治国的总目标是建设中国特色社会主义法治体系、建设社会主义法治国家，二者是统一的整体。"},{"id":914,"chapter":"第九章 全面依法治国","type":"single","typeText":"单选题","score":2.0,"question":"( )是国家治理体系和治理能力的重要依托。","options":[{"key":"A","text":"法治"},{"key":"B","text":"民主"},{"key":"C","text":"人民"},{"key":"D","text":"党的领导"}],"answer":["A"],"explanation":"法治是国家治理体系和治理能力现代化的重要标志和依托，为治理活动提供规则和程序保障。"},{"id":915,"chapter":"第九章 全面依法治国","type":"single","typeText":"单选题","score":2.0,"question":"( )是司法的灵魂和生命。","options":[{"key":"A","text":"公平正义"},{"key":"B","text":"民主法治"},{"key":"C","text":"诚信友善"},{"key":"D","text":"社会和谐"}],"answer":["A"],"explanation":"公平正义是法治的生命线，也是司法的灵魂和生命，必须努力让人民群众在每一个司法案件中感受到公平正义。"},{"id":916,"chapter":"第九章 全面依法治国","type":"single","typeText":"单选题","score":2.0,"question":"( )既是全面从严治党的重要依据，也是全面依法治国的有力保障。","options":[{"key":"A","text":"党内法规"},{"key":"B","text":"党的纪律条例"},{"key":"C","text":"党章"},{"key":"D","text":"党的监督机制"}],"answer":["A"],"explanation":"党内法规制度体系是管党治党的重要依据，与国家法律相辅相成，共同构成中国特色社会主义法治体系的重要组成部分。"},{"id":917,"chapter":"第九章 全面依法治国","type":"single","typeText":"单选题","score":2.0,"question":"我们讲坚持依宪治国、依宪执政，就包括坚持宪法确定的( )地位不动摇。","options":[{"key":"A","text":"人民当家作主"},{"key":"B","text":"中国共产党领导"},{"key":"C","text":"社会主义法治国家"},{"key":"D","text":"宪法权威"}],"answer":["B"],"explanation":"宪法确立了中国共产党在国家政治生活和社会生活中的领导地位，坚持依宪治国、依宪执政，首先必须坚持党的领导。"},{"id":918,"chapter":"第九章 全面依法治国","type":"single","typeText":"单选题","score":2.0,"question":"建设中国特色社会主义法治体系，必须坚持( )先行。","options":[{"key":"A","text":"守法"},{"key":"B","text":"司法"},{"key":"C","text":"执法"},{"key":"D","text":"立法"}],"answer":["D"],"explanation":"立法是法治的前提和基础，建设中国特色社会主义法治体系，必须坚持立法先行，发挥立法的引领和推动作用。"},{"id":919,"chapter":"第九章 全面依法治国","type":"multiple","typeText":"多选题","score":3.0,"question":"全面依法治国是( )。","options":[{"key":"A","text":"国家治理的一场深刻革命，关系党执政兴国，关系人民幸福安康"},{"key":"B","text":"完善和发展中国特色社会主义制度、推进国家治理体系和治理能力现代化的重要方面"},{"key":"C","text":"坚持和发展中国特色社会主义的本质要求和重要保障"},{"key":"D","text":"“四个全面”战略布局之一"}],"answer":["A","B","C","D"],"explanation":"全面依法治国是国家治理的深刻革命，是完善和发展中国特色社会主义制度的重要方面，是坚持和发展中国特色社会主义的本质要求和重要保障，也是“四个全面”战略布局的重要组成部分。"},{"id":920,"chapter":"第九章 全面依法治国","type":"multiple","typeText":"多选题","score":3.0,"question":"中国特色社会主义法治道路的核心要义是( )。","options":[{"key":"A","text":"坚持党的领导"},{"key":"B","text":"坚持中国特色社会主义制度"},{"key":"C","text":"贯彻中国特色社会主义法治理论"},{"key":"D","text":"坚持社会主义根本制度"}],"answer":["A","B","C"],"explanation":"中国特色社会主义法治道路的核心要义是坚持党的领导、坚持中国特色社会主义制度、贯彻中国特色社会主义法治理论。"},{"id":921,"chapter":"第九章 全面依法治国","type":"multiple","typeText":"多选题","score":3.0,"question":"要坚持( )相结合，实现法治和德治相辅相成、相得益彰。","options":[{"key":"A","text":"依法治国"},{"key":"B","text":"协同发展"},{"key":"C","text":"全面发展"},{"key":"D","text":"以德治国"}],"answer":["A","D"],"explanation":"必须坚持依法治国和以德治国相结合，发挥法律和道德的互补作用，共同规范社会行为、维护社会秩序。"},{"id":922,"chapter":"第九章 全面依法治国","type":"multiple","typeText":"多选题","score":3.0,"question":"健全公安机关、检察机关、审判机关、司法行政机关各司其职，( )相互配合、相互制约的体制机制。","options":[{"key":"A","text":"侦查权"},{"key":"B","text":"检察权"},{"key":"C","text":"审判权"},{"key":"D","text":"执行权"}],"answer":["A","B","C","D"],"explanation":"健全侦查权、检察权、审判权、执行权相互配合、相互制约的体制机制，是优化司法职权配置、维护司法公正的关键。"},{"id":923,"chapter":"第九章 全面依法治国","type":"multiple","typeText":"多选题","score":4.0,"question":"关于政治和法治的关系，下列说法正确的是( )。","options":[{"key":"A","text":"法治要脱离政治的影响，才能确保公平正义"},{"key":"B","text":"法治当中有政治，没有脱离政治的法治"},{"key":"C","text":"政治和法治相互依存，相互作用，密不可分"},{"key":"D","text":"党和法的关系是政治和法治关系的集中反映"}],"answer":["B","C","D"],"explanation":"政治和法治密不可分，法治是政治的一种实现形式；党和法的关系是政治和法治关系的集中体现，不存在脱离政治的纯粹法治。"},{"id":924,"chapter":"第九章 全面依法治国","type":"multiple","typeText":"多选题","score":4.0,"question":"走中国特色社会主义法治道路，必须长期坚持以下哪些基本原则。( )","options":[{"key":"A","text":"坚持中国共产党的领导"},{"key":"B","text":"坚持人民主体地位"},{"key":"C","text":"坚持法律面前人人平等"},{"key":"D","text":"坚持依法治国与以德治国相结合"},{"key":"E","text":"坚持从中国实际出发"}],"answer":["A","B","C","D","E"],"explanation":"走中国特色社会主义法治道路，必须坚持党的领导、人民主体地位、法律面前人人平等、依法治国和以德治国相结合、从中国实际出发等基本原则。"},{"id":925,"chapter":"第九章 全面依法治国","type":"multiple","typeText":"多选题","score":4.0,"question":"全面依法治国必须正确处理( )的关系。","options":[{"key":"A","text":"政治和法治"},{"key":"B","text":"改革和法治"},{"key":"C","text":"依法治国和以德治国"},{"key":"D","text":"依法治国和依规治党"}],"answer":["A","B","C","D"],"explanation":"全面依法治国是一项系统工程，必须正确处理政治与法治、改革与法治、依法治国与以德治国、依法治国与依规治党等重要关系。"},{"id":926,"chapter":"第九章 全面依法治国","type":"multiple","typeText":"多选题","score":4.0,"question":"正确处理改革和法治的关系，要做到( )。","options":[{"key":"A","text":"要坚持改革决策和立法决策相统一"},{"key":"B","text":"立法主动适应改革需要，重大改革于法有据"},{"key":"C","text":"对实践条件还不成熟、需要先行先试的，要按照法定程序作出授权"},{"key":"D","text":"对不适应改革要求的现行法律法规，要及时修改或废止"}],"answer":["A","B","C","D"],"explanation":"正确处理改革和法治关系，要做到改革决策与立法决策相衔接，立法引领和保障改革，确保改革在法治轨道上推进。"},{"id":927,"chapter":"第九章 全面依法治国","type":"multiple","typeText":"多选题","score":4.0,"question":"正确处理依法治国和依规治党的关系，要做到( )。","options":[{"key":"A","text":"要发挥依法治国和依规治党的互补性作用，确保党既依据宪法法律治国理政，又依据党内法规管党治党、从严治党"},{"key":"B","text":"要正确处理党的政策和国家法律的关系，两者都是人民根本意志的反映"},{"key":"C","text":"党的政策是国家法律的先导和指引"},{"key":"D","text":"要通过法律保障党的政策有效实施"}],"answer":["A","B","C","D"],"explanation":"依法治国和依规治党相互促进、相辅相成，要注重党内法规同国家法律的衔接和协调，确保党的领导和社会主义法治的统一。"},{"id":928,"chapter":"第九章 全面依法治国","type":"multiple","typeText":"多选题","score":4.0,"question":"坚持依宪治国、依宪执政，就必须( )。","options":[{"key":"A","text":"坚持宪法确定的中国共产党领导地位不动摇"},{"key":"B","text":"坚持宪法确定的人民民主专政的国体和人民代表大会的政体不动摇"},{"key":"C","text":"坚持走“宪政”道路不动摇"},{"key":"D","text":"学习西方“三权鼎立”制度"}],"answer":["A","B"],"explanation":"坚持依宪治国、依宪执政，必须坚持宪法确立的党的领导地位、人民民主专政的国体、人民代表大会制度的政体等根本制度不动摇，不能照搬西方政治模式。"},{"id":929,"chapter":"第九章 全面依法治国","type":"multiple","typeText":"多选题","score":4.0,"question":"更好推进中国特色社会主义法治体系建设，必须加快形成( )。","options":[{"key":"A","text":"完备的法律规范体系"},{"key":"B","text":"高效的法治实施体系"},{"key":"C","text":"严密的法治监督体系"},{"key":"D","text":"有力的法治保障体系"}],"answer":["A","B","C","D"],"explanation":"中国特色社会主义法治体系是一个系统，包括法律规范体系、法治实施体系、法治监督体系、法治保障体系，以及党内法规体系。"},{"id":930,"chapter":"第九章 全面依法治国","type":"multiple","typeText":"多选题","score":4.0,"question":"加快形成完备的法律规范体系，必须( )。","options":[{"key":"A","text":"深入推进科学立法、民主立法、依法立法，统筹立改废释纂"},{"key":"B","text":"提高立法效率，增强立法系统性、整体性、协同性和时效性"},{"key":"C","text":"研究丰富立法形式，增强立法的针对性、适用性、可操作性"},{"key":"D","text":"推进合宪性审查工作"}],"answer":["A","B","C","D"],"explanation":"建设完备的法律规范体系，需要提高立法质量，完善立法体制机制，加强重点领域、新兴领域、涉外领域立法，并做好合宪性审查工作。"},{"id":931,"chapter":"第九章 全面依法治国","type":"multiple","typeText":"多选题","score":4.0,"question":"加快建设法治中国，必须坚持系统观念，全面推进( )。","options":[{"key":"A","text":"科学立法"},{"key":"B","text":"严格执法"},{"key":"C","text":"公正司法"},{"key":"D","text":"全民守法"}],"answer":["A","B","C","D"],"explanation":"建设法治中国是一个系统工程，需要全面推进科学立法、严格执法、公正司法、全民守法，共同构筑法治运行的良好生态。"},{"id":932,"chapter":"第九章 全面依法治国","type":"multiple","typeText":"多选题","score":4.0,"question":"坚持以宪法为最高法律规范，完善以宪法为核心的中国特色社会主义法律体系，加强( )立法，把国家各项事业和各项工作纳入法制轨道。","options":[{"key":"A","text":"重点领域"},{"key":"B","text":"突出领域"},{"key":"C","text":"新兴领域"},{"key":"D","text":"涉外领域"}],"answer":["A","C","D"],"explanation":"完善中国特色社会主义法律体系，需要加强重点领域、新兴领域、涉外领域的立法，填补法律空白，适应国家发展需要。"},{"id":933,"chapter":"第九章 全面依法治国","type":"multiple","typeText":"多选题","score":4.0,"question":"法治中国建设的总体目标是( )。","options":[{"key":"A","text":"到2025年，党领导全面依法治国体制机制更加健全，以宪法为核心的中国特色社会主义法律体系更加完备"},{"key":"B","text":"到2025年，法治社会建设取得重大进展，党内法规体系更加完善"},{"key":"C","text":"到2025年，中国特色社会主义法治体系初步形成"},{"key":"D","text":"到2035年，法治国家、法治政府、法治社会基本建成"}],"answer":["A","B","C","D"],"explanation":"《法治中国建设规划（2020－2025年）》明确了到2025年和2035年的阶段性目标，描绘了法治中国建设的蓝图。"},{"id":934,"chapter":"第九章 全面依法治国","type":"multiple","typeText":"多选题","score":4.0,"question":"法治中国建设的工作布局是( )。","options":[{"key":"A","text":"坚持依法治国、依法执政、依法行政共同推进"},{"key":"B","text":"坚持法治国家、法治政府、法治社会一体建设"},{"key":"C","text":"坚持统筹推进国内法治和涉外法治"},{"key":"D","text":"协商民主和法制宣传一体推进"}],"answer":["A","B","C"],"explanation":"法治中国建设坚持“共同推进、一体建设”的工作布局，并注重统筹国内法治和涉外法治，为改革发展稳定提供法治保障。"},{"id":935,"chapter":"第九章 全面依法治国","type":"multiple","typeText":"多选题","score":4.0,"question":"建设更高水平的法治中国，必须( )。","options":[{"key":"A","text":"完善以宪法为核心的中国特色社会主义法律体系"},{"key":"B","text":"扎实推进依法行政"},{"key":"C","text":"严格公正司法"},{"key":"D","text":"加快建设法治社会"}],"answer":["A","B","C","D"],"explanation":"建设更高水平的法治中国是一项系统工程，需要在立法、执法、司法、守法等各个环节持续发力，全面提升法治建设水平。"},{"id":1001,"chapter":"第十章 建设社会主义文化强国","type":"single","typeText":"单选题","score":3.0,"question":"下列观点和认识中，错误的是 ( )。","options":[{"key":"A","text":"当今时代，文化在综合国力竞争中的地位日益重要，谁占据了文化发展的制高点，谁就能够更好地在激烈的国际竞争中掌握主动权"},{"key":"B","text":"文化强国既表现为具有高度文化素养的国民，也表现为发达的文化产业，还表现为强大的文化软实力"},{"key":"C","text":"国家强大、民族兴盛、社会发展，不仅需要高度发达的物质文明，也需要高度繁荣的精神文明"},{"key":"D","text":"文化是一种跨越国界、跨越民族、跨越时空的普适性精神力量，因此，要积极融入世界文化，完全没有必要坚守中华文化立场、走中国特色社会主义文化发展道路"}],"answer":["D"],"explanation":"文化具有民族性，必须坚守中华文化立场，走中国特色社会主义文化发展道路。盲目融入世界文化而放弃自身立场是错误的。"},{"id":1002,"chapter":"第十章 建设社会主义文化强国","type":"single","typeText":"单选题","score":3.0,"question":"文化兴则国运兴，文化强则民族强。实现中华民族伟大复兴，必然要求推动( )繁荣兴盛，建设社会主义文化强国。","options":[{"key":"A","text":"社会主义经济"},{"key":"B","text":"社会主义制度"},{"key":"C","text":"中华文化"},{"key":"D","text":"社会主义文化"}],"answer":["C"],"explanation":"中华文化的繁荣兴盛是实现中华民族伟大复兴的精神支撑和内在要求，文化强国建设是民族复兴的应有之义。"},{"id":1003,"chapter":"第十章 建设社会主义文化强国","type":"single","typeText":"单选题","score":2.0,"question":"建设中国特色社会主义文化，必须牢牢掌握( )。","options":[{"key":"A","text":"马克思主义的科学理论"},{"key":"B","text":"网络空间的治理和引导"},{"key":"C","text":"意识形态工作领导权"},{"key":"D","text":"中国特色社会主义科学体系的构建"}],"answer":["C"],"explanation":"意识形态工作事关文化前进方向和发展道路，必须牢牢掌握党对意识形态工作的领导权，这是建设中国特色社会主义文化的根本保证。"},{"id":1004,"chapter":"第十章 建设社会主义文化强国","type":"single","typeText":"单选题","score":2.0,"question":"( )是一个民族赖以维系的精神纽带，是一个国家共同的思想道德基础。","options":[{"key":"A","text":"社会主义核心价值观"},{"key":"B","text":"核心价值观"},{"key":"C","text":"理想信念"},{"key":"D","text":"社会主义核心价值体系"}],"answer":["B"],"explanation":"核心价值观是一个民族、一个国家最持久、最深层的精神力量，是全体人民共同认同的价值观“最大公约数”。"},{"id":1005,"chapter":"第十章 建设社会主义文化强国","type":"single","typeText":"单选题","score":2.0,"question":"( )是更基础、更广泛、更深厚的自信，是一个国家、一个民族发展中最基本、最深沉、最持久的力量。","options":[{"key":"A","text":"文化自信"},{"key":"B","text":"理论自信"},{"key":"C","text":"制度自信"},{"key":"D","text":"道路自信"}],"answer":["A"],"explanation":"文化自信是更基础、更广泛、更深厚的自信，是民族发展中更基本、更深沉、更持久的力量，关系到国运兴衰、文化安全、民族精神独立性。"},{"id":1006,"chapter":"第十章 建设社会主义文化强国","type":"single","typeText":"单选题","score":2.0,"question":"建设社会主义文化强国、推动社会主义文化繁荣兴盛，关键在于( )。","options":[{"key":"A","text":"坚定中国特色社会主义文化自信"},{"key":"B","text":"坚持马克思主义在意识形态领域的指导"},{"key":"C","text":"以社会主义核心价值观引领文化建设"},{"key":"D","text":"缩小城乡公共文化服务差距"}],"answer":["A"],"explanation":"文化自信是建设社会主义文化强国的精神支柱和内在动力，坚定文化自信是关键所在。"},{"id":1007,"chapter":"第十章 建设社会主义文化强国","type":"single","typeText":"单选题","score":2.0,"question":"( )是中华民族精神的核心，维系着华夏大地上各个民族的团结统一，激励着一代代中华儿女为祖国发展繁荣不懈奋斗。","options":[{"key":"A","text":"伟大精神"},{"key":"B","text":"爱国主义"},{"key":"C","text":"民族团结"},{"key":"D","text":"改革创新"}],"answer":["B"],"explanation":"爱国主义是中华民族精神的核心，深深植根于中华民族心中，是维护民族独立和尊严的强大精神动力。"},{"id":1008,"chapter":"第十章 建设社会主义文化强国","type":"single","typeText":"单选题","score":2.0,"question":"( )是我们坚定文化自信的深厚基础，是我们区别于其他国家和民族的根本特征。","options":[{"key":"A","text":"社会主义先进文化"},{"key":"B","text":"社会主义核心价值观"},{"key":"C","text":"革命文化"},{"key":"D","text":"中华优秀传统文化"}],"answer":["D"],"explanation":"中华优秀传统文化是中华民族的“根”和“魂”，是我们在世界文化激荡中站稳脚跟的根基，是文化自信的重要来源。"},{"id":1009,"chapter":"第十章 建设社会主义文化强国","type":"single","typeText":"单选题","score":2.0,"question":"坚持马克思主义在意识形态领域指导地位的制度是中国特色社会主义制度体系的一项( )。","options":[{"key":"A","text":"基本制度"},{"key":"B","text":"重要制度"},{"key":"C","text":"基本政策"},{"key":"D","text":"根本制度"}],"answer":["D"],"explanation":"坚持马克思主义在意识形态领域指导地位的根本制度，是关系党和国家事业长远发展、关系我国文化前进方向和发展道路的重大制度创新。"},{"id":1010,"chapter":"第十章 建设社会主义文化强国","type":"single","typeText":"单选题","score":2.0,"question":"( )是中华文明的智慧结晶和精华所在，是中华民族的根和魂。","options":[{"key":"A","text":"社会主义先进文化"},{"key":"B","text":"革命文化"},{"key":"C","text":"中华优秀传统文化"},{"key":"D","text":"中国特色社会主义文化"}],"answer":["C"],"explanation":"中华优秀传统文化积淀着中华民族最深层的精神追求，代表着中华民族独特的精神标识，是中华民族生生不息、发展壮大的丰厚滋养。"},{"id":1011,"chapter":"第十章 建设社会主义文化强国","type":"single","typeText":"单选题","score":2.0,"question":"( )是意识形态工作的主阵地、主战场、最前沿。","options":[{"key":"A","text":"传统媒体"},{"key":"B","text":"互联网"},{"key":"C","text":"政府机关"},{"key":"D","text":"学校"}],"answer":["B"],"explanation":"互联网已经成为意识形态斗争的主阵地、主战场、最前沿，管好用好互联网，是维护意识形态安全的关键。"},{"id":1012,"chapter":"第十章 建设社会主义文化强国","type":"single","typeText":"单选题","score":2.0,"question":"以( )为源头的中国共产党人精神谱系，是党带领人民战胜艰难险阻、取得一个又一个伟大胜利的精神丰碑，是中华民族的宝贵精神财富。","options":[{"key":"A","text":"伟大建党精神"},{"key":"B","text":"伟大斗争精神"},{"key":"C","text":"伟大红船精神"},{"key":"D","text":"伟大长征精神"}],"answer":["A"],"explanation":"伟大建党精神是中国共产党的精神之源，在此精神滋养下形成了一系列伟大精神，构筑起中国共产党人的精神谱系。"},{"id":1013,"chapter":"第十章 建设社会主义文化强国","type":"single","typeText":"单选题","score":2.0,"question":"( )是我们立党立国、兴党兴国的根本指导思想。","options":[{"key":"A","text":"中国特色社会主义理论"},{"key":"B","text":"马克思主义"},{"key":"C","text":"习近平新时代中国特色社会主义思想"},{"key":"D","text":"毛泽东思想"}],"answer":["B"],"explanation":"马克思主义是我们立党立国、兴党兴国的根本指导思想，是我们认识世界、把握规律、追求真理、改造世界的强大思想武器。"},{"id":1014,"chapter":"第十章 建设社会主义文化强国","type":"single","typeText":"单选题","score":2.0,"question":"( )集中体现了一个国家基于文化而具有的凝聚力和生命力，以及由此产生的吸引力和影响力。","options":[{"key":"A","text":"文化软实力"},{"key":"B","text":"意识形态"},{"key":"C","text":"核心价值观"},{"key":"D","text":"正面宣传"}],"answer":["A"],"explanation":"文化软实力集中体现了一个国家基于文化而具有的凝聚力、生命力和影响力，是国家综合国力的重要组成部分。"},{"id":1015,"chapter":"第十章 建设社会主义文化强国","type":"single","typeText":"单选题","score":2.0,"question":"( )工作是为国家立心、为民族立魂的工作。","options":[{"key":"A","text":"思想政治"},{"key":"B","text":"核心价值观培育"},{"key":"C","text":"传统文化教育"},{"key":"D","text":"意识形态"}],"answer":["D"],"explanation":"意识形态工作是为国家立心、为民族立魂的工作，决定着文化的前进方向和发展道路，事关党的前途命运、国家长治久安、民族凝聚力和向心力。"},{"id":1016,"chapter":"第十章 建设社会主义文化强国","type":"single","typeText":"单选题","score":2.0,"question":"( )关乎旗帜、关乎道路、关乎国家政治安全，决定文化前进方向和发展道路。","options":[{"key":"A","text":"核心价值观"},{"key":"B","text":"核心价值体系"},{"key":"C","text":"意识形态"},{"key":"D","text":"党的建设"}],"answer":["C"],"explanation":"意识形态工作极端重要，它关乎旗帜、关乎道路、关乎国家政治安全，在党和国家事业发展中具有根本性、战略性、全局性地位。"},{"id":1017,"chapter":"第十章 建设社会主义文化强国","type":"single","typeText":"单选题","score":2.0,"question":"新闻舆论工作有鲜明的( )属性，坚持正确的政治方向是做好新闻舆论工作的第一位要求。","options":[{"key":"A","text":"主流价值"},{"key":"B","text":"意识形态"},{"key":"C","text":"道德引领"},{"key":"D","text":"社会价值"}],"answer":["B"],"explanation":"新闻舆论工作处在意识形态斗争最前沿，具有鲜明的意识形态属性。必须把政治方向摆在第一位，坚持党性原则，坚持正确舆论导向。"},{"id":1018,"chapter":"第十章 建设社会主义文化强国","type":"single","typeText":"单选题","score":2.0,"question":"( )是新闻舆论工作的根本原则。","options":[{"key":"A","text":"人民性"},{"key":"B","text":"党性"},{"key":"C","text":"真实性"},{"key":"D","text":"客观性"}],"answer":["B"],"explanation":"党性原则是新闻舆论工作的根本原则，是坚持正确政治方向、舆论导向、价值取向的根本保证。"},{"id":1019,"chapter":"第十章 建设社会主义文化强国","type":"single","typeText":"单选题","score":2.0,"question":"铸就社会主义文化新辉煌，必须推动( )创造性转化、创新性发展。","options":[{"key":"A","text":"社会主义先进文化"},{"key":"B","text":"革命文化"},{"key":"C","text":"红色文化"},{"key":"D","text":"中华优秀传统文化"}],"answer":["D"],"explanation":"中华优秀传统文化是中华民族的突出优势，必须坚持古为今用、推陈出新，推动其创造性转化、创新性发展，使之与现代社会相协调、与当代文化相适应。"},{"id":1020,"chapter":"第十章 建设社会主义文化强国","type":"multiple","typeText":"多选题","score":4.0,"question":"文化软实力集中体现了一个国家基于文化而具有的凝聚力和生命力，以及由此产生的吸引力和影响力。提高国家文化软实力，( )。","options":[{"key":"A","text":"要努力弘扬中华文化，推进中华文化创新发展，展示中华文化魅力，夯实国家文化软实力的根基"},{"key":"B","text":"要讲好中国故事，传播好中国声音，阐释好中国特色，注重国家形象塑造，增强对外话语的创造力、感召力和公信力，提高国际话语权"},{"key":"C","text":"要加强当代中国价值观念的提炼与阐释"},{"key":"D","text":"要拓展对外传播平台和载体，创新对外话语表达方式和传播渠道，使当代中国价值观念走向世界，提高当代中国价值观念的国际知晓率和认同度"}],"answer":["A","B","C","D"],"explanation":"提高国家文化软实力是一项系统工程，需要从内夯实文化根基、提炼核心价值，对外讲好中国故事、创新传播方式，全面提升中华文化影响力。"},{"id":1021,"chapter":"第十章 建设社会主义文化强国","type":"multiple","typeText":"多选题","score":4.0,"question":"文化繁荣兴盛是实现中华民族伟大复兴的必然要求体现在( )。","options":[{"key":"A","text":"文化繁荣兴盛是实现中华民族伟大复兴的精神支撑"},{"key":"B","text":"文化繁荣兴盛是建设社会主义现代化强国的应有之义"},{"key":"C","text":"文化繁荣兴盛是满足人民日益增长的美好生活需要的内在要求"},{"key":"D","text":"文化繁荣兴盛是在世界文化激荡中站稳脚跟的前提基础"}],"answer":["A","B","C","D"],"explanation":"文化繁荣兴盛为民族复兴提供精神支撑，是现代化强国建设的重要内容，是满足人民精神需求的必然要求，也是应对外部文化冲击、坚定文化自信的根基。"},{"id":1022,"chapter":"第十章 建设社会主义文化强国","type":"multiple","typeText":"多选题","score":4.0,"question":"坚持举旗帜、聚民心、育新人、兴文化、展形象。举旗帜，就是要( )。","options":[{"key":"A","text":"高举马克思主义的旗帜"},{"key":"B","text":"高举中国特色社会主义的旗帜"},{"key":"C","text":"坚持不懈用习近平新时代中国特色社会主义思想武装全党、教育人民"},{"key":"D","text":"高举无产阶级专政的旗帜"}],"answer":["A","B","C"],"explanation":"举旗帜，就是要高举马克思主义、中国特色社会主义伟大旗帜，坚持不懈用习近平新时代中国特色社会主义思想这一当代中国马克思主义、二十一世纪马克思主义武装全党、教育人民、指导实践。"},{"id":1023,"chapter":"第十章 建设社会主义文化强国","type":"multiple","typeText":"多选题","score":4.0,"question":"坚持中国特色社会主义文化建设的“二为”方向，“二为”是( )。","options":[{"key":"A","text":"为中国共产党治国理政服务"},{"key":"B","text":"为建设社会主义现代化国家"},{"key":"C","text":"为人民服务"},{"key":"D","text":"为社会主义服务"}],"answer":["C","D"],"explanation":"中国特色社会主义文化建设必须坚持为人民服务、为社会主义服务的方向，这是社会主义文化发展的根本方向和基本遵循。"},{"id":1024,"chapter":"第十章 建设社会主义文化强国","type":"multiple","typeText":"多选题","score":4.0,"question":"坚持马克思主义在意识形态领域指导地位的根本制度，必须( )。","options":[{"key":"A","text":"牢牢掌握党对意识形态工作领导权"},{"key":"B","text":"坚持以立为本、立破并举，提高政治自觉，把意识形态阵地建设和管理工作摆在重要位置"},{"key":"C","text":"全面落实意识形态工作责任制，压紧压实做好意识形态工作的政治责任"},{"key":"D","text":"要切实把坚持以马克思主义为指导体现到理论武装、舆论引导、思想道德建设、文化文艺等各方面"}],"answer":["A","B","C","D"],"explanation":"落实这一根本制度，需要从领导权、阵地建设、责任落实、全面贯彻等多个方面协同发力，确保马克思主义在意识形态领域的指导地位落到实处。"},{"id":1025,"chapter":"第十章 建设社会主义文化强国","type":"multiple","typeText":"多选题","score":4.0,"question":"100多年前，中国共产党的先驱们创建了中国共产党，形成了( )的伟大建党精神。","options":[{"key":"A","text":"坚持真理、坚守理想"},{"key":"B","text":"践行初心、担当使命"},{"key":"C","text":"不怕牺牲、英勇斗争"},{"key":"D","text":"对党忠诚、不负人民"}],"answer":["A","B","C","D"],"explanation":"伟大建党精神内涵为：坚持真理、坚守理想，践行初心、担当使命，不怕牺牲、英勇斗争，对党忠诚、不负人民。这是中国共产党的精神之源。"},{"id":1026,"chapter":"第十章 建设社会主义文化强国","type":"multiple","typeText":"多选题","score":4.0,"question":"中国共产党人精神谱系( )。","options":[{"key":"A","text":"集中体现了党的坚定信念、根本宗旨、优良作风"},{"key":"B","text":"凝聚着中国共产党人艰苦奋斗、牺牲奉献、开拓进取的伟大品格"},{"key":"C","text":"已经深深融入党、国家、民族、人民的血脉和灵魂"},{"key":"D","text":"成为民族精神和时代精神的重要组成部分，成为社会主义核心价值观的丰富滋养"}],"answer":["A","B","C","D"],"explanation":"中国共产党人精神谱系是党百年奋斗形成的宝贵精神财富，它体现了党的性质宗旨，融入了民族血脉，丰富了时代精神和社会主义核心价值观。"},{"id":1027,"chapter":"第十章 建设社会主义文化强国","type":"multiple","typeText":"多选题","score":4.0,"question":"社会主义核心价值观涉及国家、社会、公民三个层面的价值要求，具体表达为( )。","options":[{"key":"A","text":"富强、民主、文明、和谐"},{"key":"B","text":"自由、民族、公正、法治"},{"key":"C","text":"爱国、敬业、诚信、友善"},{"key":"D","text":"自由、平等、公正、法治"}],"answer":["A","C","D"],"explanation":"社会主义核心价值观国家层面的价值目标是富强、民主、文明、和谐；社会层面的价值取向是自由、平等、公正、法治；公民个人层面的价值准则是爱国、敬业、诚信、友善。"},{"id":1028,"chapter":"第十章 建设社会主义文化强国","type":"multiple","typeText":"多选题","score":4.0,"question":"一个国家的文化软实力，从根本上说，取决于其核心价值观的( )。","options":[{"key":"A","text":"生命力"},{"key":"B","text":"凝聚力"},{"key":"C","text":"感召力"},{"key":"D","text":"影响力"}],"answer":["A","B","C"],"explanation":"核心价值观是文化软实力的灵魂，其生命力、凝聚力、感召力决定了文化软实力的强弱。影响力是文化软实力作用的结果表现。"},{"id":1029,"chapter":"第十章 建设社会主义文化强国","type":"multiple","typeText":"多选题","score":4.0,"question":"坚持( )是繁荣发展社会主义文化的重要方针。","options":[{"key":"A","text":"古为今用"},{"key":"B","text":"洋为中用"},{"key":"C","text":"百花齐放"},{"key":"D","text":"百家争鸣"}],"answer":["C","D"],"explanation":"“百花齐放、百家争鸣”是繁荣发展社会主义文化的重要方针，旨在促进艺术发展和科学进步，促进社会主义文化的繁荣。"},{"id":1030,"chapter":"第十章 建设社会主义文化强国","type":"multiple","typeText":"多选题","score":4.0,"question":"中华文明的突出特性包括( )。","options":[{"key":"A","text":"连续性"},{"key":"B","text":"创新性"},{"key":"C","text":"统一性"},{"key":"D","text":"包容性"},{"key":"E","text":"和平性"}],"answer":["A","B","C","D","E"],"explanation":"中华文明具有突出的连续性、创新性、统一性、包容性、和平性。这些特性从根本上决定了中华民族必然走自己的路，是建设中华民族现代文明的重要基础。"},{"id":1031,"chapter":"第十章 建设社会主义文化强国","type":"multiple","typeText":"多选题","score":4.0,"question":"我们党领导各族人民在进行革命、建设和改革的历史实践中，创造了鲜明独特、奋发向上的( )，是激励人民投身革命和社会主义建设的强大精神力量，是我们文化发展的基础和优势。","options":[{"key":"A","text":"革命文化"},{"key":"B","text":"社会主义先进文化"},{"key":"C","text":"中国共产党人的精神谱系"},{"key":"D","text":"伟大建党精神"}],"answer":["A","B"],"explanation":"在党领导人民的伟大实践中，形成了革命文化和社会主义先进文化，它们共同构成了中国特色社会主义文化的主体内容，是激励人民前进的强大精神力量。"},{"id":1032,"chapter":"第十章 建设社会主义文化强国","type":"multiple","typeText":"多选题","score":4.0,"question":"大力加强马克思主义理论建设，必须( )。","options":[{"key":"A","text":"坚持用马克思主义特别是中国化时代化的马克思主义武装全党、教育人民、指导实践"},{"key":"B","text":"深化马克思主义理论研究和建设"},{"key":"C","text":"加快构建中国特色哲学社会科学"},{"key":"D","text":"拒斥其他国家的学术研究成果"}],"answer":["A","B","C"],"explanation":"加强马克思主义理论建设，关键在于用党的创新理论武装头脑、指导实践，深化理论研究，构建中国特色学科体系、学术体系、话语体系。同时要坚持开放包容，吸收借鉴人类优秀文明成果。"},{"id":1033,"chapter":"第十章 建设社会主义文化强国","type":"multiple","typeText":"多选题","score":4.0,"question":"提高全社会文明程度，必须( )。","options":[{"key":"A","text":"铸就社会主义文化新辉煌"},{"key":"B","text":"广泛开展共产主义远大理想和中国特色社会主义共同理想教育"},{"key":"C","text":"实施公民道德建设工程"},{"key":"D","text":"培育时代新风新貌"}],"answer":["B","C","D"],"explanation":"提高全社会文明程度，重点是加强理想信念教育，实施公民道德建设，弘扬时代新风，提升人民思想觉悟、道德水准、文明素养。铸就文化新辉煌是更宏观的文化建设目标。"},{"id":1034,"chapter":"第十章 建设社会主义文化强国","type":"multiple","typeText":"多选题","score":4.0,"question":"繁荣发展文化产业，要做到( )。","options":[{"key":"A","text":"坚持把经济效益放在首位、经济效益和社会效益相统一"},{"key":"B","text":"深化文化体制改革，完善文化经济政策，不断扩大优质文化产品供给"},{"key":"C","text":"顺应数字产业化和产业数字化发展趋势，加快发展新型文化业态，改造提升传统文化业态"},{"key":"D","text":"围绕国家重大区域发展战略，把握文化产业发展特点规律和资源要素条件，促进形成文化产业发展新格局"},{"key":"E","text":"坚持以文塑旅、以旅彰文，推动文化和旅游融合发展"}],"answer":["B","C","D","E"],"explanation":"繁荣发展文化产业，应坚持把社会效益放在首位、社会效益和经济效益相统一。在此基础上，需要通过深化改革、顺应数字化趋势、优化产业布局、推动文旅融合等措施，推动文化产业高质量发展。"},{"id":1101,"chapter":"第十一章 以保障和改善民生为重点加强社会建设","type":"single","typeText":"单选题","score":3.0,"question":"党的十八大以来，以习近平同志为核心的党中央坚持( )的发展思想，在发展中保障和改善民生，加强和创新社会治理，人民生活全方位改善，人民获得感幸福感安全感不断增强。","options":[{"key":"A","text":"中国共产党领导"},{"key":"B","text":"社会主义本质"},{"key":"C","text":"中国特色社会主义制度"},{"key":"D","text":"以人民为中心"}],"answer":["D"],"explanation":"以人民为中心的发展思想是新时代坚持和发展中国特色社会主义的基本方略之一，体现了我们党全心全意为人民服务的根本宗旨。"},{"id":1102,"chapter":"第十一章 以保障和改善民生为重点加强社会建设","type":"single","typeText":"单选题","score":3.0,"question":"( )是坚持立党为公、执政为民的本质要求。","options":[{"key":"A","text":"中华民族伟大复兴"},{"key":"B","text":"增进民生福祉"},{"key":"C","text":"共同富裕"},{"key":"D","text":"民生"}],"answer":["B"],"explanation":"增进民生福祉是发展的根本目的，是坚持立党为公、执政为民的本质要求，必须不断实现好、维护好、发展好最广大人民根本利益。"},{"id":1103,"chapter":"第十一章 以保障和改善民生为重点加强社会建设","type":"single","typeText":"单选题","score":3.0,"question":"关注( )本身的发展，是社会主义和资本主义的根本区别之一。","options":[{"key":"A","text":"社会"},{"key":"B","text":"人"},{"key":"C","text":"公民"},{"key":"D","text":"经济"}],"answer":["B"],"explanation":"社会主义社会坚持人的全面发展，关注人本身的发展是社会主义的本质要求，与资本主义以资本增殖为根本目的形成鲜明区别。"},{"id":1104,"chapter":"第十一章 以保障和改善民生为重点加强社会建设","type":"single","typeText":"单选题","score":3.0,"question":"( )是社会主义生产的根本目的。","options":[{"key":"A","text":"提高就业水平"},{"key":"B","text":"发展制造业"},{"key":"C","text":"增进民生福祉"},{"key":"D","text":"解决发展不平衡不充分问题"}],"answer":["C"],"explanation":"社会主义生产的根本目的是满足人民日益增长的美好生活需要，增进民生福祉，不断促进人的全面发展和社会全面进步。"},{"id":1105,"chapter":"第十一章 以保障和改善民生为重点加强社会建设","type":"single","typeText":"单选题","score":3.0,"question":"中国式现代化是造福人民的现代化，要求把不断( )放在更加突出的位置。","options":[{"key":"A","text":"坚定社会主义制度"},{"key":"B","text":"推进社会主义发展"},{"key":"C","text":"增进民生福祉"},{"key":"D","text":"坚持人民主体地位"}],"answer":["C"],"explanation":"中国式现代化坚持以人民为中心，把增进民生福祉、促进共同富裕作为出发点和落脚点，不断实现人民对美好生活的向往。"},{"id":1106,"chapter":"第十一章 以保障和改善民生为重点加强社会建设","type":"single","typeText":"单选题","score":3.0,"question":"( )，消除绝对贫困，是全面建成小康社会的底线任务，是必须抓紧抓好的第一民生工程。","options":[{"key":"A","text":"人民幸福"},{"key":"B","text":"共同富裕"},{"key":"C","text":"乡村振兴"},{"key":"D","text":"打赢脱贫攻坚战"}],"answer":["D"],"explanation":"脱贫攻坚是全面建成小康社会的底线任务和标志性指标，是党对人民作出的庄严承诺，必须如期完成。"},{"id":1107,"chapter":"第十一章 以保障和改善民生为重点加强社会建设","type":"single","typeText":"单选题","score":3.0,"question":"( )是发展的“指南针”。","options":[{"key":"A","text":"民主"},{"key":"B","text":"乡村振兴"},{"key":"C","text":"共同富裕"},{"key":"D","text":"民生"}],"answer":["D"],"explanation":"民生是发展的出发点和落脚点，发展为了人民、发展依靠人民、发展成果由人民共享，民生是引领发展的根本导向。"},{"id":1108,"chapter":"第十一章 以保障和改善民生为重点加强社会建设","type":"single","typeText":"单选题","score":3.0,"question":"( )是解决民生问题的“总钥匙”。","options":[{"key":"A","text":"保障"},{"key":"B","text":"扶贫"},{"key":"C","text":"创新"},{"key":"D","text":"发展"}],"answer":["D"],"explanation":"发展是解决我国一切问题的基础和关键，保障和改善民生也必须依靠发展，在发展中解决民生问题。"},{"id":1109,"chapter":"第十一章 以保障和改善民生为重点加强社会建设","type":"single","typeText":"单选题","score":3.0,"question":"( )是民生之源，是改善民生、实现发展成果由人民共享最重要最直接的方式。","options":[{"key":"A","text":"收入分配"},{"key":"B","text":"分配制度"},{"key":"C","text":"社会保障"},{"key":"D","text":"生活幸福"}],"answer":["A"],"explanation":"收入是民生之源，合理的收入分配制度是社会公平的重要体现，是实现发展成果惠及全体人民的基础性制度安排。"},{"id":1110,"chapter":"第十一章 以保障和改善民生为重点加强社会建设","type":"single","typeText":"单选题","score":3.0,"question":"解决好( )问题，是民生改善的“温度计”，对国家长治久安具有重要支撑作用。","options":[{"key":"A","text":"医疗"},{"key":"B","text":"就业"},{"key":"C","text":"住房"},{"key":"D","text":"收入"}],"answer":["B"],"explanation":"就业是民生之本、财富之源，是最大的民生。就业状况直接反映经济运行和社会稳定程度，是民生改善最直观的指标。"},{"id":1111,"chapter":"第十一章 以保障和改善民生为重点加强社会建设","type":"single","typeText":"单选题","score":3.0,"question":"习近平指出：“( )是最大的民生工程、民心工程、根基工程，必须抓紧抓实抓好。”","options":[{"key":"A","text":"就业"},{"key":"B","text":"住房"},{"key":"C","text":"收入分配"},{"key":"D","text":"健康中国"}],"answer":["A"],"explanation":"就业关乎千家万户的生计，是社会稳定的重要保障，必须将其摆在突出位置，实施就业优先战略，强化就业优先政策。"},{"id":1112,"chapter":"第十一章 以保障和改善民生为重点加强社会建设","type":"single","typeText":"单选题","score":3.0,"question":"( )是社会文明进步的基础，是民族昌盛和国家富强的重要标志，是促进人的全面发展的必然要求。","options":[{"key":"A","text":"高质量就业"},{"key":"B","text":"人民健康"},{"key":"C","text":"文化自信"},{"key":"D","text":"医疗发达"}],"answer":["B"],"explanation":"人民健康是民族昌盛和国家富强的重要标志。没有全民健康，就没有全面小康。必须把保障人民健康放在优先发展的战略位置。"},{"id":1113,"chapter":"第十一章 以保障和改善民生为重点加强社会建设","type":"single","typeText":"单选题","score":3.0,"question":"( )是促进共同富裕的基础性制度。","options":[{"key":"A","text":"经济制度"},{"key":"B","text":"分配制度"},{"key":"C","text":"社会制度"},{"key":"D","text":"政治制度"}],"answer":["B"],"explanation":"分配制度是社会主义市场经济体制的重要组成部分，是促进共同富裕、维护社会公平正义的基础性制度安排。"},{"id":1114,"chapter":"第十一章 以保障和改善民生为重点加强社会建设","type":"single","typeText":"单选题","score":3.0,"question":"( )是最基本的民生，是劳动者赖以生存和发展的基础、共享经济发展成果的基本条件，关系到亿万劳动者及其家庭的切身利益。","options":[{"key":"A","text":"社会保障"},{"key":"B","text":"教育"},{"key":"C","text":"就业"},{"key":"D","text":"医疗"}],"answer":["C"],"explanation":"就业是民生之本，是劳动者获得收入、实现价值、融入社会的基本途径，是最基本、最重要的民生。"},{"id":1115,"chapter":"第十一章 以保障和改善民生为重点加强社会建设","type":"single","typeText":"单选题","score":3.0,"question":"( )是社会文明进步的基础，是民族昌盛和国家富强的重要标志，是促进人的全面发展的必然要求。","options":[{"key":"A","text":"改善民生"},{"key":"B","text":"社会保障体系"},{"key":"C","text":"人民健康"},{"key":"D","text":"就业"}],"answer":["C"],"explanation":"人民健康是经济社会发展的基础条件，是民族昌盛和国家富强的重要标志，也是广大人民群众的共同追求。"},{"id":1116,"chapter":"第十一章 以保障和改善民生为重点加强社会建设","type":"single","typeText":"单选题","score":3.0,"question":"( )提出创新社会治理体制，从‘社会管理’到‘社会治理’，虽然只是一字之差，却意味着社会建设理念、体制和方式的重大变革。","options":[{"key":"A","text":"党的十八大"},{"key":"B","text":"党的十八届三中全会"},{"key":"C","text":"党的十九届六中全会"},{"key":"D","text":"党的二十大"}],"answer":["B"],"explanation":"党的十八届三中全会通过的《决定》首次提出“创新社会治理体制”，用“社会治理”替代“社会管理”，体现了党在社会建设理念和实践上的重大创新。"},{"id":1117,"chapter":"第十一章 以保障和改善民生为重点加强社会建设","type":"single","typeText":"单选题","score":3.0,"question":"( )是进行社会治理的基础，也是提高社会治理效能的保障。","options":[{"key":"A","text":"社会治理体系"},{"key":"B","text":"法治建设"},{"key":"C","text":"公平正义"},{"key":"D","text":"党的领导"}],"answer":["A"],"explanation":"完善的社会治理体系是有效开展社会治理工作的组织基础和制度保障，对于提升社会治理系统化、社会化、法治化、智能化、专业化水平至关重要。"},{"id":1118,"chapter":"第十一章 以保障和改善民生为重点加强社会建设","type":"single","typeText":"单选题","score":3.0,"question":"( )是国家治理的基石，城乡社区是社会治理最基本的单元，是党和政府联系、服务居民群众的‘最后一公里’。","options":[{"key":"A","text":"改善民生"},{"key":"B","text":"人民当家作主"},{"key":"C","text":"基层治理"},{"key":"D","text":"为人民服务"}],"answer":["C"],"explanation":"基层治理是国家治理的基石，城乡社区是基层治理的重要依托。提升基层治理能力，直接关系到国家治理体系和治理能力现代化水平。"},{"id":1119,"chapter":"第十一章 以保障和改善民生为重点加强社会建设","type":"single","typeText":"单选题","score":3.0,"question":"理念是完善社会治理体系的先导，必须坚持( )的社会治理理念。","options":[{"key":"A","text":"科学实效"},{"key":"B","text":"系统化专业化"},{"key":"C","text":"共建共治共享"},{"key":"D","text":"创新协调发展"}],"answer":["C"],"explanation":"共建共治共享是社会治理制度建设的基本遵循，体现了党委领导、政府负责、民主协商、社会协同、公众参与、法治保障、科技支撑的社会治理要求。"},{"id":1120,"chapter":"第十一章 以保障和改善民生为重点加强社会建设","type":"single","typeText":"单选题","score":3.0,"question":"充分发挥( )领导核心作用，把党的领导贯穿社会治理全过程各环节。","options":[{"key":"A","text":"政府机构"},{"key":"B","text":"居民社区"},{"key":"C","text":"基层党组织"},{"key":"D","text":"中国共产党"}],"answer":["C"],"explanation":"基层党组织是党在社会基层组织中的战斗堡垒，是党的全部工作和战斗力的基础。必须强化基层党组织政治功能和组织功能，引领基层社会治理。"},{"id":1121,"chapter":"第十一章 以保障和改善民生为重点加强社会建设","type":"single","typeText":"单选题","score":3.0,"question":"社区社会治理成效很大程度取决于( )能力和水平。","options":[{"key":"A","text":"市域社会治理"},{"key":"B","text":"改善人民生活"},{"key":"C","text":"基层党组织"},{"key":"D","text":"政府机构"}],"answer":["A"],"explanation":"市域层面具有较为完备的社会治理体系和较强的资源统筹能力，是防范化解重大矛盾风险的关键层级，其治理能力直接影响基层社区的治理效能。"},{"id":1122,"chapter":"第十一章 以保障和改善民生为重点加强社会建设","type":"multiple","typeText":"多选题","score":5.0,"question":"民生工作离老百姓最近，同老百姓生活最密切，( )是我们的第一要务。","options":[{"key":"A","text":"解决发展问题"},{"key":"B","text":"改善民生"},{"key":"C","text":"满足人民生活"},{"key":"D","text":"促进精神文明建设"}],"answer":["A","B"],"explanation":"发展是硬道理，是解决所有问题的关键；改善民生是发展的根本目的。二者紧密相连，必须坚持在发展中保障和改善民生。"},{"id":1123,"chapter":"第十一章 以保障和改善民生为重点加强社会建设","type":"multiple","typeText":"多选题","score":4.0,"question":"( )，是保障和改善民生的工作思路。","options":[{"key":"A","text":"坚守底线"},{"key":"B","text":"突出重点"},{"key":"C","text":"完善制度"},{"key":"D","text":"引导预期"}],"answer":["A","B","C","D"],"explanation":"保障和改善民生需要坚持“坚守底线、突出重点、完善制度、引导预期”的工作思路，兜牢民生底线，抓住重点群体，健全长效机制，稳定社会预期。"},{"id":1124,"chapter":"第十一章 以保障和改善民生为重点加强社会建设","type":"multiple","typeText":"多选题","score":4.0,"question":"中国特色的社会保障体系，是在( )基础上建立起来的。","options":[{"key":"A","text":"坚持社会主义原则"},{"key":"B","text":"立足中国实际"},{"key":"C","text":"总结我国社会保障实践经验"},{"key":"D","text":"学习借鉴国外有益经验"}],"answer":["A","B","C","D"],"explanation":"中国特色的社会保障体系，是在坚持社会主义基本制度、立足我国国情和发展阶段、总结自身实践经验、并吸收借鉴国际有益做法的基础上，逐步建立和完善起来的。"},{"id":1125,"chapter":"第十一章 以保障和改善民生为重点加强社会建设","type":"multiple","typeText":"多选题","score":4.0,"question":"新时代加强和创新社会治理，要求坚持( )，探索一条符合中国社会发展实际、更可持续的中国特色社会主义社会治理之路。","options":[{"key":"A","text":"系统治理"},{"key":"B","text":"依法治理"},{"key":"C","text":"综合治理"},{"key":"D","text":"源头治理"}],"answer":["A","B","C","D"],"explanation":"加强和创新社会治理，必须坚持系统治理、依法治理、综合治理、源头治理，多措并举，全面提升社会治理社会化、法治化、智能化、专业化水平。"},{"id":1126,"chapter":"第十一章 以保障和改善民生为重点加强社会建设","type":"multiple","typeText":"多选题","score":4.0,"question":"运用( )统筹社会力量、平衡社会利益、调节社会关系、规范社会行为、化解社会矛盾。","options":[{"key":"A","text":"法律制度"},{"key":"B","text":"法律思维"},{"key":"C","text":"法治思维"},{"key":"D","text":"法治方式"}],"answer":["C","D"],"explanation":"法治是社会治理的基本方式。必须善于运用法治思维和法治方式深化改革、推动发展、化解矛盾、维护稳定，把社会治理纳入法治化轨道。"},{"id":1127,"chapter":"第十一章 以保障和改善民生为重点加强社会建设","type":"multiple","typeText":"多选题","score":4.0,"question":"要不断创新社会治理的理念思路、体制机制和方法手段，打造( )的社会治理新格局。","options":[{"key":"A","text":"共建"},{"key":"B","text":"共治"},{"key":"C","text":"共享"},{"key":"D","text":"共赢"}],"answer":["A","B","C"],"explanation":"打造共建共治共享的社会治理格局，是推进社会治理现代化的目标要求，旨在形成人人参与、人人尽责、人人享有的良好局面。"},{"id":1128,"chapter":"第十一章 以保障和改善民生为重点加强社会建设","type":"multiple","typeText":"多选题","score":4.0,"question":"社会治理关系( )。","options":[{"key":"A","text":"国家长治久安"},{"key":"B","text":"社会安定有序"},{"key":"C","text":"人民安居乐业"},{"key":"D","text":"深化改革开放"}],"answer":["A","B","C"],"explanation":"社会治理是国家治理的重要方面，良好的社会治理对于维护国家安全、社会安定、人民安宁具有基础性意义，是实现国家长治久安、社会和谐稳定、人民幸福安康的重要保障。"},{"id":1129,"chapter":"第十一章 以保障和改善民生为重点加强社会建设","type":"multiple","typeText":"多选题","score":4.0,"question":"坚持( )是保障和改善民生的重要方针。","options":[{"key":"A","text":"尽力而为"},{"key":"B","text":"量力而行"},{"key":"C","text":"综合治理"},{"key":"D","text":"源头治理"}],"answer":["A","B"],"explanation":"保障和改善民生既要积极作为、尽力而为，切实解决群众急难愁盼问题；又要实事求是、量力而行，使民生改善与经济发展相协调、可持续。"},{"id":1130,"chapter":"第十一章 以保障和改善民生为重点加强社会建设","type":"multiple","typeText":"多选题","score":4.0,"question":"社会治理的中心必须向基层下移，落实到城乡社区，有效防范化解社会矛盾和风险，维护城乡社区群众和谐稳定的生活，努力打造( )的幸福家园。","options":[{"key":"A","text":"和谐有序"},{"key":"B","text":"绿色文明"},{"key":"C","text":"创新包容"},{"key":"D","text":"共建共享"}],"answer":["A","B","C","D"],"explanation":"推动社会治理重心向基层下移，建设和谐有序、绿色文明、创新包容、共建共享的城乡社区，是提升基层治理效能、增强人民群众获得感幸福感安全感的重要途径。"},{"id":1201,"chapter":"第十二章 建设社会主义生态文明","type":"single","typeText":"单选题","score":3.0,"question":"根据习近平新时代中国特色社会主义思想，以下关于建设生态文明的表述哪一项是正确的？","options":[{"key":"A","text":"将经济发展与生态环境保护对立起来，牺牲生态环境来推动经济增长"},{"key":"B","text":"忽视生态文明建设，将生态环境问题留待未来解决"},{"key":"C","text":"坚持绿水青山就是金山银山的理念，推动人与自然和谐共生"},{"key":"D","text":"以GDP增长为核心，不考虑生态环境影响"}],"answer":["C"],"explanation":"坚持绿水青山就是金山银山的理念，体现了经济发展与环境保护的辩证统一，是建设生态文明的核心理念。"},{"id":1202,"chapter":"第十二章 建设社会主义生态文明","type":"single","typeText":"单选题","score":3.0,"question":"我国要建设什么样的生态文明？","options":[{"key":"A","text":"树立社会主义生态文明观"},{"key":"B","text":"树立人与自然和谐共生"},{"key":"C","text":"树立人与自然是生命共同体"},{"key":"D","text":"树立人类命运共同体"}],"answer":["C"],"explanation":"建设生态文明，必须坚持人与自然是生命共同体的理念，强调人类与自然休戚与共、共生共存的关系。"},{"id":1203,"chapter":"第十二章 建设社会主义生态文明","type":"single","typeText":"单选题","score":2.0,"question":"生态文明建设的核心是( )。","options":[{"key":"A","text":"经济增长"},{"key":"B","text":"资源节约"},{"key":"C","text":"环境保护"},{"key":"D","text":"文化传承"}],"answer":["C"],"explanation":"环境保护是生态文明建设的核心任务，旨在解决突出环境问题，维护生态安全，增进民生福祉。"},{"id":1204,"chapter":"第十二章 建设社会主义生态文明","type":"single","typeText":"单选题","score":2.0,"question":"“美丽中国”和绿色发展在“十三五”规划中着墨颇多，生态文明建设事关实现“两个一百年”奋斗目标，事关中华民族永续发展，是建设美丽中国的必然要求。我国生态文明建设的基本方针是( )。","options":[{"key":"A","text":"重点突破和整体推进"},{"key":"B","text":"绿色发展、循环发展、低碳发展"},{"key":"C","text":"节约优先、保护优先、自然恢复"},{"key":"D","text":"深化改革和创新驱动"}],"answer":["C"],"explanation":"节约优先、保护优先、自然恢复为主是生态文明建设的基本方针，体现了尊重自然、顺应自然、保护自然的理念。"},{"id":1205,"chapter":"第十二章 建设社会主义生态文明","type":"single","typeText":"单选题","score":2.0,"question":"( )国家领导人(同志)做出了“保护环境的实质就是保护生产力”的科学论断？","options":[{"key":"A","text":"毛泽东"},{"key":"B","text":"邓小平"},{"key":"C","text":"江泽民"},{"key":"D","text":"胡锦涛"}],"answer":["C"],"explanation":"江泽民同志提出了“保护环境的实质就是保护生产力”的重要论断，深刻揭示了环境保护与经济发展的内在统一关系。"},{"id":1206,"chapter":"第十二章 建设社会主义生态文明","type":"single","typeText":"单选题","score":2.0,"question":"建设生态文明，我们应该树立( )的理念。","options":[{"key":"A","text":"尊重自然、敬畏自然、爱护自然"},{"key":"B","text":"尊重自然、爱护自然、战胜自然"},{"key":"C","text":"尊重自然、顺应自然、战胜自然"},{"key":"D","text":"尊重自然、顺应自然、保护自然"}],"answer":["D"],"explanation":"树立尊重自然、顺应自然、保护自然的生态文明理念，是正确处理人与自然关系、推进生态文明建设的思想基础。"},{"id":1207,"chapter":"第十二章 建设社会主义生态文明","type":"single","typeText":"单选题","score":2.0,"question":"关于建设什么样的生态文明，下列说法正确的是( )。","options":[{"key":"A","text":"蓝天保卫战是全面建成小康社会的三大攻坚战之一"},{"key":"B","text":"生态环境安全是国家安全的重要组成部分，是经济社会持续健康发展的重要保障"},{"key":"C","text":"加快构建生态文明体系是构建高质量现代化经济体系的必然要求，解决污染问题的根本之策"},{"key":"D","text":"地方政府主要领导是本行政区域生态环境保护第一责任人，各相关部门要履行好生态环境保护职责，使各部门守土有责、守土尽责，分工协作、共同发力"}],"answer":["B"],"explanation":"生态环境安全是国家安全体系的重要组成部分，良好的生态环境是经济社会持续健康发展的基础和保障。"},{"id":1208,"chapter":"第十二章 建设社会主义生态文明","type":"single","typeText":"单选题","score":2.0,"question":"我国生态文明建设的重要战略是( )。","options":[{"key":"A","text":"可持续发展战略"},{"key":"B","text":"快速发展战略"},{"key":"C","text":"重工业化战略"},{"key":"D","text":"出口导向战略"}],"answer":["A"],"explanation":"可持续发展战略是我国长期坚持的重大战略，生态文明建设是实现可持续发展的必由之路和内在要求。"},{"id":1209,"chapter":"第十二章 建设社会主义生态文明","type":"single","typeText":"单选题","score":2.0,"question":"生态文明建设的核心理念是( )。","options":[{"key":"A","text":"绿水青山就是金山银山"},{"key":"B","text":"良好生态环境是最普惠的民生福祉"},{"key":"C","text":"绿色发展是发展观的深刻革命"},{"key":"D","text":"统筹山水林湖田草沙系统治理"}],"answer":["A"],"explanation":"“绿水青山就是金山银山”是习近平生态文明思想的核心理念，科学阐明了生态环境保护与经济发展的辩证统一关系。"},{"id":1210,"chapter":"第十二章 建设社会主义生态文明","type":"single","typeText":"单选题","score":2.0,"question":"习近平生态文明思想深刻回答了“为什么建设生态文明”“建设什么样的生态文明”“怎样建设生态文明”等重大理论和实践问题。以下( )最准确地反映了习近平生态文明思想中关于建设生态文明的具体要求。","options":[{"key":"A","text":"单纯追求经济增长，忽视环境保护"},{"key":"B","text":"以牺牲环境为代价，实现快速发展"},{"key":"C","text":"坚持人与自然和谐共生，推进绿色发展"},{"key":"D","text":"先污染后治理，走西方工业化老路"}],"answer":["C"],"explanation":"习近平生态文明思想强调坚持人与自然和谐共生，走生产发展、生活富裕、生态良好的文明发展道路，推进绿色发展。"},{"id":1211,"chapter":"第十二章 建设社会主义生态文明","type":"single","typeText":"单选题","score":2.0,"question":"在下列选项中，( )是建设生态文明的关键要素。","options":[{"key":"A","text":"经济增长优先，环境问题次之"},{"key":"B","text":"大规模工业化，忽视资源消耗"},{"key":"C","text":"绿色发展，实现人与自然和谐共生"},{"key":"D","text":"短期利益最大化，不考虑长远影响"}],"answer":["C"],"explanation":"绿色发展是生态文明建设的核心要义和关键路径，旨在实现经济社会发展与生态环境保护的协同共进。"},{"id":1212,"chapter":"第十二章 建设社会主义生态文明","type":"single","typeText":"单选题","score":2.0,"question":"新时代中国特色社会主义生态文明建设中，以下( )是正确的环境治理策略。","options":[{"key":"A","text":"仅依靠政府力量进行环境治理"},{"key":"B","text":"企业可以自行决定是否遵守环保法规"},{"key":"C","text":"公众不需要参与环境保护"},{"key":"D","text":"政府、企业和公众共同参与环境"}],"answer":["D"],"explanation":"现代环境治理体系强调构建政府为主导、企业为主体、社会组织和公众共同参与的格局，实现多元共治。"},{"id":1213,"chapter":"第十二章 建设社会主义生态文明","type":"single","typeText":"单选题","score":2.0,"question":"习近平总书记强调：“生态文明是( )文明发展的历史趋势。”","options":[{"key":"A","text":"历史"},{"key":"B","text":"环境"},{"key":"C","text":"社会"},{"key":"D","text":"人类"}],"answer":["D"],"explanation":"生态文明是人类社会继原始文明、农业文明、工业文明之后的新型文明形态，是人类文明发展的历史趋势和必然选择。"},{"id":1214,"chapter":"第十二章 建设社会主义生态文明","type":"single","typeText":"单选题","score":2.0,"question":"在推动生态文明建设过程中，以下( )最符合可持续发展的原则？","options":[{"key":"A","text":"限制一切工业活动，回归自然原始状态"},{"key":"B","text":"优先发展重工业，不考虑环境污染和资源消耗"},{"key":"C","text":"实施生态补偿机制，平衡经济发展与生态保护"},{"key":"D","text":"鼓励一次性产品消费，以满足快速增长的物质需求"}],"answer":["C"],"explanation":"生态补偿机制是运用经济手段保护生态环境、调节利益关系的重要制度安排，是践行“绿水青山就是金山银山”理念、实现可持续发展的重要举措。"},{"id":1215,"chapter":"第十二章 建设社会主义生态文明","type":"single","typeText":"单选题","score":2.0,"question":"我国在推进生态文明建设过程中，以下( )最能体现“绿水青山就是金山银山”的发展理念？","options":[{"key":"A","text":"大力发展高耗能产业，提高地区经济增长速度"},{"key":"B","text":"实施严格的环保法规，限制企业污染物排放"},{"key":"C","text":"推进生态修复工程，恢复受损的自然生态系统"},{"key":"D","text":"发展绿色低碳产业，促进经济与环境保护的协调发展"}],"answer":["D"],"explanation":"发展绿色低碳产业，能够将生态优势转化为经济优势，实现生态环境保护与经济社会高质量发展的有机统一，是“两山”理念的生动实践。"},{"id":1216,"chapter":"第十二章 建设社会主义生态文明","type":"single","typeText":"单选题","score":2.0,"question":"下列哪项措施不属于生态文明建设的范畴？","options":[{"key":"A","text":"推广清洁能源"},{"key":"B","text":"增加城市化建设"},{"key":"C","text":"加强污染防治"},{"key":"D","text":"促进生物多样性保护"}],"answer":["B"],"explanation":"单纯的增加城市化建设，如果不注重生态环保和绿色发展，可能带来资源消耗、污染排放等问题，不属于生态文明建设的直接范畴。生态文明建设更强调绿色、低碳、循环的发展方式和生活方式。"},{"id":1217,"chapter":"第十二章 建设社会主义生态文明","type":"single","typeText":"单选题","score":2.0,"question":"生态文明建设的基本路径是( )。","options":[{"key":"A","text":"产业升级"},{"key":"B","text":"创新科技"},{"key":"C","text":"法律法规的制定和执行"},{"key":"D","text":"人民群众的共同努力"}],"answer":["D"],"explanation":"生态文明建设是全社会共同的事业，必须紧紧依靠人民群众，形成人人关心、人人参与、人人享有的良好社会氛围，这是最广泛、最深厚的力量基础。"},{"id":1218,"chapter":"第十二章 建设社会主义生态文明","type":"single","typeText":"单选题","score":2.0,"question":"下列哪项措施有助于推动生态文明建设？","options":[{"key":"A","text":"大量使用一次性塑料制品"},{"key":"B","text":"随意排放工业废水"},{"key":"C","text":"推广清洁能源和节能技术"},{"key":"D","text":"过度开采自然资源"}],"answer":["C"],"explanation":"推广清洁能源和节能技术，是从源头上减少污染排放、降低资源消耗的关键举措，是推动绿色低碳发展、建设生态文明的重要内容。"},{"id":1219,"chapter":"第十二章 建设社会主义生态文明","type":"single","typeText":"单选题","score":2.0,"question":"可持续发展的原则不包括( )。","options":[{"key":"A","text":"公平性原则"},{"key":"B","text":"持续性原则"},{"key":"C","text":"共同性原则"},{"key":"D","text":"特殊性原则"}],"answer":["D"],"explanation":"可持续发展的基本原则包括公平性原则（代内公平和代际公平）、持续性原则（不超过资源环境承载力）、共同性原则（全球共同努力），不包括“特殊性原则”。"},{"id":1220,"chapter":"第十二章 建设社会主义生态文明","type":"single","typeText":"单选题","score":2.0,"question":"以下关于建设生态文明的说法，哪项不正确？","options":[{"key":"A","text":"在发展经济时，必须优先考虑生态环境的承载能力，避免破坏性开发"},{"key":"B","text":"实施生态补偿机制，可以有效激励各地区保护生态环境"},{"key":"C","text":"加强科技创新，通过绿色技术和产业优化，实现资源高效利用"},{"key":"D","text":"实现生态文明的核心在于经济高速增长，环境问题可通过后期修复解决"}],"answer":["D"],"explanation":"生态文明建设强调在发展过程中同步解决环境问题，坚持保护优先、预防为主，不能走“先污染后治理”的老路。环境问题一旦形成，往往治理成本高昂、修复周期漫长。"},{"id":1221,"chapter":"第十二章 建设社会主义生态文明","type":"single","typeText":"单选题","score":2.0,"question":"以下哪个是生态文明建设的重要举措？","options":[{"key":"A","text":"大规模开发自然资源"},{"key":"B","text":"限制经济发展规模"},{"key":"C","text":"推动生态保护与修复"},{"key":"D","text":"加大工业生产量"}],"answer":["C"],"explanation":"生态保护与修复是生态文明建设的基础性工作，旨在提升生态系统质量和稳定性，筑牢国家生态安全屏障。"},{"id":1222,"chapter":"第十二章 建设社会主义生态文明","type":"single","typeText":"单选题","score":2.0,"question":"关于生态文明建设，下列说法正确的是( )。","options":[{"key":"A","text":"蓝天保卫战是全面建成小康社会的三大攻坚战之一"},{"key":"B","text":"加快构建生态文明体系是解决污染问题的根本之策"},{"key":"C","text":"生态环境安全是经济社会持续健康发展的重要保障"},{"key":"D","text":"地方政府主要领导是本行政区域生态环境保护第一责任人"}],"answer":["C"],"explanation":"生态环境安全是国家安全的重要组成部分，是经济社会持续健康发展的重要基础和保障，关系人民福祉和民族未来。"},{"id":1223,"chapter":"第十二章 建设社会主义生态文明","type":"single","typeText":"单选题","score":2.0,"question":"“生态文明提倡适度消费，追求基本生活需要的满足，崇尚精神和文化的享受”属于下面哪个层次？","options":[{"key":"A","text":"物质层面"},{"key":"B","text":"生产方式层面"},{"key":"C","text":"生活方式层面"},{"key":"D","text":"以上都不是"}],"answer":["C"],"explanation":"题干描述的是消费观念和生活态度，属于生活方式层面的内容。生态文明建设要求形成简约适度、绿色低碳、文明健康的生活方式和消费模式。"},{"id":1224,"chapter":"第十二章 建设社会主义生态文明","type":"single","typeText":"单选题","score":2.0,"question":"党的( )以来，我国全面加强生态文明建设，决心之大、力度之大、成效之大前所未有。","options":[{"key":"A","text":"十一届三中全会"},{"key":"B","text":"十八大"},{"key":"C","text":"二十大"},{"key":"D","text":"十三大"}],"answer":["B"],"explanation":"党的十八大将生态文明建设纳入中国特色社会主义事业“五位一体”总体布局，我国生态文明建设从认识到实践发生了历史性、转折性、全局性变化。"},{"id":1225,"chapter":"第十二章 建设社会主义生态文明","type":"single","typeText":"单选题","score":2.0,"question":"将( )纳入政府的工作目标与政绩考核指标，各政府和环保主管部门的环境决策行为、经济环境行为和环境管理部门的监管工作，听取群众意见。","options":[{"key":"A","text":"治理环境"},{"key":"B","text":"节约资源"},{"key":"C","text":"保护生态"},{"key":"D","text":"保护环境"}],"answer":["D"],"explanation":"将环境保护目标纳入政绩考核，是落实地方政府环保责任、强化环境监管的重要手段，有利于引导各级政府树立正确的发展观和政绩观。"},{"id":1226,"chapter":"第十二章 建设社会主义生态文明","type":"single","typeText":"单选题","score":2.0,"question":"建设什么样的生态文明？","options":[{"key":"A","text":"以经济增长为首要目标，忽视环境保护"},{"key":"B","text":"强调人与自然和谐共生，追求可持续"},{"key":"C","text":"过度开发资源，以提高短期收益为目标"},{"key":"D","text":"保护自然环境，但不重视社会公平和经济发展"}],"answer":["B"],"explanation":"我们要建设的生态文明，是以人与自然和谐共生为本质特征，以实现经济社会可持续发展、人与自然和谐发展为目标的生态文明。"},{"id":1227,"chapter":"第十二章 建设社会主义生态文明","type":"single","typeText":"单选题","score":2.0,"question":"在毛概理论中，关于我国应建设什么样的生态文明，以下哪项描述最为准确？","options":[{"key":"A","text":"以牺牲环境为代价，追求经济的快速发展"},{"key":"B","text":"高度重视环境保护，实现经济发展与环境保护的双赢"},{"key":"C","text":"只需关注城市绿化，无需关注农村及偏远地区的生态环境"},{"key":"D","text":"依赖国外先进技术，忽视国内自主创新在生态文明建设中的作用"}],"answer":["B"],"explanation":"毛泽东思想及其发展（包括中国特色社会主义理论体系）强调在发展中保护、在保护中发展，追求经济发展与环境保护的协调统一和双赢。"},{"id":1228,"chapter":"第十二章 建设社会主义生态文明","type":"single","typeText":"单选题","score":2.0,"question":"习近平生态文明思想明确了建设什么样的生态文明，其中不包括以下哪一项？","options":[{"key":"A","text":"人与自然和谐共生的现代化"},{"key":"B","text":"绿水青山就是金山银山的发展理念"},{"key":"C","text":"以牺牲环境为代价追求经济的高速发展"},{"key":"D","text":"共建美丽中国，让人民群众在绿水青山中共享自然之美、生命之美、生活之美"}],"answer":["C"],"explanation":"习近平生态文明思想坚决反对以牺牲环境为代价换取经济增长，强调要走出一条生产发展、生活富裕、生态良好的文明发展道路。"},{"id":1229,"chapter":"第十二章 建设社会主义生态文明","type":"single","typeText":"单选题","score":2.0,"question":"在建设生态文明的过程中，我国强调的是要构建一个怎样的生态文明体系？","options":[{"key":"A","text":"以工业发展为主导，追求高速经济增长的生态文明体系"},{"key":"B","text":"以资源节约、环境友好、生态保育为核心，人与自然和谐共生的生态文明体系"},{"key":"C","text":"以牺牲环境为代价，换取短期经济利益的生态文明体系"},{"key":"D","text":"单纯强调生态保护，忽视经济社会发展的生态文明体系"}],"answer":["B"],"explanation":"我国要构建的生态文明体系，是以生态价值观念为准则、以产业生态化和生态产业化为主体的生态经济体系，以及相应的目标责任、生态文明制度、生态安全等体系，核心是促进人与自然和谐共生。"},{"id":1230,"chapter":"第十二章 建设社会主义生态文明","type":"single","typeText":"单选题","score":2.0,"question":"在推进生态文明建设的过程中，我们应当致力于构建什么样的生态文明体系？","options":[{"key":"A","text":"以工业发展为主导，追求经济增长的生态文明体系"},{"key":"B","text":"以资源消耗为核心，注重物质财富积累的生态文明体系"},{"key":"C","text":"以人与自然和谐共生为目标，注重绿色发展和生态保护的生态文明体系"},{"key":"D","text":"以科技创新为引领，忽视环境保护的生态文明体系"}],"answer":["C"],"explanation":"构建生态文明体系，必须坚持以人与自然和谐共生为目标，将绿色发展、生态保护融入经济社会发展各方面和全过程。"},{"id":1231,"chapter":"第十二章 建设社会主义生态文明","type":"single","typeText":"单选题","score":2.0,"question":"在生态文明建设方面，党的十九大将( )作为新时代坚持和发展中国特色社会主义的基本方略之一。","options":[{"key":"A","text":"坚持人与自然和谐共生"},{"key":"B","text":"坚持人定胜天"},{"key":"C","text":"坚持科学发展"},{"key":"D","text":"坚持控制自然"}],"answer":["A"],"explanation":"党的十九大将“坚持人与自然和谐共生”列入新时代坚持和发展中国特色社会主义的基本方略，凸显了生态文明建设在党和国家事业发展全局中的重要地位。"},{"id":1232,"chapter":"第十二章 建设社会主义生态文明","type":"multiple","typeText":"多选题","score":6.0,"question":"以下关于我国建设生态文明说法正确的是( )。","options":[{"key":"A","text":"树立尊重自然、顺应自然、保护自然的生态文明理念"},{"key":"B","text":"着力建设资源节约型、环境友好型社会"},{"key":"C","text":"坚持节约优先、保护优先、自然恢复为主的方针"},{"key":"D","text":"坚持节约资源和保护环境的基本国策"}],"answer":["A","B","C","D"],"explanation":"这些选项分别从理念、目标、方针、国策等不同层面，全面概括了我国建设生态文明的核心内容和基本要求。"},{"id":1233,"chapter":"第十二章 建设社会主义生态文明","type":"multiple","typeText":"多选题","score":6.0,"question":"在整个发展过程中，我们都要坚持( )的方针，要像保护眼睛一样保护生态环境。","options":[{"key":"A","text":"节约优先"},{"key":"B","text":"发展为主"},{"key":"C","text":"保护优先"},{"key":"D","text":"自然恢复为主"}],"answer":["A","C","D"],"explanation":"节约优先、保护优先、自然恢复为主，是处理发展与保护关系、推进生态文明建设必须长期坚持的基本方针。"},{"id":1234,"chapter":"第十二章 建设社会主义生态文明","type":"multiple","typeText":"多选题","score":6.0,"question":"绿水青山就是金山银山，阐述了( )的关系。","options":[{"key":"A","text":"社会和谐"},{"key":"B","text":"经济发展"},{"key":"C","text":"生态环境保护"},{"key":"D","text":"人类生存"}],"answer":["B","C"],"explanation":"“绿水青山就是金山银山”深刻揭示了经济发展与生态环境保护之间的辩证统一关系，保护生态环境就是保护生产力，改善生态环境就是发展生产力。"},{"id":1235,"chapter":"第十二章 建设社会主义生态文明","type":"multiple","typeText":"多选题","score":6.0,"question":"建设生态文明是关系( )、关乎( )的千年大计。","options":[{"key":"A","text":"人民福祉"},{"key":"B","text":"国家发展"},{"key":"C","text":"中华民族永续发展"},{"key":"D","text":"社会长治久安"}],"answer":["A","C"],"explanation":"生态文明建设直接关系到人民群众的生活质量和健康，关系到中华民族的永续发展和伟大复兴，是功在当代、利在千秋的伟大事业。"},{"id":1236,"chapter":"第十二章 建设社会主义生态文明","type":"multiple","typeText":"多选题","score":6.0,"question":"推进生态文明建设，解决( )的问题，必须采取一些硬措施，真抓实干才能见效。","options":[{"key":"A","text":"资源约束趋紧"},{"key":"B","text":"经济社会发展"},{"key":"C","text":"环境污染严重"},{"key":"D","text":"生态系统退化"}],"answer":["A","C","D"],"explanation":"资源约束趋紧、环境污染严重、生态系统退化是当前我国生态文明建设面临的突出问题和严峻挑战，必须下大力气加以解决。"},{"id":1237,"chapter":"第十二章 建设社会主义生态文明","type":"multiple","typeText":"多选题","score":6.0,"question":"党的二十大报告指出：“( )，是全面建设社会主义现代化国家的内在要求。”","options":[{"key":"A","text":"敬畏自然"},{"key":"B","text":"尊重自然"},{"key":"C","text":"顺应自然"},{"key":"D","text":"保护自然"}],"answer":["B","C","D"],"explanation":"党的二十大报告强调，尊重自然、顺应自然、保护自然，是全面建设社会主义现代化国家的内在要求。这指明了中国式现代化是人与自然和谐共生的现代化。"},{"id":1701,"chapter":"第十七章 全面从严治党","type":"single","typeText":"单选题","score":10.0,"question":"新时代党的建设的鲜明主题是( )","options":[{"key":"A","text":"党的自我革命"},{"key":"B","text":"全面从严治党"},{"key":"C","text":"以政治建设统领党的建设"},{"key":"D","text":"深入推进新时代党的建设新的伟大工程"}],"answer":["B"],"explanation":"全面从严治党是新时代党的建设的鲜明主题，这是对党的建设时代任务的准确定位。"},{"id":1702,"chapter":"第十七章 全面从严治党","type":"single","typeText":"单选题","score":10.0,"question":"党的建设的一贯要求和根本方针是( )","options":[{"key":"A","text":"把思想建设放在首位"},{"key":"B","text":"把政治建设放在首位"},{"key":"C","text":"党要管党，从严治党"},{"key":"D","text":"关键在严，要害在治"}],"answer":["C"],"explanation":"“党要管党、从严治党”是我们党加强自身建设的一贯要求和根本方针，体现了我们党自我净化、自我完善、自我革新、自我提高的自觉。"},{"id":1703,"chapter":"第十七章 全面从严治党","type":"single","typeText":"单选题","score":10.0,"question":"深入推进新时代党的建设新的伟大工程，必须注重系统性整体性协同性，坚持以( )为统领持续抓好党的各方面建设。","options":[{"key":"A","text":"思想建设"},{"key":"B","text":"组织建设"},{"key":"C","text":"政治建设"},{"key":"D","text":"纪律建设"}],"answer":["C"],"explanation":"党的政治建设是党的根本性建设，决定党的建设方向和效果。因此，必须坚持以党的政治建设为统领，全面推进党的各项建设。"},{"id":1704,"chapter":"第十七章 全面从严治党","type":"multiple","typeText":"多选题","score":10.0,"question":"全面建设社会主义现代化国家、全面推进中华民族的伟大复兴的关键( )","options":[{"key":"A","text":"关键在坚持中国特色社会主义道路"},{"key":"B","text":"关键在党"},{"key":"C","text":"关键在全面深化改革"},{"key":"D","text":"关键在全面从严治党"}],"answer":["B","D"],"explanation":"事业兴衰，关键在党。党的领导是根本保证，而全面从严治党则是确保党始终成为坚强领导核心的关键所在。"},{"id":1705,"chapter":"第十七章 全面从严治党","type":"multiple","typeText":"多选题","score":10.0,"question":"党的领导是中国特色社会主义制度的最大优势，是党和国家各项事业发展的根本政治保证。全面从严治党，（ ）","options":[{"key":"A","text":"核心是加强党的领导"},{"key":"B","text":"基础在全面"},{"key":"C","text":"关键在严"},{"key":"D","text":"要害在治"}],"answer":["A","B","C","D"],"explanation":"这是对全面从严治党内涵的完整概括。“核心是加强党的领导”指明目的；“基础在全面”强调范围覆盖；“关键在严”体现标准要求；“要害在治”突出治理效能。"},{"id":1706,"chapter":"第十七章 全面从严治党","type":"multiple","typeText":"多选题","score":10.0,"question":"党的建设包括，政治建设、思想建设、组织建设、（ ）","options":[{"key":"A","text":"作风建设"},{"key":"B","text":"纪律建设"},{"key":"C","text":"制度建设"},{"key":"D","text":"廉政建设"}],"answer":["A","B","C","D"],"explanation":"新时代党的建设总要求明确了“5+2”总体布局：以党的政治建设为统领，全面推进党的政治建设、思想建设、组织建设、作风建设、纪律建设，把制度建设贯穿其中，深入推进反腐败斗争（廉政建设是其重要内容）。"},{"id":1707,"chapter":"第十七章 全面从严治党","type":"multiple","typeText":"多选题","score":10.0,"question":"党的建设的责任主体包括（ ）","options":[{"key":"A","text":"党中央"},{"key":"B","text":"地方各级党委"},{"key":"C","text":"国家机关部门党组(党委)"},{"key":"D","text":"党支部"},{"key":"E","text":"各级党的纪律检查委员会"}],"answer":["A","B","C","D"],"explanation":"党的各级组织，从中央到基层支部，都是管党治党的责任主体，必须承担起主体责任。各级纪委是党内监督的专责机关，履行监督责任，而非广义上的“党的建设”全部责任的直接主体。"},{"id":1708,"chapter":"第十七章 全面从严治党","type":"multiple","typeText":"多选题","score":10.0,"question":"在推进全面从严治党的实践中，我们党不断深化对管党治党规律的认识，形成了一系列重要经验。下列选项哪些属于这些重要经验。（ ）","options":[{"key":"A","text":"坚持思想建党与制度建党相统一"},{"key":"B","text":"坚持使命引领和问题导向相统一"},{"key":"C","text":"坚持抓'关键少数'和管'绝大多数'相统一"},{"key":"D","text":"坚持严格管理和关心信任相统一"}],"answer":["A","B","C","D"],"explanation":"这些“相统一”是党的十八大以来全面从严治党实践经验的深刻总结，体现了我们党在管党治党上系统施治、标本兼治的辩证思维和方法论。"},{"id":1709,"chapter":"第十七章 全面从严治党","type":"multiple","typeText":"多选题","score":10.0,"question":"发挥党的政治建设的统领作用，必须做到( ）","options":[{"key":"A","text":"把准政治方向"},{"key":"B","text":"站稳政治立场"},{"key":"C","text":"营造良好政治生态"},{"key":"D","text":"提高政治能力"}],"answer":["A","B","C","D"],"explanation":"发挥政治建设的统领作用是一个系统工程，要求从方向、立场、生态、能力等多方面协同发力，确保党在政治上的先进性和纯洁性。"},{"id":1710,"chapter":"第十七章 全面从严治党","type":"multiple","typeText":"多选题","score":10.0,"question":"习近平指出:'我们党作为世界上最大的马克思主义执政党，要始终赢得人民拥护、巩固长期执政地位，必须时刻保持解决大党独有难题的清醒和坚定'。解决大党独有难题必须做到始终不忘初心，牢记使命;始终统一思想、统一意志、统一行动;始终具备强大的执政能力和领导水平( ）","options":[{"key":"A","text":"始终保持干事创业精神状态"},{"key":"B","text":"始终能够及时发现和解决自身存在的问题"},{"key":"C","text":"始终保持风清气正的政治生态"},{"key":"D","text":"始终保持同人民群众的血肉联系"}],"answer":["A","B","C"],"explanation":"本题考察对“解决大党独有难题”具体内涵（即“六个如何始终”）的掌握。选项A、B、C分别对应其中的三个“始终”。选项D“始终保持同人民群众的血肉联系”是党的根本宗旨和最大政治优势，是党的性质和初心使命的体现，也是解决所有问题的力量源泉，但它并非“六个如何始终”中列出的具体难题表述。原文的“六个如何始终”包括：如何始终不忘初心、牢记使命，如何始终统一思想、统一意志、统一行动，如何始终具备强大的执政能力和领导水平，如何始终保持干事创业精神状态，如何始终能够及时发现和解决自身存在的问题，如何始终保持风清气正的政治生态。"}];
